/* =====================  Physics interview practice  =====================
   Open-ended questions in the style used at Oxford physics interviews.
   These are written for this app (not copied from Oxford), each with
   progressive hints and a worked answer. Official material is linked, not copied. */

const PHY_TOPICS=['Estimation','Mechanics','Maths and graphs','Waves and optics','Electricity and magnetism','Thermal physics','Gravity and astrophysics','Everyday physics'];

const PHY=[
/* ---------- Estimation ---------- */
{id:'e1',t:0,l:1,q:'Estimate the mass of the air in the room you are sitting in.',
 h:['Break it into two numbers you can estimate separately: the volume of the room and the density of air.',
    'A typical room might be 5 m × 4 m × 2.5 m. Air density at room conditions is about 1.2 kg/m³. If you did not know that, you could get it from the molar mass of air (≈ 29 g/mol) and the fact that a mole of gas occupies about 24 litres.'],
 a:'<p>Volume ≈ 5 × 4 × 2.5 = 50 m³. Density of air ≈ 1.2 kg/m³ (29 g per 24 litres).</p><p>Mass ≈ 50 × 1.2 ≈ <b>60 kg</b>, roughly the mass of a person, which surprises most people.</p><p>What tutors look for: stating assumptions clearly, sensible round numbers, and a sanity check at the end.</p>'},
{id:'e2',t:0,l:2,q:'Roughly how many atoms are there in your body?',
 h:['Your body is mostly water. Start from your mass.',
    'One mole of water (18 g) contains three atoms per molecule, so the average mass per atom is about 6 g/mol. Avogadro\'s number is 6 × 10²³.'],
 a:'<p>Take 70 kg, treated as water. Average atomic mass ≈ 18/3 = 6 g/mol, so moles of atoms ≈ 70 000 / 6 ≈ 1.2 × 10⁴.</p><p>Atoms ≈ 1.2 × 10⁴ × 6 × 10²³ ≈ <b>7 × 10²⁷</b>.</p><p>Including heavier carbon and oxygen in tissue barely changes the order of magnitude: the answer is "about 10²⁸".</p>'},
{id:'e3',t:0,l:2,q:'How much does the Earth\'s atmosphere weigh?',
 h:['What does atmospheric pressure actually measure?',
    'Pressure at the surface is the weight of the air above each square metre: about 10⁵ Pa. Multiply by the surface area of the Earth (radius ≈ 6400 km).'],
 a:'<p>Surface area = 4πR² ≈ 4π × (6.4 × 10⁶)² ≈ 5 × 10¹⁴ m².</p><p>Total weight = pressure × area ≈ 10⁵ × 5 × 10¹⁴ = 5 × 10¹⁹ N, so the mass is about 5 × 10¹⁹ / 10 ≈ <b>5 × 10¹⁸ kg</b>.</p><p>A neat follow-up: this is about a millionth of the Earth\'s mass (6 × 10²⁴ kg).</p>'},
{id:'e4',t:0,l:2,q:'Estimate the power output of the Sun, using only things you could measure on Earth.',
 h:['How much solar power falls on each square metre at the top of the atmosphere? (It is a little over 1 kW.)',
    'That power is spread evenly over a sphere whose radius is the Earth–Sun distance, 1.5 × 10¹¹ m.'],
 a:'<p>Solar constant ≈ 1.4 kW/m². Sphere area = 4π(1.5 × 10¹¹)² ≈ 2.8 × 10²³ m².</p><p>Power ≈ 1.4 × 10³ × 2.8 × 10²³ ≈ <b>4 × 10²⁶ W</b>.</p><p>You could then ask how long the Sun could shine by burning chemical fuel (thousands of years) versus fusion (billions), which is how nuclear energy was inferred historically.</p>'},
{id:'e5',t:0,l:1,q:'How fast does human hair grow, in metres per second?',
 h:['Think about how often people get haircuts, and how much is cut off.',
    'About 1 cm per month is a reasonable figure. How many seconds are in a month?'],
 a:'<p>About 1 cm per month. A month ≈ 30 × 24 × 3600 ≈ 2.6 × 10⁶ s.</p><p>Speed ≈ 0.01 / 2.6 × 10⁶ ≈ <b>4 × 10⁻⁹ m/s</b>, or about 4 nm per second.</p><p>Fun comparison: that is a few atomic diameters every second.</p>'},
{id:'e6',t:0,l:3,q:'How many of the air molecules from Julius Caesar\'s last breath are in your next breath?',
 h:['You need two numbers: how many molecules are in one breath, and how many are in the whole atmosphere.',
    'A breath is about half a litre, and a mole of gas is about 24 litres. The atmosphere has mass ≈ 5 × 10¹⁸ kg and molar mass ≈ 0.029 kg/mol.',
    'Assume Caesar\'s breath has had 2000 years to mix evenly through the atmosphere. The expected number you inhale is (molecules per breath)² / (molecules in atmosphere).'],
 a:'<p>One breath ≈ 0.5/24 mol ≈ 0.02 mol ≈ 1.2 × 10²² molecules.</p><p>Atmosphere ≈ 5 × 10¹⁸ / 0.029 ≈ 1.7 × 10²⁰ mol ≈ 10⁴⁴ molecules.</p><p>The fraction of the atmosphere that was Caesar\'s breath is 1.2 × 10²² / 10⁴⁴ ≈ 10⁻²². Your breath of 10²² molecules therefore contains about <b>one</b> of his molecules on average.</p><p>Good things to mention: the mixing assumption, and that some molecules (e.g. CO₂, water) are recycled by plants and the sea.</p>'},
{id:'e7',t:0,l:1,q:'Roughly how much energy is stored in an AA battery? Is that a lot?',
 h:['Batteries are labelled with a voltage and sometimes a capacity in milliamp-hours.',
    'An AA cell is 1.5 V with a capacity of about 2000 mAh. Energy = voltage × charge.'],
 a:'<p>Charge = 2 A·h = 2 × 3600 = 7200 C. Energy = 1.5 × 7200 ≈ <b>10⁴ J</b>.</p><p>Comparison: lifting yourself (70 kg) up about 15 m, or a single biscuit (≈ 2 × 10⁵ J) contains twenty times more energy. Chemical fuels are far more energy-dense than batteries.</p>'},

/* ---------- Mechanics ---------- */
{id:'m1',t:1,l:3,q:'Imagine a straight tunnel drilled through the centre of the Earth. You jump in. Describe your motion and estimate how long it takes to reach the other side.',
 h:['Assume uniform density and no air resistance. Inside a uniform sphere, only the mass closer to the centre than you pulls on you.',
    'The enclosed mass scales as r³ and gravity as M/r², so the force is proportional to r. What kind of motion has a restoring force proportional to displacement?',
    'Simple harmonic motion with ω² = g/R. The period is 2π√(R/g).'],
 a:'<p>At radius r, enclosed mass is M(r/R)³, so g(r) = g·r/R. The force points to the centre and is proportional to distance: simple harmonic motion with ω = √(g/R).</p><p>Period T = 2π√(R/g) = 2π√(6.4 × 10⁶ / 9.8) ≈ 2π × 800 ≈ 5000 s ≈ 84 minutes. The trip across is half a period: <b>about 42 minutes</b>.</p><p>Nice extras: you pass the centre at about 8 km/s, and the period equals that of a satellite skimming the surface. In fact the trip takes 42 minutes for <em>any</em> straight tunnel between two points, not just through the centre.</p>'},
{id:'m2',t:1,l:1,q:'Ignoring air resistance, at what angle should you throw a ball to get it as far as possible? What changes if there is air resistance?',
 h:['Split the launch velocity into horizontal and vertical parts. Time in the air depends on the vertical part; distance depends on both.',
    'Range R = v² sin(2θ) / g. When is sin(2θ) largest?'],
 a:'<p>Time of flight = 2v sinθ / g, horizontal speed = v cosθ, so R = 2v² sinθ cosθ / g = v² sin2θ / g. This is maximised at <b>θ = 45°</b>.</p><p>With air resistance, the ball loses speed faster on long, high paths, so the best angle is lower (often 35–40° for a ball). Launching from a height above the landing point also lowers the optimum, which is why shot-putters release at about 37°.</p>'},
{id:'m3',t:1,l:2,q:'You are in a rowing boat on a small pond, holding a heavy rock. You throw the rock into the water. Does the water level of the pond go up, down, or stay the same?',
 h:['While the rock is in the boat, how much water does it displace? (Think about floating.)',
    'A floating object displaces its own weight of water. A sunken object displaces its own volume. Which is bigger for a rock?'],
 a:'<p>In the boat, the rock adds to the floating weight, so it displaces water equal to its <em>weight</em>. Rock is about 2.5 times denser than water, so that is 2.5 times its own volume.</p><p>On the bottom, it displaces only its own <em>volume</em>.</p><p>So less water is displaced afterwards: the level <b>falls</b>, slightly.</p>'},
{id:'m4',t:1,l:2,q:'A solid ball rolls without slipping down a ramp. An identical block slides down an identical, frictionless ramp. Which reaches the bottom first, and why?',
 h:['Use energy conservation. Where does the lost gravitational energy go in each case?',
    'For the rolling ball, some energy goes into spinning. For a solid sphere the rotational energy is (1/5)mv², compared with (1/2)mv² translational.'],
 a:'<p>Sliding block: mgh = ½mv², so v² = 2gh.</p><p>Rolling solid sphere: mgh = ½mv² + ½Iω² with I = (2/5)mr², ω = v/r, giving mgh = (7/10)mv², so v² = (10/7)gh.</p><p>The block is faster at every height, so <b>the sliding block wins</b>. The rolling ball "wastes" 2/7 of its energy on spinning. Notice the answer does not depend on mass or radius, only on the shape (a hollow ball would be slower still).</p>'},
{id:'m5',t:1,l:1,q:'If you can jump 50 cm high on Earth, how high could you jump on the Moon?',
 h:['Your legs give you the same take-off speed on the Moon as on Earth.',
    'The height reached is v²/2g. The Moon\'s surface gravity is about one sixth of Earth\'s.'],
 a:'<p>Same take-off speed v, height h = v²/2g. With g six times smaller, h is <b>six times larger: about 3 m</b>.</p><p>Refinements to mention: "jump height" usually means the rise of your centre of mass; a bulky spacesuit would reduce it a lot; and the time in the air, 2v/g, is also six times longer.</p>'},
{id:'m6',t:1,l:3,q:'A ladder leans against a smooth (frictionless) wall, standing on a rough floor. What is the smallest coefficient of friction that stops it slipping, if it makes angle θ with the floor?',
 h:['Draw the forces: weight at the middle, a horizontal push from the wall, and a normal force plus friction at the floor.',
    'Balance horizontal and vertical forces, then take moments about the foot of the ladder to avoid unknowns there.'],
 a:'<p>Let the ladder have length L and weight W. Floor: normal N, friction F. Wall: horizontal force P.</p><p>Vertical: N = W. Horizontal: F = P. Moments about the foot: P·L sinθ = W·(L/2) cosθ, so P = W / (2 tanθ).</p><p>No slip needs F ≤ μN, i.e. <b>μ ≥ 1 / (2 tanθ)</b>.</p><p>Check: a steep ladder (θ near 90°) needs almost no friction; a nearly flat one needs huge friction. That matches experience.</p>'},
{id:'m7',t:1,l:1,q:'Gravity on the International Space Station is about 90% as strong as on the ground. So why do astronauts float?',
 h:['What is the ISS actually doing?',
    'Think about what you feel in a lift whose cable has snapped.'],
 a:'<p>At 400 km altitude, g is about (6371/6771)² ≈ 0.88 of its surface value. The astronauts are not weightless in the sense of "no gravity".</p><p>They and the station are both in <b>free fall</b>, moving sideways fast enough (about 7.7 km/s) that they keep missing the Earth. Everything falls together, so nothing pushes on anything else, and that is what we feel as weightlessness.</p>'},

/* ---------- Maths and graphs ---------- */
{id:'g1',t:2,l:2,q:'Sketch the graph of y = x sin x.',
 h:['Is the function odd, even, or neither?',
    'Where is it zero? Between which two lines does it oscillate?'],
 a:'<p><b>Even</b> (x and sin x are both odd, so the product is even): the graph is symmetric about the y-axis.</p><p>Zero at x = 0 (where it touches zero like x², since x sin x ≈ x² near 0) and at every x = nπ.</p><p>It oscillates between the lines y = x and y = −x, touching them near x = (n + ½)π. So it is a wave whose amplitude grows linearly: a "widening funnel" shape.</p>'},
{id:'g2',t:2,l:2,q:'Sketch y = x e<sup>−x</sup>. Where is its maximum?',
 h:['What happens as x → +∞ and x → −∞?',
    'Differentiate with the product rule and set the derivative to zero.'],
 a:'<p>For large positive x, e<sup>−x</sup> beats x, so y → 0 from above. For large negative x, both factors grow in size with x negative, so y → −∞. It passes through the origin.</p><p>dy/dx = e<sup>−x</sup>(1 − x) = 0 at <b>x = 1</b>, where y = 1/e ≈ 0.37.</p><p>There is also a point of inflection at x = 2 (second derivative e<sup>−x</sup>(x − 2) = 0).</p>'},
{id:'g3',t:2,l:3,q:'Without a calculator, which is bigger: e<sup>π</sup> or π<sup>e</sup>?',
 h:['Take logarithms. Compare π ln e with e ln π.',
    'Dividing by eπ, you are comparing (ln x)/x at x = e and x = π. Where is (ln x)/x largest?'],
 a:'<p>Compare ln(e<sup>π</sup>) = π with ln(π<sup>e</sup>) = e ln π. Divide both by eπ: compare 1/e = (ln e)/e with (ln π)/π.</p><p>f(x) = (ln x)/x has f′(x) = (1 − ln x)/x², which is zero at x = e: f has its maximum at e. So (ln π)/π &lt; (ln e)/e.</p><p>Therefore <b>e<sup>π</sup> &gt; π<sup>e</sup></b>. (Numerically 23.1 vs 22.5.)</p>'},
{id:'g4',t:2,l:2,q:'Does 1 + 1/2 + 1/3 + 1/4 + … add up to a finite number?',
 h:['Try grouping the terms: 1/3 + 1/4, then 1/5 + … + 1/8, and so on.',
    'Each group is at least as big as one half.'],
 a:'<p>Group: 1/3 + 1/4 &gt; 2 × 1/4 = 1/2. Then 1/5 + 1/6 + 1/7 + 1/8 &gt; 4 × 1/8 = 1/2. Each doubling block adds more than 1/2.</p><p>Infinitely many halves means the sum <b>diverges</b>, even though the terms go to zero. It grows very slowly, like ln n: a million terms only sum to about 14.4.</p><p>Contrast with 1 + 1/4 + 1/9 + … which converges (to π²/6).</p>'},
{id:'g5',t:2,l:3,q:'Sketch y = sin(1/x).',
 h:['What happens for large |x|? (1/x is small.)',
    'As x approaches 0, how fast does 1/x change? How many oscillations are there between x = 0.01 and x = 0.02?'],
 a:'<p>For large |x|, sin(1/x) ≈ 1/x: the graph approaches 0, from above on the right and below on the left. The function is <b>odd</b>.</p><p>The largest value 1 occurs last at x = 2/π ≈ 0.64. Zeros sit at x = 1/(nπ), which crowd together near 0.</p><p>Close to the origin the graph oscillates between −1 and +1 infinitely often, ever faster. It is undefined at x = 0 and has no limit there.</p>'},
{id:'g6',t:2,l:2,q:'How many zeros are there at the end of 100! (100 factorial)?',
 h:['A trailing zero comes from a factor of 10 = 2 × 5. Which is rarer among the numbers 1 to 100: factors of 2 or of 5?',
    'Count multiples of 5, then remember that 25, 50, 75 and 100 each contribute an extra 5.'],
 a:'<p>Factors of 2 are plentiful, so count factors of 5.</p><p>Multiples of 5 up to 100: 20. Multiples of 25: 4 more. Total <b>24</b>.</p><p>General rule: ⌊n/5⌋ + ⌊n/25⌋ + ⌊n/125⌋ + …</p>'},
{id:'g7',t:2,l:3,q:'Differentiate y = x<sup>x</sup>.',
 h:['Neither the power rule nor the exponential rule applies directly, because both base and exponent vary.',
    'Take logs first: ln y = x ln x, then differentiate both sides.'],
 a:'<p>ln y = x ln x. Differentiating: (1/y)(dy/dx) = ln x + 1.</p><p>So <b>dy/dx = x<sup>x</sup>(ln x + 1)</b>.</p><p>Follow-up: the minimum of x<sup>x</sup> for x &gt; 0 is at ln x = −1, i.e. x = 1/e.</p>'},

/* ---------- Waves and optics ---------- */
{id:'w1',t:3,l:2,q:'Why is the sky blue? And why are sunsets red?',
 h:['Sunlight contains all colours. Something in the atmosphere scatters some colours more than others.',
    'Scattering by molecules much smaller than the wavelength (Rayleigh scattering) is proportional to 1/λ⁴.'],
 a:'<p>Air molecules scatter short wavelengths much more strongly: intensity ∝ 1/λ⁴, so blue (450 nm) is scattered about 4–5 times more than red (700 nm). Looking away from the Sun, you see this scattered light, so the sky looks blue.</p><p>Why not violet? The Sun emits less violet, some is absorbed high up, and our eyes are less sensitive to it.</p><p>At sunset, light travels through far more atmosphere to reach you. Most of the blue is scattered out of the direct beam on the way, leaving <b>red and orange</b>.</p>'},
{id:'w2',t:3,l:2,q:'Why does a rainbow form an arc, and where must the Sun be when you see one?',
 h:['Light enters a spherical raindrop, reflects once off the back, and comes out again. The angle it is deviated by has a "preferred" value.',
    'That angle is about 42° for red light, measured from the point directly opposite the Sun.'],
 a:'<p>Light refracts into a drop, reflects once inside and refracts out. The returning light piles up near a deviation of about 138°, i.e. <b>42° from the antisolar point</b> (the shadow of your head). Different colours have slightly different angles because of dispersion: red on the outside (42°), violet inside (40°).</p><p>All drops that send light to your eye at 42° lie on a cone around your line of sight, so you see a circle, cut off by the ground into an arc.</p><p>The Sun must be <b>behind you</b> and fairly low: if it is higher than 42°, the whole bow is below the horizon. From a plane you can see a full circle.</p>'},
{id:'w3',t:3,l:1,q:'Why does a straw look bent where it enters a glass of water?',
 h:['Light from the underwater part of the straw changes direction as it crosses from water into air.',
    'Your brain assumes light travels in straight lines.'],
 a:'<p>Light from the submerged part refracts away from the normal as it leaves water (n ≈ 1.33) into air. Your eye traces the rays back in straight lines, so the underwater part appears higher than it is.</p><p>Looking straight down, objects appear at about <b>3/4 of their real depth</b> (real depth ÷ n). So the straw appears bent upwards at the surface.</p>'},
{id:'w4',t:3,l:2,q:'Why can you hear someone talking around a corner, but you cannot see them?',
 h:['Both sound and light are waves. What determines how much a wave spreads after passing through a gap?',
    'Compare the wavelength of each wave with the size of a doorway.'],
 a:'<p>Waves spread significantly (diffract) when the gap is comparable to their wavelength.</p><p>Speech has wavelengths around 0.3–3 m (λ = v/f with v = 340 m/s), similar to a doorway, so it diffracts strongly round corners. Visible light has λ ≈ 500 nm, about a million times smaller than the door, so it barely diffracts and travels in effectively straight lines.</p><p>Bonus: low notes go round corners better than high ones, which is why you hear the bass from a distant party.</p>'},
{id:'w5',t:3,l:1,q:'Why does a guitar string sound higher when you tighten it or press it against a fret?',
 h:['The note is set by the frequency of the standing wave on the string.',
    'The fundamental has a wavelength of twice the vibrating length, and wave speed on a string is √(T/μ), where T is tension and μ is mass per unit length.'],
 a:'<p>Fundamental frequency f = v/2L = (1/2L)√(T/μ).</p><p><b>Tightening</b> increases T, so f rises. <b>Pressing a fret</b> shortens L, so f rises. Thicker strings (larger μ) give lower notes.</p><p>Each fret shortens the string by a factor of 2<sup>1/12</sup>, so 12 frets halve the length and raise the note by an octave.</p>'},
{id:'w6',t:3,l:2,q:'How do noise-cancelling headphones work? Why are they better at blocking a low hum than a sudden clap?',
 h:['A microphone listens to the outside noise. What could the speaker play to cancel it?',
    'Producing the exact inverse wave takes processing time. Is that delay more of a problem for long or short wavelengths?'],
 a:'<p>A microphone picks up ambient sound, and the electronics play the same wave inverted (180° out of phase). The two superpose and <b>interfere destructively</b>.</p><p>Steady, low-frequency sound is predictable and has long wavelengths, so a small timing delay is a tiny fraction of a cycle. Sudden or high-pitched sounds change too quickly to predict, and a fixed delay is a large fraction of their period, so cancellation fails. The ear cups block high frequencies passively instead.</p>'},

/* ---------- Electricity and magnetism ---------- */
{id:'x1',t:4,l:1,q:'Why can a bird sit safely on a high-voltage power line?',
 h:['Current flows because of a potential difference. What is the potential difference between the bird\'s two feet?',
    'The wire between its feet has a tiny resistance compared with the bird\'s body.'],
 a:'<p>Both feet touch the same wire, a few centimetres apart. The voltage drop along that short length of thick copper is minute (millivolts), so almost no current goes through the bird.</p><p>Danger comes from touching two things at different potentials at once: a wire and the pylon, or two wires. That is why large birds with wide wingspans are at risk.</p>'},
{id:'x2',t:4,l:2,q:'If you drop a strong magnet down a vertical copper pipe, it falls very slowly. Why? Copper is not magnetic.',
 h:['As the magnet falls, the magnetic flux through each ring of the pipe is changing.',
    'A changing flux induces a current (Faraday). Which way does that current\'s own magnetic field push (Lenz)?'],
 a:'<p>The falling magnet changes the flux through rings of copper above and below it, inducing circulating <b>eddy currents</b>. By Lenz\'s law these currents create fields that oppose the change: the ring below repels the magnet and the ring above attracts it, both slowing it down.</p><p>The braking force grows with speed, so the magnet quickly reaches a slow terminal velocity. Its lost gravitational energy becomes heat in the pipe. The same principle is used in train and roller-coaster brakes.</p>'},
{id:'x3',t:4,l:2,q:'How does a microwave oven heat food?',
 h:['Water molecules have a permanent electric dipole.',
    'The oven fills with an electromagnetic wave oscillating at about 2.45 GHz. What does an oscillating electric field do to a dipole?'],
 a:'<p>The oven\'s field oscillates billions of times a second. Polar molecules, mainly water, keep trying to rotate to line up with it. Their jostling against neighbouring molecules converts that motion into random thermal energy: <b>dielectric heating</b>.</p><p>Common misconception: it is not a resonance of the water molecule. 2.45 GHz is chosen as a practical compromise for penetration depth (a few cm) and licensing. Dry foods and ice heat poorly because their molecules cannot rotate freely.</p>'},
{id:'x4',t:4,l:1,q:'After rubbing a balloon on your hair, it sticks to a neutral wall. How can a charged object attract something with no charge?',
 h:['The wall has no net charge, but its charges can still move a little.',
    'Which charges in the wall end up closer to the balloon?'],
 a:'<p>The balloon picks up extra electrons (negative). Near it, the molecules of the wall become slightly <b>polarised</b>: their positive ends shift towards the balloon and negative ends away.</p><p>The attracted positive charges are closer than the repelled negative ones, and electric force falls with distance, so attraction wins. This is <b>induced polarisation</b>, the same reason a charged comb picks up bits of paper.</p>'},
{id:'x5',t:4,l:1,q:'Why is electricity sent across the country at hundreds of thousands of volts?',
 h:['The power delivered is P = VI. Energy is lost as heat in the cables.',
    'The power lost in a cable of resistance R is I²R.'],
 a:'<p>For a fixed power P = VI, raising the voltage lowers the current. Cable losses are I²R, so <b>10 times the voltage means 100 times less heating loss</b>.</p><p>Transformers make it easy to step voltage up for transmission and back down for homes. That is a big reason the grid uses alternating current.</p>'},

/* ---------- Thermal physics ---------- */
{id:'h1',t:5,l:1,q:'A metal bench and a wooden bench have been outside all night at the same temperature. Why does the metal one feel much colder to sit on?',
 h:['Your skin senses heat flow, not temperature directly.',
    'Which material carries heat away from your skin faster?'],
 a:'<p>Both are at the same temperature, below your skin temperature. Metal has a much higher thermal conductivity, so it draws heat from your skin quickly and your skin surface cools. Wood is a poor conductor, so the contact point warms up to near skin temperature almost immediately.</p><p>Your nerves sense the rate of heat loss, so metal <b>feels</b> colder. On a hot day, the metal bench feels hotter for the same reason.</p>'},
{id:'h2',t:5,l:2,q:'Why does ice float, and why does that matter for life on Earth?',
 h:['Floating means the solid is less dense than the liquid. That is unusual. What is special about how water molecules bond?',
    'Think about what happens to a lake in winter if ice were denser and sank.'],
 a:'<p>In ice, hydrogen bonds lock water molecules into an open hexagonal lattice, which takes up more space than the disordered liquid. Ice is about 9% less dense, so it floats.</p><p>Lakes freeze from the top down. The ice layer insulates the water below, which stays liquid (near 4 °C, where water is densest). If ice sank, lakes would fill with ice from the bottom up and could freeze solid, making aquatic life much harder.</p>'},
{id:'h3',t:5,l:1,q:'Why does food cook faster in a pressure cooker?',
 h:['What sets the temperature of boiling water?',
    'Boiling happens when the vapour pressure of the water equals the surrounding pressure.'],
 a:'<p>Water boils when its vapour pressure equals the pressure above it. Sealing the pot raises the pressure to about 2 atmospheres, which pushes the boiling point up to about <b>120 °C</b>.</p><p>Cooking chemistry speeds up strongly with temperature, so food cooks in roughly a third of the time. On a high mountain the opposite happens: water boils below 100 °C and pasta takes longer.</p>'},
{id:'h4',t:5,l:2,q:'Could you cool a sealed, insulated room by leaving the fridge door open?',
 h:['A fridge is a heat pump: it moves heat from inside to the coils at the back. Where are both of those now?',
    'Consider the room plus fridge as one system. What energy goes into it?'],
 a:'<p>No: the room <b>warms up</b>. With the door open, the fridge just moves heat from one part of the room to another. Meanwhile it draws electrical energy, which all ends up as heat in the room.</p><p>Energy conservation for the sealed room: the only energy flow in is electrical work, so its temperature must rise. An air conditioner works because it dumps its heat outside.</p>'},
{id:'h5',t:5,l:2,q:'Why can you put your hand into a 200 °C oven for a moment, but you would be badly scalded by 100 °C water?',
 h:['What matters is how quickly heat flows into your hand, not just the temperature.',
    'Compare the density, heat capacity and thermal conductivity of air and water. Is there anything else hot steam or water can do?'],
 a:'<p>Air is about a thousand times less dense than water and a poor conductor, so it can deliver heat only slowly. A thin layer of air next to your skin cools down quickly.</p><p>Water conducts about 25 times better and has huge heat capacity per volume, so it keeps delivering heat. Steam is even worse: when it condenses on your skin it releases latent heat (2.3 MJ/kg).</p>'},
{id:'h6',t:5,l:1,q:'Why does blowing on hot soup cool it down?',
 h:['Soup cools mainly by evaporation from its surface.',
    'What does the air just above the soup contain, and what does blowing do to it?'],
 a:'<p>Evaporation removes the fastest molecules, taking latent heat with them. Above the soup, a layer of humid air builds up and slows further evaporation.</p><p>Blowing <b>replaces that humid layer with drier air</b>, so evaporation speeds up. It also increases convective heat loss. (Your breath is warmer than the room, but that matters much less.)</p>'},

/* ---------- Gravity and astrophysics ---------- */
{id:'a1',t:6,l:2,q:'Why do we always see the same face of the Moon?',
 h:['It is not because the Moon does not spin. How long does one spin take compared with one orbit?',
    'The Earth\'s gravity raises tidal bulges on the Moon. What happens if they are not lined up with the Earth?'],
 a:'<p>The Moon spins exactly once per orbit (about 27 days), so the same side always faces us: it is <b>tidally locked</b>.</p><p>Early on it spun faster. Earth\'s gravity stretched it into a slight bulge; friction dragged the bulge ahead of the Earth–Moon line, and Earth\'s pull on the misaligned bulge created a torque that slowed the spin until it matched the orbit. The same process is slowly lengthening Earth\'s day.</p>'},
{id:'a2',t:6,l:2,q:'How could you work out the mass of the Earth?',
 h:['You know g at the surface and the radius of the Earth. What else do you need?',
    'Newton\'s law gives g = GM/R². G was measured in the lab by Cavendish.'],
 a:'<p>g = GM/R², so M = gR²/G = 9.8 × (6.4 × 10⁶)² / (6.7 × 10⁻¹¹) ≈ <b>6 × 10²⁴ kg</b>.</p><p>The hard part historically was G, measured by Cavendish with a torsion balance in 1798 (sometimes described as "weighing the Earth"). Alternatively, the Moon\'s orbit gives GM directly from Kepler\'s third law. Dividing by the volume gives an average density of about 5500 kg/m³, twice that of surface rock, so the core must be dense.</p>'},
{id:'a3',t:6,l:3,q:'Why are there two high tides a day, not one?',
 h:['The tide is caused not by the Moon\'s gravity itself, but by how its strength varies across the Earth.',
    'The near side is pulled more than the centre; the centre is pulled more than the far side. What does each look like from the Earth\'s point of view?'],
 a:'<p>Relative to the Earth\'s centre, water on the near side is pulled towards the Moon a bit more strongly, and water on the far side a bit less strongly. Both stretch the oceans along the Earth–Moon line, making <b>two bulges</b> on opposite sides.</p><p>The Earth turns under both bulges each day, giving two high tides about 12 h 25 min apart (the extra 25 min because the Moon moves along its orbit). The Sun adds a smaller tidal effect: spring tides happen when the two line up.</p>'},
{id:'a4',t:6,l:1,q:'How long does sunlight take to reach us? What does that tell you about looking at the night sky?',
 h:['Earth–Sun distance ≈ 1.5 × 10¹¹ m; speed of light ≈ 3 × 10⁸ m/s.','If light takes time to travel, are you seeing a distant star as it is now, or as it was?'],
 a:'<p>t = 1.5 × 10¹¹ / 3 × 10⁸ = 500 s ≈ <b>8 minutes 20 seconds</b>.</p><p>Every observation is of the past. The nearest stars appear as they were years ago; distant galaxies as they were millions or billions of years ago. That is how astronomers can study the early universe directly.</p>'},
{id:'a5',t:6,l:2,q:'If the Sun suddenly collapsed into a black hole of the same mass, what would happen to the Earth\'s orbit?',
 h:['Outside a spherical mass, how does gravity depend on its size?',
    'Newton\'s shell theorem: a spherical body attracts external objects as if all its mass were at its centre.'],
 a:'<p>Nothing would change about the orbit. Outside the Sun, its gravity depends only on its mass and our distance, not its radius. The Earth would keep orbiting once a year.</p><p>Of course, it would get very cold and dark. A black hole of the Sun\'s mass would be only about 6 km across. Black holes only "suck things in" if you get very close.</p>'},
{id:'a6',t:6,l:3,q:'Why are planets round, but small asteroids are lumpy and potato-shaped?',
 h:['Think about a competition between two things: gravity and the strength of rock.',
    'The pressure from gravity at the centre of a body grows roughly as density² × radius². At what size does it beat the strength of rock?'],
 a:'<p>Gravity pulls every bit of a body towards the centre, which would make it a sphere. Rock resists deformation with a strength of roughly 10⁷–10⁸ Pa.</p><p>Central pressure ~ Gρ²R². With ρ ≈ 3000 kg/m³, this reaches 10⁷–10⁸ Pa when R is a few hundred kilometres. Bodies larger than <b>about 200–400 km</b> are crushed into spheres; smaller ones keep irregular shapes. Ice is weaker, so icy moons become round at smaller sizes.</p>'},

/* ---------- Everyday physics ---------- */
{id:'d1',t:7,l:1,q:'Why does a spinning ice skater speed up when they pull their arms in? Where does the extra kinetic energy come from?',
 h:['Is there any external torque on the skater?',
    'Angular momentum L = Iω is conserved. Rotational kinetic energy is L²/2I.'],
 a:'<p>With no external torque, angular momentum Iω is conserved. Pulling the arms in reduces the moment of inertia I, so ω increases.</p><p>Kinetic energy L²/2I <b>increases</b>. The extra energy comes from the work the skater\'s muscles do pulling their arms inwards against the "outward" tendency of the spinning arms.</p>'},
{id:'d2',t:7,l:2,q:'Why does a kettle get noisy and then quieter just before it boils?',
 h:['Bubbles first form at the hot element at the bottom. What happens when they rise into cooler water above?',
    'Steam bubbles that suddenly condense collapse violently.'],
 a:'<p>Early on, steam bubbles form at the element but rise into cooler water, where the steam condenses and the bubbles <b>collapse</b> with a sharp snap. Thousands of these give the loud hissing roar.</p><p>As the whole kettle approaches 100 °C, bubbles survive all the way to the surface without collapsing. The violent implosions stop, so it gets quieter, then you hear the gentler bubbling of a full boil.</p>'},
{id:'d3',t:7,l:2,q:'Should you walk or run in the rain to stay drier?',
 h:['Split the rain hitting you into rain landing on your head and shoulders, and rain you walk into with your front.',
    'How does each part depend on your speed, for a fixed distance?'],
 a:'<p>Rain on <b>top</b> of you is proportional to the time spent in the rain, so going faster reduces it.</p><p>Rain hitting your <b>front</b> is the rain in the volume you sweep through, which depends only on the distance, not your speed.</p><p>So overall, <b>run</b>. (If the wind blows rain at your back, there is an ideal speed matching the wind.) Good answers set up a simple model before concluding.</p>'},
{id:'d4',t:7,l:3,q:'A shower curtain blows inwards towards you when you turn on the shower. Why?',
 h:['There is no single agreed answer; tutors want to see you propose and test explanations.',
    'Candidates: hot air rising (convection), moving air and Bernoulli\'s principle, and a vortex set up by the spray.'],
 a:'<p>Possible explanations:</p><p>• <b>Convection</b>: hot water warms the air, which rises and draws in air at the bottom. But the effect also happens with cold water, so this cannot be the whole story.</p><p>• <b>Bernoulli</b>: the spray drags air along, and faster-moving air is at lower pressure, so the curtain is pushed in.</p><p>• <b>Vortex</b>: computer simulations (2001) suggest the spray drives a rotating vortex with a low-pressure core that pulls the curtain inwards.</p><p>The point is to reason: suggest an experiment to tell them apart, such as using cold water to rule out convection.</p>'}
];

/* ---------- follow-up questions ----------
   Tutors rarely stop at the first answer. Each entry: [follow-up question, short answer]. */
const PHY_FOLLOW={
 e1:[['How many molecules of air is that?','60 kg ÷ 0.029 kg/mol ≈ 2000 mol, so about 2000 × 6 × 10²³ ≈ 10²⁷ molecules.'],
     ['The room is heated from 15 °C to 25 °C at constant pressure. Roughly how much air leaves?','At fixed pressure and volume the mass inside scales as 1/T. 1 − 288/298 ≈ 3%, so about 2 kg leaves through gaps.']],
 e2:[['Roughly how many cells are in your body?','Body volume ≈ 0.07 m³; a typical cell is (10 μm)³ = 10⁻¹⁵ m³, giving ~10¹³–10¹⁴. Careful counts give about 3 × 10¹³, many of them small red blood cells.'],
     ['So how many atoms are in a typical cell?','7 × 10²⁷ ÷ 3 × 10¹³ ≈ 2 × 10¹⁴ atoms.']],
 e3:[['If the atmosphere had sea-level density all the way up, how thick would it be?','h = P/(ρg) = 10⁵/(1.2 × 9.8) ≈ 8.5 km, about the height of Everest. This is the "scale height".'],
     ['Why does pressure fall roughly exponentially with height?','dP/dh = −ρg, and for an isothermal ideal gas ρ ∝ P. So dP/dh ∝ −P, giving P = P₀e^(−h/H) with H = kT/mg ≈ 8 km.']],
 e4:[['How much mass does the Sun lose each second?','Δm = P/c² = 4 × 10²⁶ / 9 × 10¹⁶ ≈ 4 × 10⁹ kg/s, about four million tonnes a second.'],
     ['Estimate the Sun\'s surface temperature (radius 7 × 10⁸ m).','σT⁴ = P/(4πR²) ≈ 4 × 10²⁶ / 6 × 10¹⁸ ≈ 6 × 10⁷ W/m², so T⁴ ≈ 10¹⁵ and T ≈ 5800 K.']],
 e5:[['You have about 10⁵ hairs. What total length do you grow per day?','10⁵ × 1 cm/month ≈ 1 km/month, or roughly 35 m a day.'],
     ['Roughly what mass of hair protein is that per day?','Hair diameter ≈ 70 μm gives cross-section ≈ 4 × 10⁻⁹ m². 35 m × 4 × 10⁻⁹ m² × 1300 kg/m³ ≈ 0.2 g per day.']],
 e6:[['Which assumption is weakest?','Mixing is fine: air mixes around the globe within a year or two. The bigger issue is exchange: oxygen and CO₂ are recycled by plants and the oceans. Nitrogen (78%) is almost inert, so the answer stays about one.'],
     ['Would the answer be the same for a breath someone took yesterday?','No. It takes a year or two for a breath to spread through the whole atmosphere, especially between hemispheres, so it would not yet be evenly mixed.']],
 e7:[['Compare a battery\'s energy per kilogram with petrol.','An AA is about 23 g, so 10⁴ J / 0.023 kg ≈ 0.4 MJ/kg. Petrol is about 46 MJ/kg, roughly 100 times more.'],
     ['How long could one AA run a 0.1 W LED?','10⁴ J / 0.1 W = 10⁵ s, a little over a day.']],
 m1:[['What is your maximum speed, and where?','At the centre: v = ωR = √(gR) = √(9.8 × 6.4 × 10⁶) ≈ 7.9 km/s, the same as low orbital speed.'],
     ['The real Earth is denser in the middle. Is the real trip faster or slower?','Faster. Gravity stays roughly constant (even rises slightly) for the first ~3000 km down, so you speed up more. Realistic models give about 38 minutes.']],
 m2:[['Show that 30° and 60° give the same range.','R ∝ sin2θ, and sin60° = sin120°. Any pair of angles adding to 90° gives the same range.'],
     ['Throwing from the top of a cliff, is the best angle above or below 45°?','Below. The extra fall height gives more time in the air, so it pays to put more of the speed into horizontal motion.']],
 m3:[['What if you throw a block of wood (which floats) overboard instead?','No change. Floating in the boat or in the water, it displaces its own weight of water either way.'],
     ['What happens to the boat\'s height in the water after the rock goes over?','The boat rises: it now displaces less water because it carries less weight.']],
 m4:[['Rank by speed at the bottom: hoop, solid sphere, solid cylinder, hollow sphere.','Fastest has the smallest I/mr²: solid sphere (2/5), solid cylinder (1/2), hollow sphere (2/3), hoop (1).'],
     ['Rolling needs friction, so why is no energy lost to it?','Static friction acts at the contact point, which is momentarily at rest, so it does no work. It only converts energy between translation and rotation.']],
 m5:[['How small would an asteroid have to be for you to jump off it entirely?','Take-off speed ≈ 3 m/s. Escape speed = R√(8πGρ/3); with ρ ≈ 2000 kg/m³ that is about 10⁻³ × R. So R ≈ 3 km or less.'],
     ['Why did Apollo astronauts hop rather than walk?','Walking is like an inverted pendulum, with maximum speed about √(gL). On the Moon that is only about 1 m/s, so bounding was faster and easier.']],
 m6:[['A person climbs the ladder. Where is it most likely to slip?','Near the top. Their weight then acts further from the foot, increasing the torque and the friction needed.'],
     ['What changes if the wall is also rough?','Wall friction carries some of the weight, so less floor friction is needed. With coefficients μ₁ (floor) and μ₂ (wall), the limiting angle obeys tanθ = (1 − μ₁μ₂)/(2μ₁).']],
 m7:[['What is the period of the ISS\'s orbit?','T = 2π√(r³/GM) with r ≈ 6.8 × 10⁶ m gives about 5500 s, roughly 92 minutes: 16 sunrises a day.'],
     ['Why does the ISS need regular boosts?','The very thin atmosphere at 400 km causes drag. It drops to a lower orbit (and, counter-intuitively, speeds up), so engines periodically raise it again.']],
 g1:[['Where exactly are the turning points?','dy/dx = sin x + x cos x = 0, i.e. tan x = −x. These approach x = (n + ½)π for large x.'],
     ['Now sketch y = (sin x)/x.','Even, equal to 1 at x = 0 (the limit), zeros at x = nπ (n ≠ 0), and oscillating with an envelope ±1/x that dies away.']],
 g2:[['Evaluate the integral of x e^(−x) from 0 to ∞.','By parts: [−x e^(−x)] + ∫e^(−x) dx = 0 + 1 = 1.'],
     ['Sketch y = x² e^(−x).','Touches zero at the origin (minimum), maximum at x = 2 with value 4/e² ≈ 0.54, tends to 0 as x → ∞ and to +∞ as x → −∞.']],
 g3:[['Which is bigger: 2¹⁰⁰ or 100¹⁰?','100¹⁰ = 10²⁰ ≈ 2^66.4 (using 2¹⁰ ≈ 10³), so 2¹⁰⁰ is far bigger.'],
     ['Find two different whole numbers with xʸ = yˣ.','2 and 4: 2⁴ = 4² = 16. It is the only such pair of positive integers.']],
 g4:[['Roughly how many terms do you need for the sum to exceed 10?','The sum ≈ ln n + 0.577, so ln n ≈ 9.4 and n ≈ 12 000.'],
     ['You stack identical books at the edge of a table. How far can the top one overhang?','With n books the best overhang is ½(1 + ½ + ⅓ + … + 1/n) book lengths. That grows without limit, though very slowly.']],
 g5:[['Sketch y = x sin(1/x).','It oscillates between the lines y = x and y = −x, so it is squeezed to 0 at the origin. It tends to 1 as x → ±∞ (since sin u/u → 1).'],
     ['How many zeros does sin(1/x) have between x = 0.01 and x = 0.1?','Zeros at x = 1/(nπ) need 10 ≤ nπ ≤ 100, so n = 4 to 31: 28 zeros.']],
 g6:[['How many zeros are at the end of 1000!?','200 + 40 + 8 + 1 = 249.'],
     ['Roughly how many digits does 100! have?','Stirling: log₁₀(n!) ≈ n log₁₀(n/e) + ½log₁₀(2πn) ≈ 156.6 + 1.4 = 158.0, so 158 digits.']],
 g7:[['What is the limit of xˣ as x → 0 from above?','xˣ = e^(x ln x), and x ln x → 0, so the limit is 1.'],
     ['Integrate ln x.','By parts with u = ln x, dv = dx: x ln x − x + C.']],
 w1:[['Why are clouds white?','Water droplets are much larger than the wavelength of light, so they scatter all colours about equally (Mie scattering).'],
     ['What colour is the daytime sky on the Moon, and on Mars?','Black on the Moon, which has no atmosphere. Mars has a thin, dusty atmosphere: a butterscotch sky by day and bluish sunsets, because the fine dust scatters blue light forwards.']],
 w2:[['Why is the sky darker just outside the bow than inside it?','Light reflected once inside drops can only be deviated to angles inside 42°, so the inside is brighter. The dim band is Alexander\'s dark band.'],
     ['Where does the fainter second rainbow come from?','Two internal reflections. It appears at about 51°, with the colours reversed.']],
 w3:[['A swimming pool is 2 m deep. How deep does it look from directly above?','Real depth ÷ n = 2/1.33 ≈ 1.5 m.'],
     ['What is the critical angle for light going from water to air, and what does a diver see looking up?','sin c = 1/1.33, so c ≈ 49°. The whole sky is squeezed into a bright circle of half-angle 49° overhead (Snell\'s window); outside it the surface acts as a mirror.']],
 w4:[['Why do ships use low-pitched foghorns?','Low frequencies diffract round obstacles more and are absorbed less by air, so they carry further.'],
     ['Why can\'t an optical microscope see individual atoms?','Resolution is limited to about half the wavelength, ~200 nm, while atoms are ~0.1 nm. You need much shorter wavelengths, e.g. electrons.']],
 w5:[['If you touch the string lightly at its midpoint and pluck, what do you hear?','A note an octave higher. Touching forces a node at the middle, which kills the fundamental and leaves the second harmonic.'],
     ['Why does a guitar need a hollow body?','A thin string moves very little air. The string drives the soundboard, which has a large area and couples the vibration efficiently to the air.']],
 w6:[['Where does the energy go when two sounds cancel?','Cancellation is local. Elsewhere the waves add constructively, and some energy goes back into the speaker. Energy is redistributed, not destroyed.'],
     ['Why can\'t you cancel noise throughout a whole room the same way?','The cancelling wave only matches the noise at one point. A short distance away (a fraction of a wavelength) the phases no longer line up.']],
 x1:[['Estimate the voltage between the bird\'s feet.','A line might carry ~1000 A with resistance ~5 × 10⁻⁵ Ω/m. Over 5 cm that is 2.5 × 10⁻⁶ Ω, so about 2.5 mV.'],
     ['Why can high-voltage lines be dangerous even without touching them?','Air breaks down at about 3 MV/m. Near a line at hundreds of kV, a spark can jump a gap of tens of centimetres.']],
 x2:[['How would a thicker pipe wall change the fall?','More copper means larger eddy currents and a larger braking force, so a slower terminal speed.'],
     ['What if the pipe had a slit cut along its whole length?','The current loops around the pipe are broken, so the eddy currents and braking are much weaker. The magnet falls faster.']],
 x3:[['Why does a microwave heat unevenly, and how could you use that to measure c?','Standing waves give hot spots λ/2 ≈ 6 cm apart. Melt chocolate without the turntable, measure the spacing d, then c = 2d × 2.45 GHz.'],
     ['Why doesn\'t the metal mesh in the door let microwaves out?','The holes are a few mm across, much smaller than the 12 cm wavelength, so the mesh behaves like a solid metal sheet. Visible light (λ ≈ 500 nm) passes straight through.']],
 x4:[['Why does the balloon fall off after a while?','Its charge leaks away, mainly through moisture in the air, faster on humid days.'],
     ['Why does a charged rod bend a thin stream of water?','Water molecules are polar. In the non-uniform field they line up and are pulled towards the stronger field near the rod.']],
 x5:[['Why not use even higher voltages?','Insulation, arcing and corona discharge get worse, pylons must be taller with wider spacing, and the equipment costs more.'],
     ['Why is AC usual, and when is DC used instead?','Transformers make AC easy to step up and down. For very long or undersea cables, high-voltage DC wins because it avoids losses from the cable\'s capacitance.']],
 h1:[['At what temperature would metal and wood feel the same?','At skin temperature (about 33 °C), when no heat flows either way.'],
     ['Why do tiles feel colder than carpet in the same room?','Same reason: tiles conduct heat away from your feet much faster than carpet, which traps air.']],
 h2:[['Why is water densest at 4 °C?','Two effects compete. Cooling packs molecules closer (normal contraction), but below about 4 °C open, hydrogen-bonded, ice-like clusters start to dominate and the liquid expands.'],
     ['Does pressure melting explain why ice skates glide?','Barely. A skater\'s pressure (~10⁶ Pa) lowers the melting point by only about 0.1 K. Frictional heating and a naturally liquid-like surface layer matter more.']],
 h3:[['Estimate the force on the lid of a pressure cooker.','Excess pressure ≈ 1 atm = 10⁵ Pa on a lid of radius 11 cm (area ≈ 0.04 m²): about 4000 N, the weight of 400 kg.'],
     ['At what temperature does water boil on Everest?','Pressure there is about a third of an atmosphere, so water boils at about 70 °C.']],
 h4:[['How could you actually cool the room?','Put the hot side outside the room, which is exactly what an air conditioner does.'],
     ['A fridge draws 100 W and removes 300 W of heat from inside. How much heat comes out of the back?','Energy conservation: 300 + 100 = 400 W.']],
 h5:[['Why can people survive a sauna at 90 °C?','Dry air delivers heat slowly, and sweating cools the skin by evaporation. Throwing water on the coals raises the humidity and it suddenly feels much hotter.'],
     ['How do people walk across hot embers without burning?','Embers and ash are poor conductors with low heat capacity, and each foot touches only briefly, so little heat is delivered.']],
 h6:[['Why does a lid keep soup hot for so much longer?','It stops evaporation (the main loss) and convection of air across the surface.'],
     ['Why do you feel cold getting out of a pool on a windy day?','Wind carries away humid air, so water evaporates fast from your skin, taking latent heat with it.']],
 a1:[['Is the Moon moving away from us? Why?','Yes, about 3.8 cm per year. The Earth\'s tidal bulge runs ahead of the Moon and pulls it forwards, transferring angular momentum from Earth\'s spin to the Moon\'s orbit.'],
     ['Will the Earth ever become tidally locked to the Moon?','In principle, after tens of billions of years. The Sun will become a red giant long before then.']],
 a2:[['Estimate the mass of the Sun from the Earth\'s orbit.','GM = 4π²r³/T². With r = 1.5 × 10¹¹ m and T = 3.2 × 10⁷ s, GM ≈ 1.3 × 10²⁰, so M ≈ 2 × 10³⁰ kg.'],
     ['How would you measure G in a laboratory?','A Cavendish torsion balance: small masses on a rod hanging from a thin fibre are attracted by large masses. The tiny twist, calibrated by the oscillation period, gives the force.']],
 a3:[['Which has the bigger tidal effect, the Sun or the Moon?','Tidal force scales as M/d³. Moon: 7 × 10²² / (3.8 × 10⁸)³; Sun: 2 × 10³⁰ / (1.5 × 10¹¹)³. The Moon\'s effect is about 2.2 times the Sun\'s.'],
     ['Why isn\'t high tide exactly when the Moon is overhead?','The oceans cannot respond instantly: water has inertia, there is friction, and continents get in the way. Real tides lag the Moon by hours, and vary a lot from place to place.']],
 a4:[['If the Sun vanished, when would the Earth stop orbiting?','About 8 minutes later. Changes in gravity also travel at the speed of light.'],
     ['How was the speed of light first measured?','Rømer (1676) noticed that eclipses of Jupiter\'s moon Io came later when Jupiter was further away, and from the delay estimated c.']],
 a5:[['How small would the Sun have to be to become a black hole?','The Schwarzschild radius is 2GM/c² = 2 × 6.7 × 10⁻¹¹ × 2 × 10³⁰ / 9 × 10¹⁶ ≈ 3 km.'],
     ['What density is that?','2 × 10³⁰ kg in a sphere of radius 3 km gives about 2 × 10¹⁹ kg/m³, denser than an atomic nucleus.']],
 a6:[['Roughly how tall can a mountain be on Earth?','The rock at the base fails when ρgh exceeds its strength (~3 × 10⁸ Pa): h ≈ 3 × 10⁸ / (3000 × 10) ≈ 10 km. Everest is 8.8 km.'],
     ['Why is Mars\'s Olympus Mons so much taller (about 22 km)?','Gravity on Mars is about 0.38 g, so the same rock strength supports a mountain roughly 2.6 times taller.']],
 d1:[['How does a falling cat turn over without breaking angular-momentum conservation?','It changes shape: it twists its front and back halves in opposite directions with different moments of inertia, so the total angular momentum stays zero while the orientation changes.'],
     ['Why doesn\'t a spinning top fall over?','Gravity\'s torque changes the direction of the angular momentum instead of tipping the top. The axis slowly circles round: precession.']],
 d2:[['Why do bubbles keep forming at the same spots?','Nucleation sites: scratches and tiny pockets of trapped gas make it much easier for a bubble to start.'],
     ['Why can water heated in a microwave "explode" when disturbed?','In a smooth container with no nucleation sites it can superheat above 100 °C. A spoon or a jolt triggers sudden violent boiling.']],
 d3:[['If the wind blows rain at your back at speed w, how fast should you go?','At about speed w, so relative to you the rain falls straight down and none hits your front or back.'],
     ['Does your shape matter?','Yes. A small front area reduces the speed-independent part, and leaning forward can shield your front.']],
 d4:[['Design an experiment to tell the explanations apart.','Use cold water to rule out convection, use smoke or light paper strips to show the flow pattern, and measure the pressure inside and outside the curtain.'],
     ['Why do you feel pulled towards a fast train passing close by?','The train drags air along with it, and the moving air near it is at lower pressure, so the higher-pressure still air behind you pushes you towards the train.']]
};

/* ---------- more questions ---------- */
PHY.push(
{id:'n1',t:2,l:3,q:'What is the integral of e<sup>−x²</sup> from −∞ to ∞?',
 h:['There is no elementary antiderivative, so a trick is needed. Call the integral I and consider I².',
    'Write I² as a double integral over the whole plane and switch to polar coordinates, where dx dy = r dr dθ.'],
 a:'<p>I² = ∫∫ e<sup>−(x²+y²)</sup> dx dy = ∫₀<sup>2π</sup>∫₀<sup>∞</sup> e<sup>−r²</sup> r dr dθ = 2π × ½ = π.</p><p>So <b>I = √π</b>.</p><p>This Gaussian integral appears everywhere in physics: the normal distribution, the speeds of gas molecules, and the ground state of the quantum harmonic oscillator.</p>',
 f:[['What is the integral of x² e<sup>−x²</sup> over the same range?','By parts (or differentiating ∫e^(−ax²) = √(π/a) with respect to a): √π/2.'],
    ['What is the integral of e<sup>−x²</sup> from 0 to ∞?','By symmetry, half: √π/2.']]},
{id:'n2',t:2,l:2,q:'Two friends agree to meet at a café between 12:00 and 13:00. Each arrives at a random time and waits 15 minutes before leaving. What is the probability they meet?',
 h:['Draw a square: one person\'s arrival time on each axis.',
    'They meet if their arrival times differ by at most 15 minutes. Which region of the square is that?'],
 a:'<p>On the 60 × 60 square, they fail to meet in two corner triangles where |x − y| &gt; 15. Each triangle has legs of 45, so the total area is 45² = 2025 out of 3600.</p><p>P(meet) = 1 − (45/60)² = 1 − 9/16 = <b>7/16</b>.</p>',
 f:[['What if each waits 20 minutes?','1 − (40/60)² = 5/9.'],
    ['What if one waits 15 minutes and the other 30?','The two corner triangles now differ: ½(45/60)² + ½(30/60)² = 0.28 + 0.125, so P(meet) = 19/32 ≈ 0.59.']]},
{id:'n3',t:2,l:2,q:'How many times a day do the hands of a clock make a right angle?',
 h:['Think about how often the minute hand laps the hour hand.',
    'Relative to the hour hand, the minute hand makes 11 full turns in 12 hours. How many right angles per relative turn?'],
 a:'<p>The minute hand gains one full turn on the hour hand 11 times every 12 hours. In each relative turn the angle passes 90° twice (at 90° and 270°).</p><p>So 22 times in 12 hours, and <b>44 times a day</b>.</p>',
 f:[['How many times a day do the hands overlap?','Once per relative turn: 22 times a day.'],
    ['At what time after 12:00 do they first overlap?','After 12/11 hours, about 1:05:27.']]},
{id:'n4',t:1,l:2,q:'A rope fits snugly around the Earth\'s equator. You add 1 m to its length and hold it evenly above the ground all the way round. How high is it? Could a cat crawl under it?',
 h:['How is the circumference related to the radius?',
    'If C = 2πr, how much does r change when C increases by 1 m?'],
 a:'<p>Δr = ΔC / 2π = 1/(2π) ≈ <b>16 cm</b>. A cat could crawl under.</p><p>The surprise is that the answer does not depend on the size of the Earth at all: the same extra metre around a football gives the same 16 cm gap.</p>',
 f:[['Instead, you pull the rope up at a single point until it is taut. Roughly how high does that point go?','The rope leaves the Earth along two tangents. Extra length 2R(tanθ − θ) ≈ 2Rθ³/3 = 1 m gives θ ≈ 6 × 10⁻³ rad, and height ≈ Rθ²/2 ≈ 120 m. Astonishingly high!'],
    ['Why is the second answer so different?','The extra length grows only as θ³ while the height grows as θ², so a tiny bit of slack allows a surprisingly large lift at one point.']]},
{id:'n5',t:6,l:3,q:'If the Earth suddenly stopped in its orbit, how long would it take to fall into the Sun?',
 h:['A straight-line fall is the limit of a very thin ellipse. Kepler\'s third law still applies.',
    'The thin ellipse has a semi-major axis of half the Earth–Sun distance. The fall is half of one orbit of that ellipse.'],
 a:'<p>A radial fall is a degenerate ellipse with semi-major axis a = r/2. By Kepler\'s third law, its period is T × (1/2)<sup>3/2</sup> = T/(2√2).</p><p>The fall takes half of that: T/(4√2) = 365/5.66 ≈ <b>65 days</b>.</p>',
 f:[['How long would the Moon take to fall to the Earth?','Same ratio: 27.3 days / 5.66 ≈ 4.8 days.'],
    ['How fast would the Earth be going when it hit the Sun?','Roughly the escape speed at the Sun\'s surface, about 620 km/s.']]},
{id:'n6',t:3,l:1,q:'Why do you seem to hear the sea when you hold a shell to your ear?',
 h:['Is the sound still there if you are in a very quiet room?',
    'The cavity inside the shell has natural frequencies, like an organ pipe.'],
 a:'<p>The shell\'s cavity <b>resonates</b>: it amplifies the background noise around you at its own natural frequencies, giving a whooshing, sea-like sound. In a soundproof room you hear almost nothing.</p><p>A cupped hand or a mug does the same thing.</p>',
 f:[['Why does a bigger shell give a lower-pitched sound?','A larger cavity has longer resonant wavelengths, so lower frequencies.'],
    ['Why does the pitch rise as you fill a bottle with water?','The air column above the water gets shorter, so its resonant frequency rises.']]},
{id:'n7',t:4,l:2,q:'Why does a compass point north? What would it do at the North Pole?',
 h:['The Earth has a magnetic field roughly like a bar magnet. Which way does a compass\'s "north" end point?',
    'Near the magnetic poles, the field lines point steeply into or out of the ground.'],
 a:'<p>The needle lines up with the Earth\'s magnetic field. Its north pole is attracted to the Earth\'s magnetic pole in the Arctic, which is therefore magnetically a <b>south</b> pole.</p><p>At the magnetic pole the field is almost vertical: the needle tries to point straight down, so a horizontal compass swings aimlessly. (The magnetic pole is also hundreds of kilometres from the geographic pole and drifts over time.)</p>',
 f:[['How does the Earth produce its field?','A geodynamo: convection in the liquid iron outer core, twisted by the Earth\'s rotation, generates electric currents and so a magnetic field.'],
    ['Why can\'t it just be a giant permanent magnet?','The core is far hotter than iron\'s Curie temperature (about 770 °C), above which permanent magnetism disappears.']]},
{id:'n8',t:0,l:1,q:'Estimate how long a full kettle takes to boil.',
 h:['How much water, and how much does its temperature rise?',
    'Use Q = mcΔT with c = 4200 J/kg K, and the kettle\'s power rating (around 3 kW).'],
 a:'<p>1.5 kg of water from 20 °C to 100 °C: Q = 1.5 × 4200 × 80 ≈ 5 × 10⁵ J.</p><p>At 3 kW, t ≈ 5 × 10⁵ / 3000 ≈ 170 s, <b>about 3 minutes</b>. In reality a bit longer, because some heat warms the kettle and the air.</p>',
 f:[['How much does that cost?','5 × 10⁵ J ≈ 0.14 kWh, so at about 25p per kWh, roughly 3–4p.'],
    ['How much longer would it take to boil it all away?','Latent heat 2.26 MJ/kg × 1.5 kg ≈ 3.4 MJ, about seven times longer again (~19 minutes).']]},
{id:'n9',t:6,l:2,q:'If the universe is huge and full of stars, why is the night sky dark?',
 h:['In an infinite, unchanging universe, every line of sight would eventually end on a star. Which assumption must fail?',
    'Think about the age of the universe and its expansion.'],
 a:'<p>This is <b>Olbers\' paradox</b>. In an infinite, eternal, static universe the whole sky would be as bright as the Sun\'s surface.</p><p>The resolution: the universe has a finite age (about 13.8 billion years), so we only see light from a finite volume, and stars have finite lifetimes. Expansion also redshifts distant light, weakening it.</p>',
 f:[['Why do stars twinkle but planets mostly don\'t?','Stars are point sources, so atmospheric turbulence shifts their light around. Planets show a small disc, so the fluctuations average out.'],
    ['What does the redshift of distant galaxies tell us?','They are moving away, faster the further they are (Hubble\'s law), which is the evidence that the universe is expanding.']]},
{id:'n10',t:7,l:3,q:'When you stir a cup of tea and stop, the tea leaves gather in the middle of the bottom rather than flying outwards. Why?',
 h:['In the spinning tea, pressure increases outwards to provide the centripetal force. Is that the same at every depth?',
    'Near the bottom, friction slows the water. Does the same pressure gradient still balance it there?'],
 a:'<p>The rotating tea needs an inward force, supplied by a pressure that rises towards the rim (the surface dips in the middle). Near the bottom, friction slows the water, so it needs less centripetal force, but the same pressure gradient still acts.</p><p>The excess inward push drives a flow <b>inward along the bottom</b>, up the middle and out at the top. The leaves are swept to the centre and are too heavy to rise, so they pile up there. Einstein explained this in 1926.</p>',
 f:[['Why do rivers erode the outside of bends?','The same secondary flow: at a bend, surface water moves outwards and bottom water inwards, carrying sediment to the inside bank and scouring the outside.'],
    ['What shape is the surface of the spinning tea?','A paraboloid: z = ω²r²/(2g).']]},
{id:'n11',t:1,l:1,q:'Estimate the fastest speed a car can drive round a roundabout without skidding.',
 h:['What provides the centripetal force?',
    'Friction: μmg ≥ mv²/r. Estimate μ for tyres on dry tarmac and a sensible radius.'],
 a:'<p>Friction provides the centripetal force: v<sub>max</sub> = √(μgr). With μ ≈ 0.8 and r ≈ 15 m, v ≈ √(0.8 × 9.8 × 15) ≈ 11 m/s, <b>about 40 km/h (25 mph)</b>.</p><p>The mass cancels, so a lorry and a car have the same limit (in this simple model).</p>',
 f:[['Why are bends on fast roads and racetracks banked?','Part of the normal force then points towards the centre, so less (or no) friction is needed.'],
    ['How does the limit change on ice?','μ drops to about 0.1, so v drops by √8 ≈ 3: about 4 m/s.']]},
{id:'n12',t:0,l:1,q:'How much power does your body use, on average? Compare it with a light bulb.',
 h:['Start from the food energy you eat per day.',
    'About 2500 kcal, and 1 kcal ≈ 4200 J. How many seconds are in a day?'],
 a:'<p>2500 kcal × 4200 J ≈ 10⁷ J per day. Divided by 86 400 s, that is <b>about 120 W</b>: similar to an old-fashioned light bulb.</p><p>That is why a crowded room warms up quickly.</p>',
 f:[['How much of that does your brain use?','About 20%, or roughly 20 W.'],
    ['How many stairs could the energy in one biscuit (~200 kJ) lift you?','One stair raises 70 kg by 0.17 m: about 120 J. So ~1700 stairs at 100% efficiency, but muscles are ~25% efficient, so about 400.']]}
);
PHY.push(
{id:'p1',t:0,l:2,q:'Roughly how many photons per second does a 100 W light bulb give out?',
 h:['What is the energy of one visible photon? Use E = hc/λ with λ ≈ 500 nm, or remember it is a couple of electronvolts.',
    'Divide the power by the energy per photon. Then think: is all 100 W visible light?'],
 a:'<p>A 500 nm photon has E = hc/λ ≈ 4 × 10⁻¹⁹ J (about 2.5 eV).</p><p>If all 100 W were visible: 100 / 4 × 10⁻¹⁹ ≈ <b>3 × 10²⁰ photons per second</b>.</p><p>An old filament bulb turns only about 5% into visible light, so about 10¹⁹ visible photons per second, with the rest as infrared.</p>',
 f:[['How many of those enter your eye from 10 m away?','Pupil area ≈ 2 × 10⁻⁵ m²; sphere area at 10 m ≈ 1300 m². Fraction ≈ 1.5 × 10⁻⁸, so about 10¹¹–10¹² photons per second.'],
    ['Why don\'t you notice individual photons?','The numbers are enormous. Fully dark-adapted rod cells can respond to single photons, but you need several arriving together to consciously see a flash.']]},
{id:'p2',t:1,l:1,q:'You stand on bathroom scales in a lift that accelerates upwards at 2 m/s². Your mass is 60 kg. What do the scales read?',
 h:['Scales measure the normal contact force, not your mass directly.',
    'Apply Newton\'s second law: N − mg = ma.'],
 a:'<p>N = m(g + a) = 60 × (9.8 + 2) ≈ 710 N. Scales calibrated in kilograms divide by g, so they read about <b>72 kg</b>.</p><p>Accelerating downwards, they would read less. When moving at constant speed, they read your true 60 kg.</p>',
 f:[['What do the scales read if the cable snaps?','Zero: you and the scales fall together in free fall.'],
    ['Why do you feel heavier at the bottom of a swing?','You are accelerating upwards towards the centre of the circle, so the seat must push with N = mg + mv²/r.']]},
{id:'p3',t:3,l:1,q:'Why do you hear thunder after you see the lightning? How could you use that?',
 h:['Compare the speeds of light and sound.',
    'Sound travels at about 340 m/s. How far does it go in 3 seconds?'],
 a:'<p>Light arrives almost instantly; sound travels at about 340 m/s. The delay tells you the distance: about <b>3 seconds per kilometre</b> (or 5 seconds per mile).</p><p>If the gap is shrinking, the storm is coming towards you.</p>',
 f:[['Why does thunder rumble rather than make a single bang?','The bolt is kilometres long, so sound from different parts arrives at different times, plus echoes off the ground and clouds.'],
    ['Why can you sometimes see lightning but hear no thunder at all?','Beyond about 15–25 km, sound is refracted upwards (air is cooler higher up, so sound bends away from the ground) and absorbed.']]},
{id:'p4',t:4,l:1,q:'Why does a TV remote still work when you point it at the wall instead of the TV?',
 h:['What kind of signal does the remote send?',
    'What happens to infrared light when it hits a matt wall?'],
 a:'<p>The remote flashes an <b>infrared</b> LED in a coded pattern. A matt wall reflects infrared diffusely in all directions, like visible light, so enough reaches the TV\'s sensor.</p>',
 f:[['How can you check whether a remote\'s LED is working?','Look at it through a phone camera: the sensor detects near-infrared, so the LED appears to flash.'],
    ['Why can\'t our eyes see infrared?','Infrared photons have too little energy to trigger the light-sensitive pigments in the retina.']]},
{id:'p5',t:5,l:2,q:'Why does a bicycle pump get hot when you pump up a tyre?',
 h:['You do work on the air when you push the handle. Where does that energy go?',
    'A quick compression does not leave time for heat to escape. This is called an adiabatic change.'],
 a:'<p>Compressing the gas quickly does work on it, raising its internal energy and therefore its temperature, because there is little time for heat to escape (an <b>adiabatic</b> compression). Friction between the piston and barrel adds some heat too.</p><p>For air (γ = 1.4) compressed quickly from 1 to 3 atmospheres: T₂ = T₁ × 3<sup>0.29</sup> ≈ 293 × 1.37 ≈ 400 K, a rise of about 100 °C in the air itself. The metal barrel warms more gently.</p>',
 f:[['Why does an aerosol can get cold when you spray it?','The gas expands and the liquid propellant evaporates, both of which take energy from the can.'],
    ['How does a fridge use the same idea?','Refrigerant is compressed (heating it, so it releases heat outside) and then expanded (cooling it, so it absorbs heat inside).']]},
{id:'p6',t:6,l:2,q:'How do we know what the Sun is made of, without going there?',
 h:['When light passes through a cooler gas, certain wavelengths are absorbed.',
    'Each element has a unique pattern of spectral lines.'],
 a:'<p><b>Spectroscopy</b>. Sunlight split into a spectrum shows dark absorption lines (Fraunhofer lines), where atoms in the Sun\'s cooler outer layers absorb specific wavelengths. Each element\'s pattern acts as a fingerprint.</p><p>Matching the lines identifies the elements; their strengths, with atomic physics, give the amounts. Cecilia Payne showed in 1925 that the Sun is mostly hydrogen and helium.</p>',
 f:[['How was helium discovered?','As an unknown yellow spectral line in sunlight during the 1868 eclipse, decades before it was found on Earth. It is named after Helios, the Sun.'],
    ['How can spectra tell us that a star is moving away from us?','The whole pattern of lines is shifted to longer wavelengths (redshift), by an amount that gives the speed.']]},
{id:'p7',t:2,l:1,q:'Is 0.999… (recurring forever) equal to 1?',
 h:['Call it x. What is 10x?',
    'Subtract x from 10x.'],
 a:'<p>Yes. Let x = 0.999… Then 10x = 9.999…, so 10x − x = 9 and x = <b>1</b> exactly.</p><p>Another view: if they were different numbers, there would have to be a number between them, and there is none. It is also the geometric series 9/10 + 9/100 + … = (9/10)/(1 − 1/10) = 1.</p>',
 f:[['Write 0.272727… as a fraction.','100x − x = 27, so x = 27/99 = 3/11.'],
    ['What is 1/2 + 1/4 + 1/8 + …?','1: a geometric series with a = ½ and r = ½.']]},
{id:'p8',t:7,l:2,q:'How does a drinking straw work? Could you drink through a 15 m straw?',
 h:['When you suck, what are you actually doing to the air in the straw?',
    'What pushes the liquid up, and what is the most it can push?'],
 a:'<p>You lower the pressure inside the straw; atmospheric pressure on the drink\'s surface pushes the liquid up. You don\'t pull it.</p><p>Even with a perfect vacuum, atmospheric pressure can only support a column of height h = p/(ρg) = 10⁵/(1000 × 9.8) ≈ <b>10 m</b> of water. A 15 m straw cannot work, however hard you suck.</p>',
 f:[['Would a straw work on the Moon (inside a pressurised base)?','Inside a pressurised base, yes. Outside, with no air pressure, nothing would push the drink up (and it would boil anyway).'],
    ['How do tall trees lift water more than 10 m, then?','Water is pulled up as a continuous column under tension: evaporation from the leaves draws water up, and cohesion between water molecules stops the column breaking.']]}
);
PHY.push(
{id:'q1',t:7,l:2,q:'Why is it much easier to balance a broom upright on your hand than a pencil?',
 h:['Both are inverted pendulums: if they tilt slightly, they fall further. What sets how quickly the tilt grows?',
    'Use dimensional analysis: the only time scale from length L and g is √(L/g). Compare that with your reaction time.'],
 a:'<p>An upright stick that tilts by a small angle θ falls with θ growing roughly as e<sup>t/τ</sup>, where τ ~ √(L/g). For a rod pivoted at its end, τ = √(2L/3g).</p><p>Pencil (L ≈ 0.15 m): τ ≈ 0.1 s. Broom (L ≈ 1.5 m): τ ≈ 0.3 s. Human reactions take about 0.2 s, so you can correct a broom in time but not a pencil. <b>Longer objects fall over more slowly.</b></p>',
 f:[['Why is a broom easier to balance with the heavy brush at the top?','Raising the centre of mass increases the effective pendulum length (I/md), so it topples even more slowly.'],
    ['Released 1° from vertical, roughly how long does a pencil take to fall over?','θ ≈ θ₀ cosh(t/τ). Growing from 0.017 rad to about 1 rad needs cosh ≈ 60, so t ≈ 4.8τ ≈ 0.5 s.']]},
{id:'q2',t:4,l:2,q:'Why does your hair stand on end when you touch a Van de Graaff generator?',
 h:['When you touch the dome, charge spreads over your body, including every hair.',
    'What do like charges do to each other?'],
 a:'<p>Charge flows from the dome onto you and spreads over your surface. Every hair gets charge of the <b>same sign</b>, so the hairs repel each other and your head, and spread out as far apart as possible.</p><p>It only works if you stand on an insulator, so the charge cannot escape to the ground. Fine, dry hair works best.</p>',
 f:[['Why must you stand on an insulating mat?','Otherwise the charge simply flows through you to earth and never builds up.'],
    ['Why is the dome large and smooth? Roughly what voltage can a 30 cm diameter dome reach?','Sharp points concentrate the field and leak charge (corona discharge). For a sphere E = V/r, and air breaks down at about 3 MV/m, so V ≈ 3 × 10⁶ × 0.15 ≈ 450 kV.']]},
{id:'q3',t:5,l:1,q:'Why can you see your breath on a cold day but not on a warm one?',
 h:['Your breath is warm and saturated with water vapour. What happens to it when it mixes with cold air?',
    'Cold air can hold much less water vapour than warm air.'],
 a:'<p>Exhaled air is at about 35 °C and nearly saturated with water vapour. Mixing with cold air cools it below its <b>dew point</b>, so the vapour condenses into a cloud of tiny droplets: you see a little cloud.</p><p>On a warm day the mixture never cools enough to become saturated, so the vapour stays invisible.</p>',
 f:[['Why do aircraft leave contrails?','Engine exhaust contains water vapour. At altitude the air is around −40 °C, so the vapour quickly condenses and freezes into ice crystals.'],
    ['Why does a cold drink "sweat" in summer?','Air touching the cold glass is cooled below its dew point, so water condenses on the surface.']]},
{id:'q4',t:3,l:2,q:'Why does your voice sound higher after breathing in helium?',
 h:['How does the speed of sound depend on the gas it travels through?',
    'Your vocal tract is a resonator: its resonant frequencies depend on the wave speed. Does the vibration rate of your vocal cords change much?'],
 a:'<p>Sound travels about three times faster in helium, because its atoms are much lighter (v = √(γRT/M)). The resonances of your throat and mouth (the "formants" that give your voice its character) shift to much higher frequencies.</p><p>Surprisingly, your vocal cords vibrate at nearly the same rate, so the fundamental pitch barely changes. What changes is the <b>timbre</b>, which makes your voice sound squeaky and higher.</p>',
 f:[['By roughly what factor is sound faster in helium than in air?','√((γ_He/γ_air)(M_air/M_He)) = √((1.67/1.4)(29/4)) ≈ 2.9.'],
    ['What would breathing sulfur hexafluoride (a very heavy gas) do?','Sound is slower in it, so the resonances shift down and your voice sounds much deeper. (Like helium, it is dangerous to breathe, because it displaces oxygen.)']]}
);
/* university-level questions: harder, first-year style, to make interviews feel realistic */
PHY.push(
{id:'u1',t:1,l:3,q:'A uniform heavy chain hangs between two hooks at the same height. Find the shape it makes.',
 h:['Look at a small piece of chain. The horizontal component of tension, H, must be the same everywhere. Why?',
    'The vertical component of tension at a point supports the weight of the chain between the lowest point and there. Write dy/dx in terms of the arc length s.',
    'With ds = √(1 + y′²) dx, differentiate again to get a differential equation for y. Try y = a cosh(x/a).'],
 a:'<p>No horizontal external force acts, so the horizontal tension H is constant. The vertical tension at arc length s from the bottom supports a weight λgs, so dy/dx = λgs/H = s/a, with a = H/(λg).</p><p>Differentiating: y″ = (1/a) ds/dx = (1/a)√(1 + y′²). The solution is the <b>catenary</b>, y = a cosh(x/a) (plus a constant), since cosh′ = sinh and 1 + sinh² = cosh².</p><p>What tutors look for: a good free-body diagram of a small element and spotting that H is constant.</p>',
 f:[['How is a suspension-bridge cable different?','The deck\'s weight is spread evenly per horizontal length, not per length of cable, so y″ = constant: a parabola.'],
    ['Why does an upside-down catenary make a strong arch?','The same shape that is in pure tension when hanging is in pure compression when inverted, so there are no bending moments. Masonry is strong in compression.']]},
{id:'u2',t:2,l:3,q:'Solve m ẍ + b ẋ + k x = 0 for a damped oscillator, and describe the different types of behaviour.',
 h:['Try x = e^(λt). What equation must λ satisfy?',
    'The nature of the roots depends on the discriminant b² − 4mk.'],
 a:'<p>Substituting x = e<sup>λt</sup> gives mλ² + bλ + k = 0, so λ = [−b ± √(b² − 4mk)]/2m.</p><p><b>Under-damped</b> (b² &lt; 4mk): complex roots, x = Ae<sup>−bt/2m</sup>cos(ω′t + φ) with ω′ = √(k/m − b²/4m²). The oscillation decays.</p><p><b>Critically damped</b> (b² = 4mk): x = (A + Bt)e<sup>−bt/2m</sup>, the fastest return without oscillating. <b>Over-damped</b> (b² &gt; 4mk): two decaying exponentials, a slow return.</p>',
 f:[['Which would you design a car suspension to be, and why?','Close to critical (slightly under): it settles quickly after a bump without bouncing repeatedly or feeling harsh.'],
    ['What is the quality factor Q?','Q = ω₀m/b ≈ 2π × (energy stored)/(energy lost per cycle). A high Q means slow decay and a sharp resonance peak, as in a tuning fork.']]},
{id:'u3',t:3,l:3,q:'A particle of mass m is trapped in a one-dimensional box of width L. Estimate its lowest energy. Use this to explain why chemistry involves electronvolts but nuclear physics involves MeV.',
 h:['Its de Broglie wave must fit in the box like a standing wave on a string. What is the longest wavelength allowed?',
    'λ = 2L, p = h/λ, and E = p²/2m. Then put in an electron in an atom (L ~ 10⁻¹⁰ m) and a nucleon in a nucleus (L ~ 10⁻¹⁴ m).'],
 a:'<p>Standing waves need L = nλ/2, so p = nh/2L and E<sub>n</sub> = n²h²/(8mL²). The lowest energy is E₁ = h²/(8mL²), which is never zero.</p><p>Electron, L = 10⁻¹⁰ m: E₁ ≈ (6.6 × 10⁻³⁴)²/(8 × 9.1 × 10⁻³¹ × 10⁻²⁰) ≈ 6 × 10⁻¹⁸ J ≈ <b>40 eV</b>. Nucleon, L = 10⁻¹⁴ m: mass ×1800 and L² ×10⁻⁸, so E₁ ≈ 3 × 10⁻¹³ J ≈ <b>2 MeV</b>.</p><p>Confinement alone sets the energy scales: chemistry (eV) and nuclear physics (MeV).</p>',
 f:[['Why can\'t the particle simply sit still with zero energy?','A standing wave needs at least half a wavelength to fit, so p cannot be zero. This is the uncertainty principle: Δx Δp ≳ ħ.'],
    ['What happens to the energy levels if you double the width of the box?','They all fall by a factor of 4 (E ∝ 1/L²), and get closer together. That is why electrons in long molecules absorb at longer wavelengths.']]},
{id:'u4',t:4,l:3,q:'Maxwell found that electromagnetic waves travel at 1/√(μ₀ε₀). Check numerically that this is the speed of light, and outline where it comes from.',
 h:['Put in μ₀ = 4π × 10⁻⁷ H/m and ε₀ = 8.85 × 10⁻¹² F/m.',
    'Faraday: a changing B creates E. Ampère–Maxwell: a changing E creates B. Combining them in empty space gives a wave equation.'],
 a:'<p>μ₀ε₀ = 4π × 10⁻⁷ × 8.85 × 10⁻¹² ≈ 1.11 × 10⁻¹⁷ s²/m², so 1/√(μ₀ε₀) ≈ <b>3.00 × 10⁸ m/s</b>.</p><p>In vacuum, ∇ × E = −∂B/∂t and ∇ × B = μ₀ε₀ ∂E/∂t. Taking the curl of the first and using the second gives ∇²E = μ₀ε₀ ∂²E/∂t², a wave equation with speed 1/√(μ₀ε₀).</p><p>Two constants measured with static charges and steady currents predict the speed of light, which showed that light is an electromagnetic wave.</p>',
 f:[['In an electromagnetic wave, what is the ratio E/B?','E/B = c. E, B and the direction of travel are mutually perpendicular.'],
    ['Why was the "displacement current" term essential?','Without the μ₀ε₀ ∂E/∂t term, a changing electric field would not create a magnetic field, so there would be no self-sustaining wave. It also makes charge conservation consistent.']]},
{id:'u5',t:5,l:3,q:'Show that heat flowing from a hot body to a cold one increases the total entropy. What does that imply about heat engines?',
 h:['When heat Q enters a body at temperature T, its entropy changes by Q/T.',
    'Add the entropy changes of the hot body (losing Q) and the cold body (gaining Q).'],
 a:'<p>ΔS<sub>total</sub> = −Q/T<sub>h</sub> + Q/T<sub>c</sub> = Q(1/T<sub>c</sub> − 1/T<sub>h</sub>) &gt; 0 because T<sub>c</sub> &lt; T<sub>h</sub>. For example, 1000 J flowing from 400 K to 300 K gives −2.5 + 3.33 = <b>+0.83 J/K</b>.</p><p>For an engine, total entropy cannot fall, so it must dump some heat into the cold reservoir. That limits its efficiency to at most the Carnot value, 1 − T<sub>c</sub>/T<sub>h</sub>.</p>',
 f:[['What is the maximum efficiency of an engine working between 400 K and 300 K?','1 − 300/400 = 25%.'],
    ['What does entropy mean microscopically?','S = k ln Ω, where Ω is the number of microstates consistent with the macrostate. Heat spreading out increases the number of available arrangements.']]},
{id:'u6',t:6,l:3,q:'Estimate the temperature at the centre of the Sun using only its mass and radius.',
 h:['In a star in equilibrium, the thermal energy of particles is comparable to their gravitational binding energy (the virial theorem).',
    'Set kT ~ GMm_p/R for a proton. M = 2 × 10³⁰ kg, R = 7 × 10⁸ m.'],
 a:'<p>Balancing thermal and gravitational energy per particle: kT ~ GMm<sub>p</sub>/R, so T ~ GMm<sub>p</sub>/(kR) = (6.7 × 10⁻¹¹ × 2 × 10³⁰ × 1.7 × 10⁻²⁷)/(1.4 × 10⁻²³ × 7 × 10⁸) ≈ <b>2 × 10⁷ K</b>.</p><p>Detailed models give 1.5 × 10⁷ K, which is remarkably close for one line of physics.</p>',
 f:[['Is that hot enough for two protons to overcome their electrostatic repulsion classically?','No. kT ≈ 1 keV, while the Coulomb barrier is about 1 MeV. Fusion happens because protons quantum-tunnel through the barrier.'],
    ['How long could the Sun shine on gravitational energy alone?','GM²/R ÷ L ≈ (6.7 × 10⁻¹¹ × 4 × 10⁶⁰ / 7 × 10⁸)/(3.8 × 10²⁶) ≈ 10¹⁵ s, about 30 million years (Kelvin–Helmholtz). Geology needed far longer, which pointed to nuclear energy.']]},
{id:'u7',t:1,l:3,q:'Find the period of small oscillations of a uniform rod of length L pivoted at one end. Where should the pivot be to make the period as short as possible?',
 h:['For a rigid body, τ = Iα. For small angles the restoring torque is mgdθ, where d is the distance from the pivot to the centre of mass.',
    'Use the parallel axis theorem, I = I_cm + md², with I_cm = mL²/12.'],
 a:'<p>Iθ̈ = −mgdθ, so T = 2π√(I/(mgd)). Pivoted at the end: I = mL²/3 and d = L/2, giving <b>T = 2π√(2L/3g)</b>, like a simple pendulum of length 2L/3.</p><p>For a general pivot, T ∝ √((L²/12 + d²)/d). This is smallest when d² = L²/12, i.e. <b>d = L/√12 ≈ 0.29L</b> from the centre.</p>',
 f:[['Why does the period become very long if the pivot is right next to the centre of mass?','The restoring torque mgd goes to zero while the moment of inertia stays near mL²/12, so T → ∞.'],
    ['Why is the centre of percussion of a cricket bat useful?','Hitting the ball there causes no reaction impulse at the hands (the pivot), so there is no jarring "sting".']]},
{id:'u8',t:2,l:3,q:'What is 1 + 1/4 + 1/9 + 1/16 + …? At least show that it is less than 2.',
 h:['Compare 1/n² with 1/(n(n − 1)) for n ≥ 2.',
    '1/(n(n − 1)) = 1/(n − 1) − 1/n, which telescopes.'],
 a:'<p>For n ≥ 2, 1/n² &lt; 1/(n(n − 1)) = 1/(n − 1) − 1/n. Summing from n = 2 telescopes to 1, so the total is <b>less than 1 + 1 = 2</b>.</p><p>The exact value is <b>π²/6 ≈ 1.645</b> (the Basel problem, solved by Euler in 1734).</p>',
 f:[['How did Euler find π²/6?','He wrote sin x/x as an infinite product over its roots, (1 − x²/π²)(1 − x²/4π²)…, and compared the x² coefficient with the Taylor series, −1/6.'],
    ['Does 1/n^1.01 summed over all n converge?','Yes. Σ1/nᵖ converges for any p &gt; 1, by comparison with ∫x⁻ᵖ dx, though very slowly when p is close to 1.']]},
{id:'u9',t:7,l:3,q:'Estimate the drag force on a cyclist at 10 m/s and the power they must produce. Why is going twice as fast so hard?',
 h:['At this size and speed, drag is quadratic: F = ½ρC_dAv².',
    'Take a frontal area of about 0.5 m² and a drag coefficient of about 0.9. Power = force × velocity.'],
 a:'<p>F ≈ ½ × 1.2 × 0.9 × 0.5 × 10² ≈ 27 N, so P = Fv ≈ <b>270 W</b> (plus a bit for rolling resistance).</p><p>Since F ∝ v², P ∝ v³: doubling the speed needs about <b>8 times</b> the power. That is why racing cyclists tuck down and ride in each other\'s slipstream.</p>',
 f:[['When is drag proportional to v instead of v²?','At low Reynolds number (small, slow objects in viscous fluids, like dust or bacteria), Stokes\' law F = 6πηrv applies.'],
    ['How much easier is it to ride behind someone?','Drafting can cut drag by about 30–40%, which matters enormously because power scales with drag at fixed speed.']]}
);
PHY.push(
{id:'r1',t:7,l:2,q:'Why do cyclists lean into a corner? How far must they lean?',
 h:['In the cyclist\'s frame, what forces act at the tyre, and what must their combination do?',
    'Friction at the road provides the centripetal force mv²/r. For no toppling, the resultant of friction and the normal force must pass through the centre of mass.'],
 a:'<p>Turning needs a centripetal force, which only friction at the road can supply. Friction acts at the tyre, below the centre of mass, so on its own it would tip the cyclist outwards. Leaning in makes the resultant contact force (normal + friction) point through the centre of mass, so there is no net torque.</p><p>Normal force = mg, friction = mv²/r, so <b>tanθ = v²/(rg)</b> from the vertical. At 10 m/s round a 20 m radius: tanθ = 100/196 ≈ 0.5, θ ≈ 27°.</p>',
 f:[['What is the steepest lean possible on a dry road with μ ≈ 0.8?','Friction needed is mg tanθ ≤ μmg, so tanθ ≤ 0.8: about 39°. Lean further and the tyres slide out.'],
    ['Why do motorbike racers lean even further than the bike?','Moving their body inwards lowers and shifts the combined centre of mass, so the bike itself can stay more upright for the same turn, keeping more tyre in contact.']]},
{id:'r2',t:4,l:3,q:'A charged capacitor stores energy. Where exactly is that energy?',
 h:['Think about what exists between the plates of a charged capacitor that was not there before.',
    'Try energy per unit volume u = ½ε₀E² for the field, and compare with ½CV² for a parallel-plate capacitor with C = ε₀A/d.'],
 a:'<p>The energy is stored in the <b>electric field</b> between the plates, with energy density u = ½ε₀E².</p><p>Check for a parallel-plate capacitor: E = V/d and volume = Ad, so the field energy is ½ε₀(V/d)² × Ad = ½(ε₀A/d)V² = <b>½CV²</b>, exactly the circuit result.</p><p>Fields carrying energy is a deep idea: light, for example, is energy travelling in electric and magnetic fields.</p>',
 f:[['How much energy is stored per cubic metre in the fair-weather field of about 100 V/m near the ground?','½ × 8.85 × 10⁻¹² × 100² ≈ 4 × 10⁻⁸ J/m³: tiny.'],
    ['What is the magnetic equivalent, and how big is it inside a 3 T MRI magnet?','u = B²/2μ₀ = 9/(2 × 1.26 × 10⁻⁶) ≈ 4 × 10⁶ J/m³, which is why quenching an MRI magnet releases a lot of energy.']]},
{id:'r3',t:5,l:2,q:'How does sweating cool you down, and why does it work badly on humid days?',
 h:['Evaporating water needs energy. Where does that energy come from?',
    'The latent heat of vaporisation of water at skin temperature is about 2.4 MJ/kg. Evaporation depends on how much water vapour the air already holds.'],
 a:'<p>Sweat evaporates by taking latent heat from your skin. Evaporating 1 kg needs about 2.4 MJ, so sweating 1 litre per hour removes 2.4 × 10⁶/3600 ≈ <b>700 W</b>, several times your resting heat output.</p><p>In humid air, the air near your skin is already close to saturated, so the evaporation rate falls. Sweat drips off instead of evaporating, taking almost no heat with it.</p>',
 f:[['How much sweat per hour must evaporate to remove 100 W?','100 × 3600 / 2.4 × 10⁶ ≈ 0.15 kg, so about 150 ml per hour.'],
    ['Why do dogs pant instead of sweating?','Dogs have few sweat glands. Panting moves air rapidly over the wet tongue and airways, increasing evaporation there.']]},
{id:'r4',t:3,l:3,q:'Why is everything blurry when you open your eyes underwater, and why do goggles fix it?',
 h:['Most of the eye\'s focusing happens at the cornea, not the lens. What sets how strongly a surface refracts?',
    'The cornea has n ≈ 1.38. Compare its boundary with air (n = 1.00) and with water (n = 1.33).'],
 a:'<p>Refraction at a surface depends on the change in refractive index across it. In air, the cornea (n ≈ 1.38) provides about two-thirds of the eye\'s focusing power. In water (n ≈ 1.33) the difference is tiny, so most of that power vanishes and images focus far behind the retina: everything is blurred, like extreme long-sightedness.</p><p>Goggles trap a layer of air in front of the eye, restoring the air–cornea boundary.</p>',
 f:[['Why do objects look bigger through a diving mask?','Refraction at the flat mask makes objects appear at about 3/4 of their real distance (n ≈ 1.33), so they look about a third larger and closer.'],
    ['How do fish see clearly underwater?','Their corneas do little focusing; instead they have nearly spherical, very strongly curved lenses with a high refractive index.']]}
);
PHY.push(
{id:'s1',t:7,l:2,q:'Why do your ears "pop" on a plane? Roughly how big is the force on your eardrum before they pop?',
 h:['Aircraft cabins are pressurised to the pressure at about 2400 m altitude, roughly 0.75 atmospheres. What is trapped behind your eardrum?',
    'Force = pressure difference × area. An eardrum is about 60 mm² in area.'],
 a:'<p>Air is trapped in the middle ear behind the eardrum. As the cabin pressure falls during the climb, that air is at higher pressure than the cabin, so the eardrum bulges outwards until the Eustachian tube opens and lets air escape: the "pop".</p><p>Δp ≈ 0.25 atm ≈ 2.5 × 10⁴ Pa, and area ≈ 6 × 10⁻⁵ m², so F ≈ <b>1.5 N</b>, roughly the weight of a 150 g apple pressing on a membrane thinner than paper. No wonder it hurts.</p>',
 f:[['Why is it often worse during descent?','Outside pressure rises and squeezes the soft Eustachian tube shut, so air cannot get back into the middle ear easily. Swallowing or yawning helps open it.'],
    ['A sealed crisp packet is filled at sea level. By roughly what factor does its volume try to grow in the cabin?','Boyle\'s law at constant temperature: V ∝ 1/p, so about 1/0.75 ≈ 1.3 times.']]},
{id:'s2',t:6,l:2,q:'How fast is the Earth moving round the Sun? Why don\'t we feel it?',
 h:['Distance = circumference of the orbit (radius 1.5 × 10¹¹ m); time = one year (3.2 × 10⁷ s).',
    'Do we feel velocity or acceleration? Work out the centripetal acceleration v²/r.'],
 a:'<p>v = 2πr/T = 2π × 1.5 × 10¹¹ / 3.2 × 10⁷ ≈ <b>30 km/s</b>, over 100 000 km/h.</p><p>We only feel acceleration, not velocity. The centripetal acceleration is v²/r ≈ (3 × 10⁴)²/1.5 × 10¹¹ ≈ 6 × 10⁻³ m/s², less than a thousandth of g. And we are in free fall around the Sun together with the Earth, so even that produces no felt force.</p>',
 f:[['How fast are you moving because of the Earth\'s spin, in the UK (latitude about 52°)?','The equator moves at 2π × 6.4 × 10⁶ / 86 400 ≈ 465 m/s; at 52° multiply by cos 52° ≈ 0.62, giving about 290 m/s.'],
    ['And how fast does the Sun orbit the centre of the galaxy?','About 230 km/s, taking roughly 230 million years per orbit.']]},
{id:'s3',t:3,l:2,q:'Why does your voice sound better when you sing in the shower?',
 h:['Think about the surfaces in a shower and what they do to sound.',
    'A small enclosure has standing-wave resonances (room modes) at f = nv/2L. What frequencies does that give for L ≈ 1 m?'],
 a:'<p>Hard tiles reflect almost all sound, so your voice <b>reverberates</b>: notes are sustained and blended, which hides small wobbles in pitch.</p><p>The small space also has strong <b>resonances</b>. With L ≈ 1 m, f = v/2L ≈ 170 Hz and its multiples, right in the range of the human voice, so some notes are boosted and sound fuller and louder.</p>',
 f:[['What is the lowest resonant frequency between the floor and ceiling of a 2 m tall shower?','f = v/2L = 340/4 ≈ 85 Hz.'],
    ['Why do concert halls avoid large parallel walls?','They cause strong standing waves and "flutter echoes"; irregular shapes and absorbing materials give an even, controlled reverberation.']]},
{id:'s4',t:0,l:2,q:'Roughly how many raindrops fall on London on a day with 5 mm of rain?',
 h:['Estimate the total volume of water: area of London × depth of rain.',
    'London is about 1500 km². A typical raindrop is about 2 mm across.'],
 a:'<p>Volume ≈ 1.5 × 10⁹ m² × 5 × 10⁻³ m ≈ 7.5 × 10⁶ m³.</p><p>One drop of diameter 2 mm has volume (4/3)π(10⁻³)³ ≈ 4 × 10⁻⁹ m³. Number ≈ 7.5 × 10⁶ / 4 × 10⁻⁹ ≈ <b>2 × 10¹⁵ drops</b>: a couple of thousand trillion.</p>',
 f:[['Estimate the terminal speed of a 2 mm raindrop.','mg = ½ρC_dAv² with m ≈ 4 × 10⁻⁶ kg, A ≈ 3 × 10⁻⁶ m², C_d ≈ 0.5: v² ≈ 45, so v ≈ 7 m/s (measured: about 6.5 m/s).'],
    ['Why don\'t raindrops grow much bigger than about 5 mm?','Large drops are flattened by air resistance into a "parachute" shape and break apart, because surface tension can no longer hold them together.']]}
);
PHY.push(
{id:'v1',t:4,l:2,q:'How does an induction hob heat a pan but not your hand?',
 h:['Under the glass is a coil carrying alternating current at tens of kilohertz. What does a changing magnetic field do to a nearby conductor?',
    'Induced currents heat a material through its resistance. How good a conductor is your hand compared with a steel pan?'],
 a:'<p>The coil makes a rapidly alternating magnetic field. By Faraday\'s law, the changing flux induces <b>eddy currents</b> in the metal base of the pan, which heat it through its resistance (I²R). Iron-based pans also lose energy by repeatedly re-magnetising (hysteresis).</p><p>Your hand is a very poor conductor and is not magnetic, so only tiny currents flow and it barely warms. The glass top only gets hot from contact with the pan.</p>',
 f:[['Why do copper or aluminium pans work badly on induction?','They are not ferromagnetic and have very low resistivity: the induced currents spread out and produce little heating, and there is no hysteresis loss. (Some hobs use special higher-frequency coils for them.)'],
    ['Why use such a high frequency?','Induced emf is proportional to the rate of change of flux, so higher frequency gives larger currents. It also concentrates the currents in a thin surface layer (the skin effect) and keeps the hum above the range of hearing.']]},
{id:'v2',t:5,l:3,q:'Why is it hard to cook an egg properly on top of Everest? Estimate the boiling point of water there.',
 h:['Air pressure at the summit is about a third of sea-level pressure. Water boils when its vapour pressure equals the surrounding pressure.',
    'Use the Clausius–Clapeyron relation: ln(p₂/p₁) = −(L/R)(1/T₂ − 1/T₁), with L = 41 kJ/mol and T₁ = 373 K.'],
 a:'<p>With p₂/p₁ ≈ 1/3, ln(p₂/p₁) ≈ −1.1 and L/R ≈ 4900 K. So 1/T₂ = 1/373 + 1.1/4900 ≈ 0.00290 K⁻¹, giving T₂ ≈ 344 K ≈ <b>71 °C</b>.</p><p>Egg proteins set at roughly 62–80 °C, and the hardest-to-set parts need the top of that range, so water at 71 °C cooks an egg very slowly and the white may never fully firm up. Climbers use pressure cookers.</p>',
 f:[['What is the boiling point inside a pressure cooker at 2 atmospheres?','ln 2 = 0.69: 1/T₂ = 1/373 − 0.69/4900 ≈ 0.00254 K⁻¹, so T₂ ≈ 394 K ≈ 121 °C.'],
    ['Does adding a teaspoon of salt to the water noticeably raise the boiling point?','Hardly. About 6 g of salt in 1 kg of water gives about 0.2 mol of ions, raising the boiling point by only about 0.1 K.']]},
{id:'v3',t:7,l:2,q:'Why does a T-shirt look darker when it is wet?',
 h:['Most of the light you see from dry fabric is scattered back from the surfaces of many tiny fibres. What causes that scattering?',
    'Scattering at a boundary depends on the change in refractive index. Fibres have n ≈ 1.5, air n = 1.0, water n = 1.33.'],
 a:'<p>Dry fabric looks light because light is scattered back out at the many fibre–air boundaries before it can be absorbed. When water fills the gaps, the refractive-index difference at each boundary is much smaller, so far less light is scattered back.</p><p>Light travels deeper into the fabric and has more chances to be absorbed by the dye, so less returns to your eye and the fabric looks <b>darker and more saturated</b>.</p>',
 f:[['Why does wet sand look darker than dry sand?','Exactly the same reason: water between the grains reduces scattering at their surfaces, so more light is absorbed.'],
    ['Why does frosted glass become nearly see-through if you put clear sticky tape over it?','The tape\'s adhesive fills the rough surface and has a similar refractive index to the glass, so the scattering surface effectively disappears.']]},
{id:'v4',t:6,l:2,q:'Why can\'t we see the stars during the day, even though they are still there?',
 h:['What makes the daytime sky bright?',
    'Seeing something faint depends on contrast with its background, not just on how much light it sends.'],
 a:'<p>Sunlight scattered by air molecules makes the whole sky glow blue. A star sends the same light by day as by night, but against the bright sky its contrast is far too small for your eye to notice, especially as your eyes adapt to daylight.</p><p>Remove the scattering (above the atmosphere) and the sky is black even with the Sun up.</p>',
 f:[['Why can you sometimes see Venus in daylight?','It is extremely bright (much brighter than any star) and compact, so if you know exactly where to look, its contrast with the sky is just enough.'],
    ['Could astronauts on the Moon see stars during the lunar day?','In principle, yes: there is no atmosphere to scatter light. In practice their eyes and cameras were adjusted for the brilliant sunlit surface, so the faint stars rarely showed up in photos.']]}
);
PHY.push(
{id:'y1',t:0,l:1,q:'Estimate how far you walk in a lifetime. How does it compare with the distance round the Earth?',
 h:['Estimate the number of steps you take in a typical day, and the length of a step.',
    'Something like 7000 steps of 0.7 m each. Then multiply by the days in about 80 years. The Earth\'s circumference is 40 000 km.'],
 a:'<p>7000 steps × 0.7 m ≈ 5 km per day. Over 80 years: 5 × 365 × 80 ≈ 1.5 × 10⁵ km.</p><p>That is about <b>150 000 km, nearly four times round the Earth</b>, or roughly 40% of the way to the Moon.</p>',
 f:[['If each step raises your centre of mass by about 3 cm, how much lifting work is that per day?','7000 × 70 kg × 9.8 × 0.03 m ≈ 1.4 × 10⁵ J, about 35 kcal (and much more is used by muscles in reality).'],
    ['How long would it take to walk to the Moon non-stop?','384 000 km at 5 km/h ≈ 77 000 hours, about 9 years.']]},
{id:'y2',t:4,l:3,q:'On a fine day there is an electric field of about 100 V/m pointing down near the ground. So there should be about 170 V between your head and feet. Why don\'t you get a shock?',
 h:['You are a fairly good conductor compared with air. What does a conductor do to an electric field around it?',
    'A conductor in equilibrium is an equipotential. Where do the field lines end when you stand on the ground?'],
 a:'<p>Your body conducts far better than air, so charge flows (almost instantly) until your whole body is at the same potential as the ground. The field lines then end on your head instead of passing through you: there is <b>no potential difference across your body</b>.</p><p>The air itself is such a poor conductor that the tiny current that keeps you at ground potential is utterly negligible.</p>',
 f:[['The upper atmosphere is about 300 kV above the ground. Why doesn\'t that voltage simply leak away?','It does leak continuously (about 1 kA worldwide through the weakly conducting air), but thunderstorms around the world keep recharging it: the global electric circuit.'],
    ['Estimate the total charge on the Earth\'s surface.','E = σ/ε₀ gives σ ≈ 8.85 × 10⁻¹² × 100 ≈ 9 × 10⁻¹⁰ C/m². Times the surface area 5 × 10¹⁴ m², that is about 5 × 10⁵ C (negative).']]},
{id:'y3',t:5,l:2,q:'Why do water pipes burst when they freeze?',
 h:['What happens to the volume of water when it turns to ice?',
    'The pipe stops the ice expanding. Think about which part of the pipe the pressure actually builds up in.'],
 a:'<p>Water expands by about 9% when it freezes. In a sealed section, the ice cannot expand, so the pressure rises enormously, in principle to thousands of atmospheres, far beyond what a pipe can withstand.</p><p>Often the burst happens where the water is still liquid: ice plugs form and trap water between them and a closed tap, and further freezing squeezes that trapped water until the pipe splits.</p>',
 f:[['Why does lagging pipes help, even though insulation produces no heat?','It slows the rate of heat loss, so the water takes much longer to cool to 0 °C, often long enough to get through a cold night.'],
    ['Why does leaving a tap dripping help?','Moving water brings in warmer water and relieves the pressure between ice plugs, so a burst is much less likely.']]},
{id:'y4',t:7,l:2,q:'Why does popcorn pop, and why at around 180 °C rather than 100 °C?',
 h:['Each kernel contains a little water inside a tough, sealed hull.',
    'What happens to the boiling point of water when it is kept under pressure?'],
 a:'<p>The kernel holds about 14% water inside a tough, nearly airtight hull. As it heats, the water cannot escape, so the pressure rises and the water stays liquid well above 100 °C.</p><p>At about 180 °C the vapour pressure reaches roughly 9–10 atmospheres and the hull ruptures. The superheated water flashes to steam, and the expanding steam puffs the softened starch into foam, which sets as it cools.</p>',
 f:[['Why do some kernels never pop?','Their hulls are cracked or leaky, so steam escapes gradually, or they have dried out and have too little water.'],
    ['How is this related to a pressure cooker?','Both raise the boiling point by raising the pressure: about 120 °C at 2 atmospheres in a pressure cooker.']]}
);
PHY.push(
{id:'z1',t:6,l:2,q:'Why do we always see the same face of the Moon?',
 h:['Does the Moon spin at all? Compare its rotation period with its orbital period.',
    'The Earth raises tides in the Moon, just as the Moon raises tides in the Earth. What would tidal friction do to a spin that did not match the orbit?'],
 a:'<p>The Moon <b>does</b> rotate: once per orbit (about 27 days), so the same side always faces us. This is called tidal locking.</p><p>Earth\'s gravity stretches the Moon into a slight bulge along the Earth–Moon line. If the Moon spun faster or slower than it orbits, the bulge would be dragged off that line; Earth\'s pull on the misaligned bulge gives a torque that speeds up or slows down the spin, and internal friction dissipates the energy, until the spin matches the orbit. Then the bulge stays put and the torque vanishes.</p><p>Tutors like it if you notice that "not rotating" would actually show us every side.</p>',
 f:[['The Moon raises tides on Earth too. What is that doing to the length of our day?','Tidal friction is slowing Earth\'s spin: the day lengthens by about 2 ms per century. The angular momentum goes into the Moon\'s orbit, so the Moon recedes (about 4 cm per year).'],
    ['Will the Earth eventually always show the same face to the Moon?','In principle yes, when Earth\'s day equals the (by then longer) month, but it would take far longer than the Sun\'s remaining lifetime.']]},
{id:'z2',t:4,l:2,q:'A magnet is dropped down a vertical copper pipe. It falls much more slowly than outside the pipe. Explain why, and estimate what decides its speed.',
 h:['Copper is not magnetic. What happens in a conductor when the magnetic flux through it changes?',
    'Lenz\'s law: in which direction do the induced currents push the magnet? What happens to their size as the magnet speeds up?'],
 a:'<p>As the magnet falls, the flux through each ring of the pipe changes, so currents (eddy currents) are induced in the copper. By Lenz\'s law they oppose the change: the ring below repels the magnet and the ring above attracts it, so there is an upward force.</p><p>The induced emf, and so the current and the force, grow with speed: the drag is roughly proportional to v. The magnet speeds up until the drag equals its weight, then falls at a steady <b>terminal speed</b>, which is lower for thicker, better-conducting pipes and stronger magnets.</p><p>Energy check: gravitational energy goes into heating the pipe instead of kinetic energy.</p>',
 f:[['What happens if the pipe has a slit cut along its length?','The currents cannot circulate round the pipe, so the braking is much weaker and the magnet falls faster.'],
    ['Would the effect be stronger or weaker in a cold pipe (say in liquid nitrogen)?','Stronger: copper\'s resistivity falls when it is cooled, so larger currents flow and the terminal speed is lower.']]},
{id:'z3',t:5,l:3,q:'(University level) Estimate how long a cup of tea takes to cool from 80 °C to 60 °C in a room at 20 °C.',
 h:['Newton\'s law of cooling: the rate of heat loss is proportional to the temperature difference with the room. What shape of curve does that give?',
    'Estimate the heat loss at the start. A mug of tea loses heat at roughly 15 W when it is about 60 °C above the room. Its heat capacity is about 0.3 kg × 4200 J/(kg K).'],
 a:'<p>Heat capacity C ≈ 0.3 × 4200 ≈ 1300 J/K. If the loss is P = kΔT with P ≈ 15 W at ΔT = 60 K, then k ≈ 0.25 W/K.</p><p>Then ΔT falls exponentially: ΔT = ΔT₀e^(−t/τ), with τ = C/k ≈ 5000 s. Going from ΔT = 60 K to 40 K needs t = τ ln(60/40) ≈ 5000 × 0.4 ≈ 2000 s, roughly <b>half an hour</b>.</p><p>Sanity check: experience says 20–30 minutes; evaporation from the open surface makes real tea cool faster at first.</p>',
 f:[['Should you add the milk at the start or just before drinking, if you want the tea as hot as possible later on?','Add it at the start: the hotter tea loses heat faster, so cooling it with milk early reduces the losses afterwards.'],
    ['What is the time constant τ, physically?','The time for the temperature difference to fall to 1/e (about 37%) of its value: it is the heat capacity divided by the heat-loss coefficient.']]},
{id:'z4',t:3,l:1,q:'Why does a straw look bent where it enters a glass of water?',
 h:['Light from the part of the straw under water has to leave the water to reach your eye. What happens at the surface?',
    'Your brain assumes light travels in straight lines. Trace a ray back from your eye.'],
 a:'<p>Light from the submerged part of the straw refracts away from the normal as it leaves the water (water has a higher refractive index than air). Your brain traces the rays back in straight lines, so they appear to come from a point closer to the surface than the straw really is.</p><p>So the submerged part looks raised and the straw looks bent at the surface. For the same reason a pool looks shallower than it is: about 3/4 of its real depth when viewed from directly above (1/1.33).</p>',
 f:[['Why does the effect get stronger when you look at a shallow angle?','Refraction increases with the angle of incidence, so the apparent raising of the straw is larger for rays leaving at a glancing angle.'],
    ['A fish looking up sees the whole sky squeezed into a circle. Why?','Light from all directions above enters within the critical angle (about 49°), so the sky appears in a cone of half-angle 49°; outside it, the fish sees reflections of the bottom.']]}
);
PHY.push(
{id:'j1',t:1,l:2,q:'You stand on bathroom scales in a lift. Describe what the scales read as the lift starts, travels and stops on the way up.',
 h:['The scales measure the normal contact force on you, not your weight.',
    'Apply F = ma to yourself in each stage, taking upwards as positive.'],
 a:'<p>The scales read the normal force N. Newton\'s second law for you: N − mg = ma.</p><p><b>Starting upwards</b> (accelerating up): N = m(g + a), more than your weight. <b>Steady speed</b>: a = 0, so N = mg, the normal reading. <b>Slowing to a stop</b> (accelerating down): N = m(g − a), less than your weight.</p><p>With a = 1 m/s² and m = 60 kg: about 66 kg, 60 kg, then 54 kg on the dial. Tutors look for a clear free-body diagram and the point that only acceleration matters, not velocity.</p>',
 f:[['What would the scales read if the cable snapped?','Zero: you and the scales both fall with acceleration g, so there is no contact force. That is "weightlessness", as in orbit.'],
    ['Could the scales tell you whether the lift is moving up at constant speed or standing still?','No: both have zero acceleration, so the reading is mg either way. Only acceleration is detectable from inside.']]},
{id:'j2',t:2,l:2,q:'Without a calculator, which is bigger: 2^(100) or 10^(30)?',
 h:['2^(10) is a number you probably know, and it is close to a power of 10.',
    '2^(10) = 1024 ≈ 10³. How much bigger than 10³ is it, and what happens when you raise that to the 10th power?'],
 a:'<p>2^(100) = (2^(10))^(10) = 1024^(10) = 10^(30) × 1.024^(10).</p><p>1.024^(10) ≈ 1 + 10 × 0.024 ≈ 1.27 (a little more, actually), which is more than 1. So <b>2^(100) is bigger</b>, by about 27%. (The exact value is 1.27 × 10^(30).)</p><p>Tutors like the binomial approximation (1 + x)ⁿ ≈ 1 + nx and a comment on when it is valid (nx small).</p>',
 f:[['How many digits does 2^(100) have?','31: it is about 1.27 × 10^(30).'],
    ['Estimate log₁₀ 2 from this.','2^(10) ≈ 10³ gives log₁₀ 2 ≈ 0.3 (the true value is 0.301).']]},
{id:'j3',t:7,l:1,q:'Why does a spoon feel colder than a wooden table, even though they are at the same temperature?',
 h:['What does your skin actually sense: temperature, or something else?',
    'Compare how quickly metal and wood conduct heat away from the patch of skin touching them.'],
 a:'<p>Your skin senses the rate at which it loses heat (and so its own temperature), not the temperature of the object.</p><p>Metal is a far better thermal conductor than wood (roughly 1000 times for steel versus pine), so it carries heat away from your skin much faster. The skin at the contact cools quickly and the spoon feels cold; wood barely draws heat, so the skin surface stays warm.</p><p>On a hot day the opposite happens: metal in the sun feels hotter than wood at the same temperature.</p>',
 f:[['At what temperature would the spoon and wood feel the same?','At skin temperature (about 33 °C): no heat flows, so neither feels hot or cold.'],
    ['Why do tiles feel colder than carpet on bare feet?','The same reason: tile conducts heat away faster, and carpet traps air, a very poor conductor.']]},
{id:'j4',t:4,l:3,q:'(University level) Estimate the drift speed of electrons in a copper wire carrying 1 A. Why does the light come on instantly?',
 h:['I = nAvq. Copper has about 10²⁹ free electrons per m³. Take a wire 1 mm² in cross-section.',
    'What actually travels along the wire quickly when you close the switch?'],
 a:'<p>v = I/(nAq) = 1 / (10²⁹ × 10⁻⁶ × 1.6 × 10⁻¹⁹) ≈ <b>6 × 10⁻⁵ m/s</b>, less than a tenth of a millimetre per second.</p><p>The light comes on at once because the wire is already full of free electrons. Closing the switch sets up an electric field along the whole circuit at nearly the speed of light, so electrons everywhere, including in the filament, start drifting together. It is like pushing a full hosepipe: water comes out at the far end immediately.</p>',
 f:[['How does the drift speed change if the wire is half the diameter but carries the same current?','The area is a quarter, so the drift speed is four times larger.'],
    ['Why is the drift speed so small compared with the electrons\' thermal speeds (about 10⁶ m/s)?','The random thermal motion averages to zero; the field adds only a tiny net drift on top, because collisions with the lattice constantly reset it.']]}
);
PHY.push(
{id:'c1',t:5,l:2,q:'Why does a bicycle pump get hot when you pump up a tyre quickly?',
 h:['Think about the air inside the pump, not just friction. What are you doing to that gas?',
    'First law of thermodynamics: ΔU = Q + W (work done on the gas). If the compression is quick, is there time for heat to escape?'],
 a:'<p>Each stroke compresses the air quickly. Work is done <b>on</b> the gas, and because the stroke is fast there is little time for heat to flow out (nearly adiabatic), so the work goes into internal energy: the air gets hotter.</p><p>For air compressed to about a third of its volume adiabatically, T rises by a factor of 3^(0.4) ≈ 1.55, from 290 K to about 450 K in principle. In practice the barrel takes heat away, so the end of the pump near the valve gets warm rather than scalding. Friction of the piston adds a little, but the compression is the main effect.</p>',
 f:[['Why does gas escaping from an aerosol can feel cold?','The gas expands and does work on the surroundings, so its internal energy and temperature fall (and the liquid propellant evaporating takes latent heat too).'],
    ['If you pumped very slowly, would the pump still warm up?','Much less: slow compression is close to isothermal, with heat leaking away as fast as work is done.']]},
{id:'c2',t:6,l:3,q:'(University level) Estimate the escape velocity from the Moon, and explain why the Moon has almost no atmosphere.',
 h:['Escape velocity: ½mv² = GMm/R. The Moon\'s mass is about 7 × 10²² kg and its radius about 1.7 × 10⁶ m.',
    'Compare it with the typical speed of gas molecules. In daytime the lunar surface reaches about 390 K. Use ½m(c_rms)² = (3/2)kT. How does a tail of fast molecules matter over billions of years?'],
 a:'<p>v = √(2GM/R) = √(2 × 6.7 × 10⁻¹¹ × 7 × 10²² / 1.7 × 10⁶) ≈ √(5.5 × 10⁶) ≈ <b>2.4 km/s</b> (Earth: 11.2 km/s).</p><p>For nitrogen at 390 K: c_rms = √(3kT/m) = √(3 × 1.38 × 10⁻²³ × 390 / 4.7 × 10⁻²⁶) ≈ 590 m/s, only about a quarter of the escape speed. That sounds safe, but the Maxwell–Boltzmann distribution has a tail of much faster molecules; a gas is lost over geological time if its rms speed is more than about 1/6 of escape speed. Light gases like hydrogen and helium go fast; heavier ones leak too over 4 billion years, helped by solar wind and no magnetic field.</p><p>Tutors look for the comparison with molecular speeds and the idea that the fast tail matters, not the average.</p>',
 f:[['Why has Earth kept nitrogen and oxygen but lost almost all its hydrogen?','Hydrogen molecules are 14–16 times lighter, so at the same temperature their rms speed is about 4 times greater, enough for the tail to escape steadily.'],
    ['Titan, Saturn\'s moon, is smaller than Earth yet has a thick atmosphere. Why?','It is very cold (about 94 K), so molecules move slowly, and it is far from the Sun\'s solar wind.']]},
{id:'c3',t:3,l:2,q:'A tuning fork is struck and held in the air: you can barely hear it. Press its base on a table and it becomes much louder. Where does the extra sound energy come from, and what is the catch?',
 h:['The fork\'s prongs are thin. How well does a thin vibrating object push air around?',
    'If more energy is radiated per second, what must happen to how long the fork rings?'],
 a:'<p>No energy is created. The thin prongs move very little air, so they radiate sound inefficiently. Pressing the base on the table makes the large table top vibrate too, and a large surface couples to the air much better, so energy is radiated as sound at a much higher <b>rate</b>.</p><p>The catch: the fork\'s vibration energy is used up faster, so it is louder but <b>dies away sooner</b>. Guitar bodies and violin soundboards work in the same way.</p>',
 f:[['Why do the two prongs of a tuning fork make so little sound on their own?','They move in opposite directions, so the pressure waves they make largely cancel; it behaves like a quadrupole, a very weak radiator.'],
    ['Why does a tuning fork give a nearly pure note?','Its shape strongly favours one mode of vibration; the higher modes are not harmonics and die away quickly after it is struck.']]},
{id:'c4',t:0,l:1,q:'Estimate how many breaths you take in a year, and the total volume of air you breathe.',
 h:['How many breaths per minute at rest? About how much air per breath?',
    'Roughly 12–15 breaths a minute and half a litre each at rest.'],
 a:'<p>About 15 breaths per minute × 60 × 24 × 365 ≈ 15 × 5 × 10⁵ ≈ <b>8 × 10⁶ breaths a year</b>.</p><p>At 0.5 L each that is 4 × 10⁶ L, about <b>4000 m³</b> of air a year: roughly the volume of a large house, or 1.5 Olympic swimming pools. Exercise would raise it noticeably, so call it 4000–6000 m³.</p>',
 f:[['How many molecules are in one breath?','0.5 L is about 1/48 of a mole (24 L per mole at room conditions), so about 1.3 × 10²² molecules.'],
    ['Estimate the mass of oxygen you use in a day.','About 20% of the air is oxygen, and only about a quarter of that is absorbed: roughly 10 000 L of air a day gives about 500 L of O₂, around 0.7 kg.']]}
);
PHY.push(
{id:'f1',t:1,l:2,q:'A ladder leans against a smooth wall on a rough floor. Why is it more likely to slip when you climb near the top?',
 h:['Draw the forces: weight of the ladder, your weight, the wall\'s push (horizontal, since the wall is smooth), and the floor\'s normal force and friction.',
    'Take moments about the foot of the ladder. What happens to the wall\'s push as your weight moves higher up?'],
 a:'<p>The smooth wall can only push horizontally, with force N_w. Horizontal balance: friction at the floor F = N_w. Vertical balance: the floor\'s normal force R = total weight, which does not depend on where you stand.</p><p>Moments about the foot: N_w × (height of top) = (weights) × (their horizontal distances from the foot). As you climb, your horizontal distance from the foot grows, so N_w grows, and so does the friction needed. Friction is limited to μR, which stays fixed, so near the top the required friction can exceed μR and the ladder slips.</p><p>Tutors look for a clear diagram and the choice of the foot as the pivot (it removes two unknown forces).</p>',
 f:[['Why is a steeper ladder safer?','The horizontal distances of the weights from the foot are smaller relative to the height, so N_w and the friction needed are smaller.'],
    ['Why does someone standing on the bottom rung help?','It adds to R (and so the maximum friction μR) without adding much moment, because their weight acts close to the foot.']]},
{id:'f2',t:4,l:2,q:'Why do birds sitting on a high-voltage power line not get electrocuted, but a person touching the line from a ladder would?',
 h:['What does a current need to flow through the bird?',
    'Compare the potential difference between the bird\'s two feet with the potential difference between the line and the ground.'],
 a:'<p>Current flows through a body only if there is a potential difference across it. The bird\'s feet are a few centimetres apart on the same wire. The wire has a tiny resistance, so even with hundreds of amps the pd between the feet is only millivolts: almost no current flows through the bird.</p><p>A person on a ladder touches the line (hundreds of kilovolts) while connected to the ground at 0 V, so there is a huge pd across their body and a lethal current flows.</p><p>For a 400 A current in a line with resistance of about 5 × 10⁻⁵ Ω per metre, 5 cm of wire gives V = IR ≈ 400 × 2.5 × 10⁻⁶ ≈ 1 mV.</p>',
 f:[['Why are large birds sometimes killed on power lines anyway?','Their wingspan can bridge two conductors at different potentials, or a conductor and an earthed pylon.'],
    ['Why do engineers working on live lines wear conducting suits?','The suit (a Faraday cage) keeps the whole body at the line\'s potential, so no pd appears across them and the current flows through the suit.']]},
{id:'f3',t:7,l:1,q:'Why does a hot-air balloon rise, and why do balloon flights usually happen early in the morning?',
 h:['Archimedes: the upthrust equals the weight of the air displaced. How does the density of the hot air inside compare with the cooler air outside?',
    'The lift depends on the temperature difference between inside and outside. When is the outside air coolest and calmest?'],
 a:'<p>Heating the air inside lowers its density (ρ ∝ 1/T at constant pressure). The envelope displaces a large volume of cooler, denser air, so the upthrust exceeds the weight of the hot air plus the balloon, basket and passengers.</p><p>Example: 2500 m³ of air at 15 °C has a mass of about 3000 kg; at 100 °C inside, the same volume holds about 2300 kg, giving roughly 700 kg of lift. Early mornings are cool (more lift for the same burner temperature) and usually calm, before the Sun heats the ground and causes gusts and thermals.</p>',
 f:[['How does the balloon descend?','The pilot lets the air cool or opens a vent at the top, so the inside density increases and the upthrust exceeds the weight by less, or not at all.'],
    ['Would a hot-air balloon work better on a high mountain?','Worse: the outside air is less dense there, so the same volume displaces less mass and the lift is smaller.']]},
{id:'f4',t:2,l:3,q:'(University level) Show that the sum 1 + 1/2 + 1/3 + 1/4 + … grows without limit, and estimate how many terms are needed for the sum to exceed 10.',
 h:['Group the terms: 1/3 + 1/4, then 1/5 to 1/8, then 1/9 to 1/16. Compare each group with 1/2.',
    'For the estimate, compare the sum with ∫ dx/x from 1 to n.'],
 a:'<p>Each group 1/(2^(k)+1) + … + 1/2^(k+1) has 2^(k) terms, each at least 1/2^(k+1), so each group is at least 1/2. There are infinitely many groups, so the sum <b>diverges</b>, even though the terms go to zero.</p><p>The sum of the first n terms is close to ln n + 0.577. Setting ln n ≈ 10 − 0.58 gives n ≈ e^(9.42) ≈ <b>12 000 terms</b> (the exact answer is 12 367). It grows incredibly slowly: to reach 100 you would need about 10^(43) terms.</p>',
 f:[['Does 1 + 1/4 + 1/9 + 1/16 + … also diverge?','No: compare with ∫ dx/x² from 1, which is finite. It converges, to π²/6 ≈ 1.645.'],
    ['How far can a stack of identical blocks overhang the edge of a table?','As far as you like: the n-th block from the top can overhang by L/(2n), and the harmonic series diverges, but you need enormous numbers of blocks.']]}
);
PHY.push(
{id:'i1',t:5,l:2,q:'Why does sweating cool you down, and why does it work badly on a humid day?',
 h:['What does water need in order to evaporate from your skin, and where does that energy come from?',
    'Evaporation is a net flow of molecules from liquid to air. What happens to that net flow if the air is already nearly saturated with water vapour?'],
 a:'<p>Evaporating water needs latent heat, about 2.4 MJ per kg at skin temperature. It takes that energy from your skin, so you cool down. In molecular terms, the fastest molecules escape, lowering the average kinetic energy of those left behind.</p><p>Evaporating 0.5 kg of sweat an hour removes about 1.2 MJ, roughly 330 W, enough to dump the heat of hard exercise. On a humid day the air already holds nearly as much vapour as it can, so almost as many molecules return to the skin as leave it. The net evaporation, and the cooling, are small: the sweat just drips off.</p>',
 f:[['Why does a fan help even though it does not cool the air?','It replaces the humid air next to your skin with drier air, increasing the net evaporation (and convection).'],
    ['Why do dogs pant instead of sweating?','They have few sweat glands; panting evaporates water from the tongue and airways, using the same latent-heat cooling.']]},
{id:'i2',t:6,l:2,q:'Astronauts on the International Space Station float. Is gravity there much weaker than on Earth?',
 h:['The ISS orbits about 400 km up, and the Earth\'s radius is 6400 km. How does g depend on distance from the centre?',
    'If gravity is still strong there, why do the astronauts feel weightless?'],
 a:'<p>g ∝ 1/r²: g = 9.8 × (6400/6800)² ≈ <b>8.7 N/kg</b>, about 89% of its surface value. Gravity is barely weaker.</p><p>They float because they and the station are in free fall together: both accelerate towards the Earth at the same rate, so there is no contact force between them, and contact forces are what we feel as weight. The station moves sideways at about 7.7 km/s, so it keeps "falling around" the Earth instead of into it.</p><p>Tutors want the distinction between gravitational force and the feeling of weight.</p>',
 f:[['How high would you need to go for g to be half its surface value?','r = 6400 × √2 ≈ 9050 km from the centre, about 2650 km above the surface.'],
    ['Would a pendulum clock work on the ISS?','No: in free fall there is no effective restoring force, so it would not swing.']]},
{id:'i3',t:0,l:2,q:'Estimate how many litres of water are used to flush toilets in the UK each day.',
 h:['How many people, how many flushes each per day, and how much water per flush?',
    'Roughly 67 million people, about 5 flushes each per day (some at work or school), and about 6 litres per modern flush (older cisterns use more).'],
 a:'<p>67 × 10⁶ × 5 × 6 L ≈ <b>2 × 10⁹ litres a day</b>, about 2 million cubic metres.</p><p>That is roughly 800 Olympic swimming pools a day, or about a fifth of all household water use. Sanity check: UK homes use about 140 litres per person per day in total, and toilets are often quoted as about a quarter of that, which gives about 35 litres per person, in line with 5 × 6 = 30.</p>',
 f:[['How much would switching every toilet to a 4-litre dual flush save per year?','2 litres × 5 × 67 × 10⁶ × 365 ≈ 2.4 × 10¹¹ litres, about a quarter of a cubic kilometre.'],
    ['Estimate the energy used to pump that water to homes, if it takes about 0.5 kWh per cubic metre.','2 × 10⁶ m³ × 0.5 kWh ≈ 10⁶ kWh per day, about 40 MW on average.']]},
{id:'i4',t:3,l:3,q:'(University level) Why is the sky blue, but sunsets red? Use the fact that scattering by molecules goes as 1/λ⁴.',
 h:['Compare how strongly blue light (450 nm) and red light (700 nm) are scattered.',
    'At sunset the light travels through much more atmosphere to reach you. What happens to the blue part along the way?'],
 a:'<p>(700/450)⁴ ≈ 5.9, so blue light is scattered about <b>six times</b> more than red by air molecules (Rayleigh scattering). Looking away from the Sun, you see light scattered towards you: mostly blue, so the sky looks blue.</p><p>At sunset, sunlight crosses tens of times more air. Most of the blue is scattered out of the direct beam before it reaches you, leaving the red and orange: the setting Sun and the clouds it lights look red.</p><p>Violet scatters even more, but the sky is not violet because sunlight has less violet, some is absorbed high up, and our eyes are less sensitive to it.</p>',
 f:[['Why are clouds white rather than blue?','Cloud droplets are much larger than the wavelength of light, so they scatter all colours about equally (Mie scattering).'],
    ['What colour is the sky on the Moon, and why?','Black: there is no atmosphere to scatter sunlight.']]}
);
PHY.push(
{id:'k1',t:1,l:2,q:'A 70 kg bungee jumper falls from rest on a cord 20 m long with a stiffness of 200 N/m. Find the maximum extension of the cord and the jumper\'s greatest acceleration. (g = 9.8 m/s²)',
 h:['At the lowest point the jumper is momentarily at rest. Use energy conservation from the top to the bottom: gravitational PE lost = elastic energy stored.',
    'The jumper falls (20 + x) metres in total, and the cord stores ½kx². Solve the quadratic for x. The greatest acceleration is at the bottom, where the cord pulls hardest.'],
 a:'<p>Energy: mg(20 + x) = ½kx², so 686(20 + x) = 100x², giving 100x² − 686x − 13 720 = 0.</p><p>x = (686 + √(686² + 4 × 100 × 13 720))/200 = (686 + 2441)/200 ≈ <b>15.6 m</b>, so the lowest point is about 35.6 m below the platform.</p><p>At the bottom: net upward force = kx − mg = 200 × 15.6 − 686 ≈ 2440 N, so a ≈ 2440/70 ≈ <b>35 m/s² ≈ 3.6 g</b> upwards. Sanity check: the equilibrium extension is mg/k = 3.4 m, and the jumper overshoots it by far, as expected after a 20 m free fall.</p>',
 f:[['Where is the jumper moving fastest?','At the equilibrium point, 20 + 3.4 = 23.4 m down, where the net force is zero: ½mv² = mg(23.4) − ½k(3.4)², giving v ≈ 20.6 m/s.'],
    ['Why do bungee cords use a soft, long cord rather than a stiff one?','A smaller k gives a larger stopping distance, so a smaller maximum force and acceleration for the same energy.']]},
{id:'k2',t:1,l:1,q:'A car travels at 30 m/s (about 70 mph). The driver reacts in 0.7 s and the brakes give a friction coefficient of 0.7. Find the total stopping distance. What happens at twice the speed? (g = 9.8 m/s²)',
 h:['Split it into thinking distance (constant speed during the reaction time) and braking distance.',
    'Maximum braking deceleration = μg. Then v² = u² − 2as with v = 0.'],
 a:'<p>Thinking distance = 30 × 0.7 = 21 m. Deceleration = 0.7 × 9.8 ≈ 6.9 m/s², so braking distance = 30²/(2 × 6.9) ≈ 65 m. Total ≈ <b>86 m</b>, about 20 car lengths.</p><p>At 60 m/s the thinking distance doubles (42 m) but the braking distance <b>quadruples</b> (about 260 m), because it goes as v². Total ≈ 300 m.</p><p>Mass cancels: heavy and light cars brake equally well if their tyres grip equally (in practice lorries take longer).</p>',
 f:[['How does a wet road (μ = 0.4) change the braking distance at 30 m/s?','30²/(2 × 3.9) ≈ 115 m, nearly twice as far.'],
    ['How much heat do the brakes absorb for a 1200 kg car stopping from 30 m/s?','½ × 1200 × 900 = 540 kJ, enough to heat 1.5 kg of brake disc (c = 450) by about 800 K, which is why brakes can fade on long descents.']]},
{id:'k3',t:6,l:2,q:'How short would the Earth\'s day have to be for objects at the equator to become weightless? (g = 9.8 m/s², Earth\'s radius 6.4 × 10⁶ m)',
 h:['An object on the equator moves in a circle. When would gravity alone be just enough to provide the centripetal force?',
    'Set g = ω²R and find T = 2π/ω.'],
 a:'<p>Weightless when mg = mω²R, so ω = √(g/R) = √(9.8/6.4 × 10⁶) ≈ 1.24 × 10⁻³ rad/s.</p><p>T = 2π/ω ≈ <b>5100 s ≈ 85 minutes</b>, the same as the period of a satellite skimming the surface (which makes sense: you would be in orbit while standing still).</p><p>Today ω²R ≈ 0.034 m/s², so the equator already reduces your apparent weight by about 0.3%.</p>',
 f:[['By how much does the Earth\'s spin reduce the apparent weight of a 60 kg person at the equator today?','m ω²R = 60 × 0.034 ≈ 2 N, about 0.35%.'],
    ['Why is the Earth wider at the equator than pole to pole?','Its spin reduces the effective gravity at the equator, so the planet bulges there, by about 21 km in radius.']]},
{id:'k4',t:4,l:1,q:'An electric car has a 60 kWh battery and a range of 400 km. It charges from a 7 kW home charger. How long does a full charge take, what current flows at 230 V, and what does each kilometre cost at 25p per kWh?',
 h:['Time = energy / power (ignoring charging losses).',
    'I = P/V. Cost per km = (energy per km) × (price per kWh).'],
 a:'<p>Time = 60/7 ≈ <b>8.6 hours</b> (overnight). Current = 7000/230 ≈ <b>30 A</b>, more than a normal socket (13 A), which is why chargers need their own circuit.</p><p>Energy per km = 60/400 = 0.15 kWh, so the cost ≈ 0.15 × 25p ≈ <b>3.75p per km</b>. A petrol car using 6 L per 100 km at £1.50 per litre costs about 9p per km.</p><p>In practice charging is about 90% efficient, so allow roughly 10% more time and cost.</p>',
 f:[['How fast could a 150 kW rapid charger fill the battery from 20% to 80%?','36 kWh / 150 kW ≈ 0.24 h ≈ 15 minutes (in practice slower, as charging rate drops near full).'],
    ['How much energy is in the 60 kWh battery in joules, and to what height could it lift the 2000 kg car?','2.16 × 10⁸ J; h = E/(mg) ≈ 2.16 × 10⁸ / 19 600 ≈ 11 km.']]}
);
/* ---- Calculation rewrites (owner's request, 5 Nov 2026) ----
   54 questions rewritten in place as numerical problems: the 12 that duplicated other questions, plus most of the
   purely verbal ones. Same ids (so saved questions and links still work); their old spaced-repetition ratings are
   cleared once (key 'phy-calc') because the content changed. */
const PHY_CALC={
/* ---- replacements for duplicated questions ---- */
z1:{t:6,l:2,q:`A geostationary satellite orbits once every 24 hours. Calculate the radius of its orbit and its height above the ground. (GM for the Earth = 4.0 × 10¹⁴ m³ s⁻², Earth's radius 6400 km)`,
 h:[`Gravity provides the centripetal force: GMm/r² = mω²r. What is ω for one turn in 24 hours?`,
    `Rearrange to r³ = GM/ω² (equivalently GMT²/4π²). T = 86 400 s.`],
 a:`<p>ω = 2π/86 400 ≈ 7.27 × 10⁻⁵ rad/s. Then r³ = GM/ω² = 4.0 × 10¹⁴ / 5.3 × 10⁻⁹ ≈ 7.6 × 10²² m³, so <b>r ≈ 4.2 × 10⁷ m</b> (42 000 km).</p><p>Height = 42 000 − 6400 ≈ <b>36 000 km</b>, about 5.6 Earth radii up. Speed v = ωr ≈ 3.1 km/s, much slower than low orbit (7.7 km/s), as expected since v ∝ 1/√r.</p><p>Strictly the Earth turns once in a sidereal day (23 h 56 min), which changes the answer by less than 1%.</p>`,
 f:[[`Why must a geostationary satellite be above the equator?`,`Its orbit must be centred on the Earth's centre and keep pace with a point on the surface; only an equatorial orbit stays over the same point.`],
    [`How long does a radio signal take to go up to it and back down?`,`About 2 × 36 000 km / 3 × 10⁵ km/s ≈ 0.24 s, which is why satellite phone calls have a noticeable delay.`]]},
z4:{t:3,l:2,q:`Light of wavelength 600 nm falls on a diffraction grating with 300 lines per mm. How many bright maxima can you see in total, and at what angle is the first order?`,
 h:[`Find the slit spacing d from the number of lines per metre.`,
    `d sinθ = nλ, and sinθ cannot exceed 1. What is the largest whole number n?`],
 a:`<p>d = 1/(3 × 10⁵) m = 3.33 × 10⁻⁶ m. First order: sinθ = λ/d = 6 × 10⁻⁷ / 3.33 × 10⁻⁶ = 0.18, so <b>θ ≈ 10.4°</b>.</p><p>Largest order: n ≤ d/λ = 5.55, so n = 5. Counting both sides and the central maximum: 5 + 5 + 1 = <b>11 maxima</b>.</p><p>Tutors like it if you notice the higher orders get spread out (sinθ grows linearly, θ grows faster) and dimmer.</p>`,
 f:[[`What changes if you use blue light of 450 nm instead?`,`The maxima are closer together (θ₁ ≈ 7.8°) and n_max = 7, so you see 15 maxima.`],
    [`Why does a grating give much sharper maxima than two slits?`,`Light from hundreds of slits only adds up exactly at the angles nλ = d sinθ; slightly away from them the contributions cancel, so the peaks are very narrow.`]]},
i1:{t:5,l:1,q:`An electric shower heats water from 10 °C to 40 °C at a flow rate of 8 litres per minute. What power does it need? Is a 9 kW shower enough? (c = 4200 J kg⁻¹ K⁻¹)`,
 h:[`Work out the mass of water heated per second.`,
    `Power = (mass per second) × c × ΔT.`],
 a:`<p>8 L/min = 8 kg/min ≈ 0.133 kg/s. P = 0.133 × 4200 × 30 ≈ <b>17 kW</b>.</p><p>A 9 kW shower can only heat about 4.3 L/min by 30 K, which is why electric showers often feel feeble in winter, when the mains water is colder. Sanity check: a kettle (3 kW) takes minutes to heat 1 L, so heating 8 L a minute needs several kettles' worth of power.</p><p>The current at 230 V would be 17 000/230 ≈ 74 A, far more than a domestic circuit allows, so homes use gas boilers or stored hot water for powerful showers.</p>`,
 f:[[`How much does a 10-minute, 9 kW shower cost at 25p per kWh?`,`9 kW × 1/6 h = 1.5 kWh, about 38p.`],
    [`Why does the water get hotter if you reduce the flow?`,`The same power heats less water per second, so ΔT = P/(ṁc) increases.`]]},
i4:{t:3,l:2,q:`An ambulance siren emits 1000 Hz and approaches you at 30 m/s. What frequency do you hear, and what do you hear after it passes? (speed of sound 340 m/s)`,
 h:[`While the source moves towards you, the wavefronts are squashed together: the wavelength in front is (v − u)/f.`,
    `So the observed frequency is f' = f v/(v − u) approaching, and f v/(v + u) receding.`],
 a:`<p>Approaching: f' = 1000 × 340/310 ≈ <b>1097 Hz</b>. Receding: f' = 1000 × 340/370 ≈ <b>919 Hz</b>.</p><p>So the pitch drops by about 180 Hz, roughly a musical tone and a half, as it passes. For u ≪ v both shifts are about ±f u/v ≈ ±88 Hz, a quick check.</p><p>The same principle in light (Δf/f ≈ v/c) is how astronomers measure the speeds of stars and galaxies.</p>`,
 f:[[`What frequency would the ambulance driver hear?`,`1000 Hz: there is no relative motion between the driver and the siren.`],
    [`How fast would the ambulance need to go for the pitch heard in front to double?`,`340/(340 − u) = 2 gives u = 170 m/s, half the speed of sound.`]]},
f2:{t:4,l:1,q:`A kettle is rated at 3 kW on the 230 V mains. Find the current and the resistance of its element. Which fuse should its plug have: 3 A, 5 A or 13 A?`,
 h:[`P = VI gives the current.`,
    `R = V/I, or R = V²/P.`],
 a:`<p>I = P/V = 3000/230 ≈ <b>13 A</b>. R = V/I = 230/13 ≈ <b>18 Ω</b> (or V²/P = 52 900/3000 ≈ 17.6 Ω).</p><p>The fuse must be just above the normal current, so a <b>13 A</b> fuse. A 3 A or 5 A fuse would blow every time the kettle was switched on.</p><p>(Mains values are rms; the peak voltage is about 325 V, but power calculations use rms values.)</p>`,
 f:[[`How long does it take to boil 1 kg of water from 20 °C, ignoring losses?`,`336 kJ / 3 kW ≈ 110 s, just under 2 minutes.`],
    [`Why is the element's resistance higher when it is hot?`,`It is a metal: hotter ions vibrate more and scatter electrons more, so resistivity rises.`]]},
z2:{t:4,l:3,q:`(University level) An electron is accelerated from rest through 2000 V. Find its speed and its de Broglie wavelength. Could it be diffracted by a crystal? (e = 1.6 × 10⁻¹⁹ C, m = 9.1 × 10⁻³¹ kg, h = 6.6 × 10⁻³⁴ J s)`,
 h:[`The kinetic energy gained is eV.`,
    `λ = h/p, with p = mv (the speed is well below c, so ignore relativity).`],
 a:`<p>½mv² = eV gives v = √(2eV/m) = √(2 × 1.6 × 10⁻¹⁹ × 2000 / 9.1 × 10⁻³¹) ≈ <b>2.7 × 10⁷ m/s</b> (9% of c, so the classical formula is fine to about 0.3%).</p><p>p = mv ≈ 2.4 × 10⁻²³ kg m/s, so λ = h/p ≈ <b>2.7 × 10⁻¹¹ m</b>.</p><p>Atoms in a crystal are about 10⁻¹⁰ m apart, a few times larger than λ, so yes: the electrons diffract strongly, as in the electron-diffraction tube in school labs.</p>`,
 f:[[`What happens to the wavelength if the voltage is quadrupled?`,`v doubles, so p doubles and λ halves.`],
    [`Why are electron microscopes able to see far smaller things than light microscopes?`,`Electron wavelengths (around 10⁻¹¹ m) are thousands of times shorter than visible light (about 5 × 10⁻⁷ m), so diffraction blurs much smaller details.`]]},
c1:{t:5,l:2,q:`A car tyre is at an absolute pressure of 3.5 × 10⁵ Pa at 10 °C. After a long drive the air inside is at 40 °C. What is the new pressure, assuming the volume does not change?`,
 h:[`For a fixed mass of gas at constant volume, p/T is constant.`,
    `T must be in kelvin.`],
 a:`<p>p₂ = p₁ × T₂/T₁ = 3.5 × 10⁵ × 313/283 ≈ <b>3.87 × 10⁵ Pa</b>, an increase of about 11%.</p><p>A common mistake is to use Celsius (40/10 would wrongly quadruple the pressure). Another subtlety: tyre gauges read the pressure above atmospheric. Here the gauge would read 2.5 → 2.87 × 10⁵ Pa, which is a 15% rise in the gauge reading.</p><p>This is why tyre pressures should be checked when the tyres are cold.</p>`,
 f:[[`What would the pressure be if the tyre were taken to −20 °C?`,`3.5 × 10⁵ × 253/283 ≈ 3.13 × 10⁵ Pa.`],
    [`How many moles of air are in a 20-litre tyre at 3.5 × 10⁵ Pa and 283 K?`,`n = pV/RT = 3.5 × 10⁵ × 0.02 / (8.31 × 283) ≈ 3.0 mol, about 87 g of air.`]]},
f1:{t:1,l:1,q:`A ball is kicked at 20 m/s at 30° above the horizontal from flat ground. Find its time of flight, its range and its greatest height. (g = 10 m/s², no air resistance)`,
 h:[`Split the velocity into horizontal and vertical components.`,
    `The vertical motion decides the time: it returns to the ground when the vertical displacement is zero.`],
 a:`<p>Components: horizontal 20 cos30° ≈ 17.3 m/s, vertical 20 sin30° = 10 m/s.</p><p>Time of flight: 0 = 10t − 5t², so <b>t = 2 s</b>. Range = 17.3 × 2 ≈ <b>34.6 m</b>. Greatest height: v² = u² − 2gs gives s = 10²/20 = <b>5 m</b>, reached at t = 1 s.</p><p>Check with R = v² sin2θ/g = 400 × 0.866/10 = 34.6 m. ✓</p>`,
 f:[[`At what other angle would it land in the same place?`,`60°, since sin2θ is the same for complementary angles (it would go higher and take longer: 3.46 s).`],
    [`What is its speed at the top of its flight?`,`Only the horizontal component remains: about 17.3 m/s.`]]},
i2:{t:6,l:2,q:`Mars orbits the Sun at 1.52 times the Earth's distance. Without looking anything else up, how long is a Martian year?`,
 h:[`For circular orbits, gravity provides the centripetal force. Show that T² ∝ r³.`,
    `Compare with the Earth: T in years, r in units of the Earth–Sun distance.`],
 a:`<p>GMm/r² = m(2π/T)²r gives T² = (4π²/GM) r³, so T² ∝ r³ for everything orbiting the Sun.</p><p>Then T = 1.52^(3/2) years = 1.52 × √1.52 ≈ 1.52 × 1.23 ≈ <b>1.87 years</b> (about 687 days).</p><p>Tutors like it if you derive the law rather than quote it, and spot that the Sun's mass cancels when you compare two planets.</p>`,
 f:[[`Jupiter takes about 12 years to orbit. How far is it from the Sun?`,`r = 12^(2/3) ≈ 5.2 times the Earth's distance.`],
    [`How fast does Mars move compared with the Earth?`,`v ∝ 1/√r, so about 1/√1.52 ≈ 0.81 of the Earth's 30 km/s, roughly 24 km/s.`]]},
j1:{t:1,l:1,q:`A 1000 kg car moving at 20 m/s crashes into a stationary 1500 kg car and they lock together. Find their speed just after the crash and the kinetic energy lost.`,
 h:[`Momentum is conserved in the collision (the crash is too quick for friction to matter).`,
    `Compare the kinetic energy before and after.`],
 a:`<p>Momentum: 1000 × 20 = 2500v, so <b>v = 8 m/s</b>.</p><p>KE before = ½ × 1000 × 20² = 200 kJ. After = ½ × 2500 × 8² = 80 kJ. So <b>120 kJ (60%) is lost</b> to deformation, heat and sound.</p><p>That is why crumple zones matter: the energy has to go somewhere, and it is better spent crushing the car's front than the passengers. Kinetic energy is not conserved in collisions; momentum always is.</p>`,
 f:[[`If the collision lasts 0.1 s, what average force acts on the stationary car?`,`It gains 1500 × 8 = 12 000 kg m/s, so F = 12 000/0.1 = 120 kN.`],
    [`What would happen in a perfectly elastic collision instead?`,`The 1000 kg car would bounce back at 4 m/s and the 1500 kg car would move off at 16 m/s, with no kinetic energy lost.`]]},
f4:{t:2,l:2,q:`Carbon-14 has a half-life of 5700 years. A piece of wood has 25% of the carbon-14 of living wood. How old is it? How old would it be if 10% remained?`,
 h:[`25% is a neat number of half-lives.`,
    `For 10%, use N = N₀e^(−λt), with λ = ln2/T½, or (1/2)^(t/T½) = 0.1.`],
 a:`<p>25% = (1/2)², so two half-lives: <b>11 400 years</b>.</p><p>For 10%: t = T½ × log₂10 = 5700 × 3.32 ≈ <b>19 000 years</b>. (ln10/ln2 ≈ 2.303/0.693 ≈ 3.32.)</p><p>Sanity check: 10% lies between 12.5% (three half-lives, 17 100 years) and 6.25% (four half-lives), so the answer must be between 17 100 and 22 800 years. ✓</p>`,
 f:[[`Why is carbon dating not used for dinosaur bones?`,`After 65 million years (over 11 000 half-lives) essentially no carbon-14 is left; other isotopes with longer half-lives are used.`],
    [`What fraction remains after 1000 years?`,`(1/2)^(1000/5700) ≈ 0.886, about 89%.`]]},
j3:{t:7,l:1,q:`A 60 kg student runs up a flight of stairs 3 m high in 2.5 s. What is their power output? How does it compare with a horse (746 W)? (g = 10 m/s²)`,
 h:[`Work done against gravity = mgh.`,
    `Power = work / time. Is the real power output higher or lower than this?`],
 a:`<p>Work = 60 × 10 × 3 = 1800 J. Power = 1800/2.5 = <b>720 W</b>, almost exactly one horsepower, but only for a few seconds.</p><p>The body's real output is higher: muscles are only about 25% efficient, so the body is using roughly 3 kW of chemical energy during the sprint, which is why you get hot and out of breath.</p>`,
 f:[[`How long would it take to climb a 300 m hill at a sustainable 150 W?`,`60 × 10 × 300 = 180 kJ; 180 000/150 = 1200 s, about 20 minutes (more in practice, as walking also costs energy).`],
    [`How much chocolate (about 2 MJ per 100 g) does the stair climb "burn"?`,`1800 J × 4 (for 25% efficiency) ≈ 7 kJ, about 0.4 g: exercise burns less than people think.`]]},
/* ---- mechanics: verbal questions turned into calculations ---- */
m2:{t:1,l:1,q:`A ball is thrown at 20 m/s. Calculate its range on flat ground at 30°, 45° and 60°. Which angle gives the furthest throw, and why do 30° and 60° give the same answer? (g = 10 m/s², no air resistance)`,
 h:[`Time of flight t = 2u sinθ/g; range = (u cosθ) × t.`,
    `Combine them: R = u² sin2θ/g. What value of θ makes sin2θ largest?`],
 a:`<p>R = u² sin2θ/g = 40 sin2θ metres. At 30°: 40 × 0.866 = <b>34.6 m</b>. At 45°: 40 × 1 = <b>40 m</b>. At 60°: 40 × 0.866 = <b>34.6 m</b>.</p><p>45° is best because sin2θ peaks at 2θ = 90°. 30° and 60° tie because sin60° = sin120°: one throw is fast and flat, the other slow and high (3.46 s in the air instead of 2 s).</p><p>With air resistance the best angle is lower than 45° (often 35–40° for a ball), because drag hurts the long, high flight more.</p>`,
 f:[[`From the top of a cliff, is 45° still the best angle?`,`No: the best angle is less than 45°, because the extra fall time already gives distance; launching flatter uses more of the speed horizontally.`],
    [`How fast must you throw to reach 100 m at 45°?`,`u² = gR = 1000, so u ≈ 32 m/s.`]]},
m3:{t:1,l:2,q:`You sit in a rowing boat on a pond of area 200 m², holding a 6 kg rock of density 3000 kg/m³. You drop the rock over the side and it sinks. Does the pond level rise or fall, and by how much?`,
 h:[`While the rock is in the boat, the boat displaces extra water equal to the rock's weight. What volume is that?`,
    `On the bottom, the rock displaces only its own volume. Compare the two.`],
 a:`<p>In the boat: extra displaced water has the rock's mass, 6 kg, so 6 litres. On the bottom: the rock displaces its own volume, 6/3000 m³ = 2 litres.</p><p>So the water displaced drops by 4 litres and the level <b>falls</b> by 0.004/200 = 2 × 10⁻⁵ m = <b>0.02 mm</b>.</p><p>The level always falls, because the rock is denser than water. Tutors want to see the two displacement volumes compared clearly, not a guess.</p>`,
 f:[[`What if you dropped a 6 kg block of wood (which floats) instead?`,`No change: a floating block displaces its own weight of water whether it is in the boat or in the pond.`],
    [`What if you poured a bucket of pond water into the boat?`,`No change: the water in the boat displaces exactly its own weight, which is the water removed from the pond.`]]},
m4:{t:1,l:2,q:`A solid ball rolls without slipping down a ramp 1.0 m high. An identical block slides down an identical, frictionless ramp. Find the speed of each at the bottom. (g = 9.8 m/s²; for a solid ball, rotational KE = (2/5) × ½mv²)`,
 h:[`Both lose the same potential energy, mgh.`,
    `The rolling ball must share its energy between translation and rotation: total KE = ½mv² (1 + 2/5) = (7/10)mv².`],
 a:`<p>Sliding block: ½mv² = mgh, so v = √(2gh) = √19.6 ≈ <b>4.4 m/s</b>.</p><p>Rolling ball: (7/10)mv² = mgh, so v = √(10gh/7) = √14 ≈ <b>3.7 m/s</b>, about 85% as fast. The block wins the race.</p><p>Both answers are independent of mass and radius. Friction does no work on the rolling ball (the contact point does not slip), so energy is conserved for both.</p>`,
 f:[[`Would a hollow ball (rotational KE = (2/3) × ½mv²) be faster or slower than the solid ball?`,`Slower: v = √(6gh/5) ≈ 3.4 m/s, as more of its energy goes into rotation.`],
    [`What fraction of the rolling ball's kinetic energy is rotational?`,`(2/5)/(7/5) = 2/7, about 29%.`]]},
m6:{t:1,l:3,q:`A uniform ladder leans against a smooth wall at 60° to the floor. What is the smallest coefficient of friction between ladder and floor that stops it slipping?`,
 h:[`Forces: weight W at the middle, the wall's push N_w (horizontal, as the wall is smooth), the floor's normal force R and friction F.`,
    `Resolve vertically and horizontally, then take moments about the foot. Let the ladder's length be L.`],
 a:`<p>Vertically: R = W. Horizontally: F = N_w.</p><p>Moments about the foot: N_w × L sin60° = W × (L/2) cos60°, so N_w = W/(2 tan60°) ≈ 0.29W.</p><p>No slipping needs F ≤ μR, so μ ≥ N_w/W = 1/(2 tan60°) ≈ <b>0.29</b>. In general μ_min = 1/(2 tanθ): a steeper ladder needs less friction.</p><p>Choosing the foot as the pivot removes two unknown forces at once, which is what tutors are watching for.</p>`,
 f:[[`At what angle would a ladder start to slip on a floor with μ = 0.5?`,`tanθ = 1/(2 × 0.5) = 1, so below 45°.`],
    [`A person of the same weight as the ladder stands at the top. What μ is needed at 60° now?`,`Moments: N_w L sin60° = W(L/2)cos60° + W L cos60°, so N_w = 1.5W cot60° ≈ 0.87W. R = 2W, so μ ≥ 0.43.`]]},
m7:{t:6,l:2,q:`The ISS orbits about 400 km above the ground. Find its orbital speed and its period. (GM for the Earth = 4.0 × 10¹⁴ m³ s⁻², Earth's radius 6400 km)`,
 h:[`The orbit radius is measured from the Earth's centre.`,
    `GMm/r² = mv²/r gives v = √(GM/r); then T = 2πr/v.`],
 a:`<p>r = 6800 km = 6.8 × 10⁶ m. v = √(4.0 × 10¹⁴ / 6.8 × 10⁶) = √(5.9 × 10⁷) ≈ <b>7.7 km/s</b>.</p><p>T = 2π × 6.8 × 10⁶ / 7700 ≈ 5500 s ≈ <b>92 minutes</b>, so astronauts see about 16 sunrises a day.</p><p>The astronauts float not because gravity is weak there (g is still about 8.7 N/kg) but because they and the station are in free fall together.</p>`,
 f:[[`How much faster would it need to go to escape the Earth altogether from that height?`,`Escape speed is √2 times the orbital speed, about 10.9 km/s: an extra 3.2 km/s.`],
    [`Why does the ISS need regular boosts?`,`Thin air at 400 km causes drag, so it slowly loses height (and, oddly, speeds up as it drops to a lower orbit).`]]},
d1:{t:1,l:2,q:`A skater spins at 2 revolutions per second with arms out (moment of inertia 3.0 kg m²). They pull their arms in, reducing it to 1.0 kg m². Find the new spin rate and the change in kinetic energy. Where does the extra energy come from?`,
 h:[`With no external torque, angular momentum Iω is conserved.`,
    `Rotational KE = ½Iω². Compare before and after.`],
 a:`<p>Iω constant: 3.0 × 2 = 1.0 × ω₂, so <b>6 revolutions per second</b>.</p><p>KE = ½Iω² with ω = 2π × rev/s. Before: ½ × 3 × (4π)² ≈ 237 J. After: ½ × 1 × (12π)² ≈ 711 J. KE <b>triples</b> (it scales as L²/2I, and I fell by 3).</p><p>The extra 474 J is work done by the skater's muscles pulling the arms inwards against the tendency of the hands to fly outwards.</p>`,
 f:[[`What happens when the skater pushes their arms out again?`,`The spin slows back to 2 rev/s and the arms do negative work: the kinetic energy returns to 237 J.`],
    [`How does a diver use the same idea?`,`Tucking reduces the moment of inertia, so they spin faster; opening out before entry slows the rotation.`]]},
d3:{t:7,l:2,q:`Rain falls vertically at 5 m/s at a rate of 10 mm per hour. You need to cross 100 m. Your top surface is 0.1 m² and your front is 0.7 m². How much water hits you if you walk at 1.5 m/s, and if you run at 5 m/s?`,
 h:[`Water hitting your top depends on how long you are out in the rain: rate × area × time.`,
    `Water hitting your front is the rain sitting in the "tunnel" you sweep through: (water per m³ of air) × front area × distance. The water per m³ is (rainfall rate)/(fall speed).`],
 a:`<p>Rainfall rate: 10 mm/h = 2.8 × 10⁻⁶ m/s. Water in the air: 2.8 × 10⁻⁶ / 5 = 5.6 × 10⁻⁷ m³ per m³.</p><p>Front (same whatever your speed): 5.6 × 10⁻⁷ × 0.7 × 100 ≈ 3.9 × 10⁻⁵ m³ = <b>39 mL</b>.</p><p>Top: walking takes 67 s: 2.8 × 10⁻⁶ × 0.1 × 67 ≈ 19 mL. Running takes 20 s: about 6 mL.</p><p>Total: about <b>58 mL walking, 45 mL running</b>. Running helps, but less than people expect, because the front soaking is fixed.</p>`,
 f:[[`What if the wind blows the rain towards your back at your running speed?`,`Running at the rain's horizontal speed means no rain hits your front or back; only your top gets wet.`],
    [`Why does leaning forward help a little?`,`It reduces your effective front area facing the oncoming rain, at the cost of a slightly larger top area.`]]},
d4:{t:7,l:2,q:`Air near a running shower moves at about 3 m/s, so the curtain is pushed inwards. Estimate the pressure difference across the curtain and the force on a 1.5 m² curtain. (density of air 1.2 kg/m³)`,
 h:[`Moving air has lower pressure than still air (Bernoulli): the pressure drop is about ½ρv².`,
    `Force = pressure difference × area.`],
 a:`<p>Δp ≈ ½ × 1.2 × 3² ≈ <b>5.4 Pa</b>. Force ≈ 5.4 × 1.5 ≈ <b>8 N</b>, about the weight of 800 g: plenty to push a light curtain inwards.</p><p>The real explanation also involves the spray dragging air along with it and setting up a vortex inside the shower, which lowers the pressure inside. Atmospheric pressure is 10⁵ Pa, so this is a difference of only 0.005%.</p>`,
 f:[[`How fast would the air need to move to lift a 1 kg curtain off its rail?`,`Force 10 N over 1.5 m² needs 6.7 Pa, so v = √(2 × 6.7/1.2) ≈ 3.3 m/s, barely more.`],
    [`How does the same effect help aeroplanes fly?`,`Air flows faster over the curved upper wing surface, giving lower pressure above than below (along with the wing turning air downwards).`]]},
/* ---- thermal physics ---- */
h1:{t:5,l:2,q:`A single-glazed window is 1.5 m² with glass 4 mm thick. Inside is 20 °C and outside 0 °C. Using thermal conduction, P = kAΔT/d with k = 1.0 W m⁻¹ K⁻¹ for glass, estimate the heat loss. Why is the real loss much smaller?`,
 h:[`Plug the numbers into P = kAΔT/d.`,
    `The glass is not the only barrier: thin layers of still air cling to both surfaces. Air conducts about 40 times worse than glass.`],
 a:`<p>P = 1.0 × 1.5 × 20 / 0.004 = <b>7500 W</b>, which would need several heaters for one window!</p><p>In reality the still air films on each side (together equivalent to well over 10 cm of glass) do most of the insulating, so the real loss is closer to 150–200 W (about 6 W per m² per kelvin).</p><p>The lesson: the temperature drop happens mostly across the air layers, not the glass. Double glazing works by adding another trapped air (or argon) layer.</p>`,
 f:[[`Why does a metal bench feel colder than a wooden one at the same temperature?`,`Metal conducts heat away from your skin hundreds of times faster than wood, so your skin surface cools quickly.`],
    [`Why is the gap in double glazing only about 16 mm, not much wider?`,`In a wider gap the air starts to circulate (convection), carrying heat across and spoiling the insulation.`]]},
h2:{t:5,l:1,q:`Ice has a density of 920 kg/m³ and seawater 1025 kg/m³. What fraction of an iceberg is below the surface?`,
 h:[`A floating object displaces its own weight of water.`,
    `Weight of iceberg = ρ_ice V g; upthrust = ρ_sea V_sub g.`],
 a:`<p>ρ_ice V = ρ_sea V_sub, so V_sub/V = 920/1025 ≈ <b>0.90</b>: about 90% is under water and only 10% shows: "the tip of the iceberg".</p><p>In fresh water (1000 kg/m³) it would be 92% submerged. Ice floats at all because water expands by about 9% when it freezes, which is unusual; most solids are denser than their liquids.</p>`,
 f:[[`If an ice cube melts in a glass of fresh water, does the level change?`,`No: the floating ice displaces exactly its own mass of water, which is the water it turns into.`],
    [`Why does melting land ice raise sea levels when melting sea ice does not?`,`Land ice is not floating, so it is not already displacing seawater; when it melts, it adds water to the sea.`]]},
h3:{t:5,l:2,q:`A pressure cooker runs at 1 atmosphere above atmospheric pressure. Its lid has a diameter of 22 cm. What force does the steam exert on the lid, and roughly what temperature does the water boil at?`,
 h:[`Excess pressure 1 atm ≈ 1.0 × 10⁵ Pa. Force = pressure × area.`,
    `Boiling point rises with pressure: at 2 atm absolute, water boils at about 120 °C.`],
 a:`<p>Area = π × 0.11² ≈ 0.038 m². Force ≈ 1.0 × 10⁵ × 0.038 ≈ <b>3.8 kN</b>, the weight of about 390 kg. That is why the lid locks and has a safety valve.</p><p>At 2 atm absolute, water boils at about <b>120 °C</b>. Reaction rates roughly double for every 10 °C, so food cooks about 3–4 times faster.</p>`,
 f:[[`Why must you never force open a pressure cooker while it is hot?`,`The water is above 100 °C; releasing the pressure suddenly makes it boil violently and spray out.`],
    [`What is the boiling point at the top of Everest (about 0.33 atm)?`,`About 70 °C, which is why it is hard to cook properly there.`]]},
h4:{t:5,l:3,q:`You leave a fridge door open in a sealed, insulated 60 m³ room. The fridge draws 100 W of electricity and pumps 300 W of heat. What happens to the room temperature in 10 hours? (air: 1.2 kg/m³, c = 1000 J kg⁻¹ K⁻¹)`,
 h:[`With the door open, the heat pumped out of the inside goes straight back into the room. What is the net heat added?`,
    `Energy conservation: all the electrical energy ends up as heat in the room.`],
 a:`<p>The fridge removes 300 W from its inside (which is the room) and dumps 400 W out of the back. Net heating = <b>100 W</b>, the electrical input.</p><p>In 10 hours: 100 × 36 000 = 3.6 MJ. Mass of air = 72 kg, so ΔT = 3.6 × 10⁶ / (72 × 1000) = <b>50 K</b>, if only the air absorbed it. In reality walls and furniture soak up most of it, so the rise is a few degrees, but the room definitely warms up.</p><p>Tutors want energy conservation: a fridge moves heat, it does not destroy it.</p>`,
 f:[[`How does an air conditioner avoid this problem?`,`It dumps its heat outside the room, through an outdoor unit or a pipe through the wall.`],
    [`What is the coefficient of performance of this fridge?`,`Heat removed / work in = 300/100 = 3.`]]},
h5:{t:5,l:2,q:`Compare the heat delivered to your skin (at 37 °C) by 1 g of steam at 100 °C condensing and cooling to 37 °C, with 1 g of air at 200 °C cooling to 37 °C. (latent heat of water 2.26 MJ/kg, c_water = 4200, c_air = 1000 J kg⁻¹ K⁻¹)`,
 h:[`Steam: latent heat released on condensing, plus heat from the water cooling from 100 °C to 37 °C.`,
    `Air: only mcΔT.`],
 a:`<p>Steam: 0.001 × 2.26 × 10⁶ + 0.001 × 4200 × 63 ≈ 2260 + 265 ≈ <b>2500 J</b>.</p><p>Air: 0.001 × 1000 × 163 ≈ <b>160 J</b>. The steam delivers about <b>15 times</b> as much.</p><p>Also, steam condenses directly on the skin and keeps coming, while hot air is a poor conductor and a thin cool layer forms next to your hand. That is why you can reach briefly into a 200 °C oven but steam scalds instantly.</p>`,
 f:[[`Why do cooks wear thick, dry oven gloves rather than damp ones?`,`Water in a damp glove turns to steam and conducts heat much better than dry fabric full of air.`],
    [`How much energy does it take to turn 1 kg of water at 20 °C into steam?`,`4200 × 80 + 2.26 × 10⁶ ≈ 2.6 MJ; the boiling part is over 85% of it.`]]},
h6:{t:5,l:2,q:`A 300 g bowl of soup at 80 °C cools mainly by evaporation when you blow on it. What mass of water must evaporate to cool it by 20 K? (c = 4200 J kg⁻¹ K⁻¹, latent heat of vaporisation about 2.3 MJ/kg)`,
 h:[`Heat lost by the soup = mcΔT.`,
    `This heat supplies the latent heat of the evaporated water.`],
 a:`<p>Heat lost = 0.3 × 4200 × 20 = 25 200 J. Mass evaporated = 25 200 / 2.3 × 10⁶ ≈ <b>11 g</b>, only about 4% of the soup.</p><p>Blowing helps because it sweeps away the humid air just above the surface, so evaporation continues quickly, and it brings cooler air for convection.</p>`,
 f:[[`Why does the soup cool faster in a wide bowl than in a mug?`,`The larger surface area allows more evaporation and heat loss per second.`],
    [`Why does hot soup cool faster at first and then more slowly?`,`The rate of heat loss depends on the temperature difference with the room, which shrinks as it cools.`]]},
q3:{t:5,l:1,q:`How much ice at 0 °C must you add to 330 mL of drink at 25 °C to cool it to 5 °C? (c = 4200 J kg⁻¹ K⁻¹, latent heat of fusion 334 kJ/kg)`,
 h:[`Heat lost by the drink = heat gained by the ice.`,
    `The ice first melts (latent heat), then the meltwater warms from 0 °C to 5 °C.`],
 a:`<p>Drink: 0.33 × 4200 × 20 ≈ 27 700 J lost.</p><p>Each kilogram of ice takes 334 000 + 4200 × 5 = 355 000 J. Mass = 27 700/355 000 ≈ <b>78 g</b>, about four or five ice cubes.</p><p>Melting does most of the work: the latent heat is 16 times the energy needed to warm the meltwater by 5 K.</p>`,
 f:[[`Why do ice cubes cool a drink much better than the same mass of cold water at 0 °C?`,`Melting absorbs 334 kJ/kg; water at 0 °C only absorbs 4.2 kJ/kg per kelvin of warming.`],
    [`Why can you see your breath on a cold day?`,`The water vapour in your breath cools below its dew point in the cold air and condenses into tiny droplets.`]]},
y3:{t:5,l:3,q:`Water expands by about 9% when it freezes. Water's bulk modulus is about 2 GPa (the pressure needed for a fractional volume change of 1). Estimate the pressure if water froze in a completely rigid sealed pipe. Why do pipes burst?`,
 h:[`Bulk modulus K = pressure / (fractional volume change). The ice must be squeezed back by about 9%.`,
    `Compare your answer with atmospheric pressure (10⁵ Pa) and the few tens of atmospheres a copper pipe can take.`],
 a:`<p>p ≈ K × ΔV/V = 2 × 10⁹ × 0.09 ≈ <b>2 × 10⁸ Pa</b>, about 2000 atmospheres. (In reality ice changes to denser forms at roughly this pressure, which caps it.)</p><p>A domestic pipe bursts at perhaps 50–100 atmospheres, so long before this. Often the split happens where water is still liquid: ice plugs trap water between them and the pressure builds there.</p>`,
 f:[[`Why does lagging pipes help, even though insulation produces no heat?`,`It slows heat loss so the water takes much longer to reach 0 °C, often long enough to get through a cold night.`],
    [`Why do lakes freeze from the top down?`,`Water is densest at 4 °C, so colder water and ice float on top, insulating the water below.`]]},
y4:{t:7,l:2,q:`A popcorn kernel of 0.15 g contains about 14% water. If all that water became steam at 180 °C and atmospheric pressure, what volume would it occupy? Compare with a popped kernel of about 2 cm³. (R = 8.3 J mol⁻¹ K⁻¹, water 18 g/mol)`,
 h:[`Find the number of moles of water.`,
    `pV = nRT with T = 453 K and p = 1.0 × 10⁵ Pa.`],
 a:`<p>Water = 0.14 × 0.15 = 0.021 g = 1.2 × 10⁻³ mol.</p><p>V = nRT/p = 1.2 × 10⁻³ × 8.3 × 453 / 10⁵ ≈ 4.5 × 10⁻⁵ m³ = <b>45 cm³</b>, over 20 times the popped volume.</p><p>So there is plenty of steam to puff up the starch, even though most of it escapes. The tough hull keeps the water liquid well above 100 °C until the pressure (about 9 atmospheres) bursts it.</p>`,
 f:[[`Why do some kernels never pop?`,`Their hulls are cracked or they have dried out, so steam leaks away gradually and pressure never builds.`],
    [`How is this related to a pressure cooker?`,`Both raise the boiling point by keeping the pressure high.`]]},
u5:{t:5,l:3,q:`(University level) 1000 J of heat flows from a hot block at 400 K to a cold block at 300 K. Calculate the entropy change of each block and of the whole system. What does the sign tell you?`,
 h:[`For heat Q flowing in or out at (roughly constant) temperature T, ΔS = Q/T.`,
    `The hot block loses heat (negative), the cold one gains it (positive).`],
 a:`<p>Hot block: ΔS = −1000/400 = −2.5 J/K. Cold block: ΔS = +1000/300 = +3.33 J/K.</p><p>Total: <b>+0.83 J/K</b>. Positive, as the second law requires: heat flowing from hot to cold increases the total entropy, so it happens spontaneously. The reverse flow would give −0.83 J/K, which never happens on its own.</p>`,
 f:[[`What is the maximum efficiency of an engine working between 400 K and 300 K?`,`The Carnot efficiency 1 − 300/400 = 25%.`],
    [`Why does a fridge not break the second law?`,`It uses work, and dumps more heat into the room than it removes, so the total entropy still increases.`]]},
/* ---- waves ---- */
w4:{t:3,l:2,q:`Sound of 500 Hz and green light of 500 nm both pass through a 0.9 m doorway. Using sinθ ≈ λ/a for the spread of the central beam, compare how much each spreads. Why can you hear round a corner but not see round it? (speed of sound 340 m/s)`,
 h:[`Find the wavelength of the sound from v = fλ.`,
    `Compare λ/a for each. When λ/a is close to 1, the wave spreads out a lot.`],
 a:`<p>Sound: λ = 340/500 = 0.68 m, so sinθ ≈ 0.68/0.9 ≈ 0.76 and θ ≈ <b>50°</b>: it spreads widely round the corner.</p><p>Light: λ/a = 5 × 10⁻⁷ / 0.9 ≈ 5.6 × 10⁻⁷, θ ≈ <b>0.00003°</b>: it carries straight on, leaving a sharp shadow.</p><p>Diffraction is significant only when the gap is comparable to the wavelength; for light, that means gaps of micrometres.</p>`,
 f:[[`Why does music from a party next door sound bass-heavy through a wall or door?`,`Low frequencies have long wavelengths, diffract round obstacles more and are absorbed less by walls.`],
    [`How narrow would a slit need to be for 500 nm light to spread by 30° each side?`,`sin30° = 0.5 = λ/a, so a = 1 μm.`]]},
w5:{t:3,l:2,q:`A guitar string 0.65 m long with mass per unit length 5.0 g/m is under a tension of 70 N. Find the frequency of its fundamental. What tension would raise the note by an octave (double the frequency)?`,
 h:[`Wave speed on a string: v = √(T/μ).`,
    `The fundamental has a wavelength of 2L, so f = v/2L.`],
 a:`<p>v = √(70/0.005) = √14 000 ≈ 118 m/s. f = v/2L = 118/1.3 ≈ <b>91 Hz</b> (close to a low F♯ on a guitar).</p><p>Since f ∝ √T, doubling f needs <b>4 times the tension, 280 N</b>, which would probably snap the string. Guitarists press the string at the 12th fret instead, halving L.</p>`,
 f:[[`Why are bass strings thicker?`,`A larger μ gives a lower wave speed, so a low note at a sensible tension and length.`],
    [`What frequency does pressing at the 12th fret (halfway) give?`,`Halving L doubles f: about 182 Hz.`]]},
w6:{t:3,l:3,q:`Noise-cancelling headphones play an inverted copy of outside noise. Suppose the timing is off so the cancelling wave is shifted by the equivalent of 1 cm of path. Compare the leftover sound for a 100 Hz hum and a 3000 Hz voice. (v = 340 m/s; two equal waves with phase difference φ add to amplitude 2A sin(φ/2) when one is inverted.)`,
 h:[`Find λ for each frequency, then the phase error φ = 2π × (1 cm)/λ.`,
    `Leftover amplitude as a fraction of the original = 2 sin(φ/2).`],
 a:`<p>100 Hz: λ = 3.4 m; φ = 2π × 0.01/3.4 ≈ 0.018 rad; leftover ≈ 2 sin(0.009) ≈ <b>1.8%</b> of the amplitude: excellent cancellation.</p><p>3000 Hz: λ = 11 cm; φ ≈ 0.55 rad; leftover ≈ 2 sin(0.27) ≈ <b>54%</b>: hardly any cancellation.</p><p>That is why the headphones are great at engine hum but poor at voices, and why they also use padding to block high frequencies passively.</p>`,
 f:[[`Why is the cancellation worse if your head moves inside the headphones?`,`The path from the microphone to your eardrum changes, adding more phase error, which matters most at short wavelengths.`],
    [`Where does the energy of the cancelled sound go?`,`The speaker does work against the incoming pressure wave; the energy goes into the speaker and its circuit, and less sound energy reaches the ear.`]]},
n6:{t:3,l:1,q:`A seashell acts roughly like a tube about 10 cm long, closed at one end. Estimate the frequency it resonates at, which you hear as the "sea". (speed of sound 340 m/s)`,
 h:[`For a tube closed at one end, the fundamental has a quarter of a wavelength in the tube.`,
    `λ = 4L, then f = v/λ.`],
 a:`<p>λ = 4 × 0.10 = 0.4 m, so f = 340/0.4 ≈ <b>850 Hz</b>. The shell picks out and amplifies background noise near its resonant frequencies, which sounds like a gentle roar.</p><p>A bigger shell resonates at a lower pitch, which you can test with cups and glasses too. Real shells are not neat tubes, so they have several broad resonances.</p>`,
 f:[[`What would the next resonance be?`,`For a closed tube only odd harmonics occur: 3 × 850 ≈ 2550 Hz.`],
    [`Why does the "sea" sound go away in a soundproof room?`,`There is no background noise for the shell to amplify; it is not producing sound itself.`]]},
p3:{t:3,l:1,q:`You see lightning and hear the thunder 6 seconds later. How far away was the strike? How much of the delay is due to the light? (speed of sound 340 m/s)`,
 h:[`Light arrives almost instantly. Distance = speed of sound × time.`,
    `Work out the light's travel time for the same distance.`],
 a:`<p>d = 340 × 6 ≈ <b>2 km</b> (a handy rule: 3 seconds per kilometre).</p><p>Light takes 2000 / 3 × 10⁸ ≈ 7 microseconds: utterly negligible. So the delay is all due to sound, and the method works well.</p><p>Thunder rumbles because sound arrives from different parts of a channel several kilometres long, at different times.</p>`,
 f:[[`If the gap between flash and bang is getting shorter, what does it mean?`,`The storm is getting closer.`],
    [`Why is thunder rarely heard more than about 15 km away?`,`The sound spreads out and is absorbed, and the air's temperature changes refract it upwards, over your head.`]]},
q4:{t:3,l:2,q:`The speed of sound in helium is about 1000 m/s, compared with 340 m/s in air. After breathing helium, a resonance of your vocal tract at 500 Hz moves to what frequency? Does your voice's actual pitch change?`,
 h:[`The vocal tract resonances depend on its size and the speed of sound: f = v/λ with λ fixed by the tract's length.`,
    `The pitch is set by how fast your vocal folds vibrate, which helium barely changes.`],
 a:`<p>λ is fixed by the size of your vocal tract, so f ∝ v: 500 × 1000/340 ≈ <b>1470 Hz</b>.</p><p>The fundamental pitch (from the vocal folds) hardly changes. What changes are the resonances (formants), which shape the tone, so the voice sounds squeaky and thin rather than truly higher.</p>`,
 f:[[`What would breathing sulfur hexafluoride (sound speed about 130 m/s) do?`,`Lower the resonances by a factor of about 2.6, giving a deep, booming voice.`],
    [`Why is sound faster in helium?`,`At the same temperature, lighter molecules move faster: v ∝ √(γRT/M), and helium's molar mass is about 7 times smaller than air's.`]]},
r4:{t:3,l:2,q:`Light passes from water (n = 1.33) into air at 40° to the normal. Find the angle in air. Then find the critical angle, and the apparent depth of a pool 2.0 m deep viewed from directly above.`,
 h:[`Snell's law: n₁ sinθ₁ = n₂ sinθ₂.`,
    `Critical angle: sinθ_c = 1/n. For viewing from directly above, apparent depth ≈ real depth / n.`],
 a:`<p>sinθ_air = 1.33 × sin40° = 1.33 × 0.643 ≈ 0.855, so θ ≈ <b>59°</b>.</p><p>Critical angle: sinθ_c = 1/1.33, so <b>θ_c ≈ 49°</b>. Rays hitting the surface at more than 49° from the normal are totally internally reflected.</p><p>Apparent depth = 2.0/1.33 ≈ <b>1.5 m</b>: pools look shallower than they are, which is a real safety issue.</p>`,
 f:[[`Why is everything blurry when you open your eyes underwater?`,`Your cornea does most of the focusing because of the big refractive-index change from air to cornea; in water the change is tiny, so the eye cannot focus.`],
    [`Why do goggles fix it?`,`They keep a layer of air in front of the eye, restoring the air–cornea boundary.`]]},
s3:{t:3,l:2,q:`A shower cubicle is 2.4 m tall. Treating it as a pipe with hard surfaces at both ends, find the frequencies of the lowest three standing waves between floor and ceiling. Why does singing sound better in the shower? (speed of sound 340 m/s)`,
 h:[`Hard surfaces at both ends: the length holds a whole number of half-wavelengths, L = nλ/2.`,
    `f_n = nv/2L.`],
 a:`<p>f₁ = 340/4.8 ≈ <b>71 Hz</b>, then <b>142 Hz</b> and <b>213 Hz</b>, and so on. The width and depth (about 1 m) add resonances at about 170 Hz and its multiples.</p><p>Many of these lie in the range of a singing voice, so notes near them are reinforced. Hard tiles also reflect sound well, adding reverberation that smooths out wobbles in pitch.</p>`,
 f:[[`Why do bathrooms sound different from carpeted bedrooms?`,`Carpets, curtains and soft furniture absorb sound, so there is far less reverberation.`],
    [`What would the lowest resonance be in a 10 m long hall?`,`340/20 = 17 Hz, below the range of hearing.`]]},
c3:{t:3,l:2,q:`A 440 Hz tuning fork is held over a tube closed at the bottom by water. As the water is lowered, the first loud resonance occurs when the air column is 18.5 cm long. Estimate the speed of sound. Where does the extra loudness come from?`,
 h:[`At the first resonance the air column holds about a quarter of a wavelength.`,
    `In practice the antinode is a little above the open end: an "end correction" of about 0.6 × radius. Ignore it first, then think about its effect.`],
 a:`<p>λ ≈ 4 × 0.185 = 0.74 m, so v ≈ 440 × 0.74 ≈ <b>326 m/s</b>. With an end correction of about 1 cm (for a 3 cm wide tube), λ ≈ 0.78 m and v ≈ <b>343 m/s</b>, matching the accepted value.</p><p>No energy is created: the resonating air column couples the fork's vibration to the air much better, so energy is radiated faster and the fork dies away sooner.</p>`,
 f:[[`At what length would the next resonance be?`,`Three quarters of a wavelength: about 0.75 × 0.78 − 0.01 ≈ 0.57 m.`],
    [`How could you eliminate the end correction from your result?`,`Measure the first two resonance lengths: their difference is exactly half a wavelength.`]]},
/* ---- electricity and magnetism ---- */
x3:{t:4,l:1,q:`An 800 W microwave oven heats 250 g of water from 20 °C. How long until it boils, if 70% of the power reaches the water? The microwaves have a frequency of 2.45 GHz: what is their wavelength, and why do ovens have turntables? (c = 4200 J kg⁻¹ K⁻¹)`,
 h:[`Energy needed = mcΔT; useful power = 0.7 × 800 W.`,
    `λ = c/f. Standing waves form inside the metal box: how far apart are the hot spots?`],
 a:`<p>Energy = 0.25 × 4200 × 80 = 84 kJ. Time = 84 000 / 560 ≈ <b>150 s</b>, about 2½ minutes.</p><p>λ = 3 × 10⁸ / 2.45 × 10⁹ ≈ <b>12 cm</b>. Standing waves give hot spots (antinodes) every half wavelength, about 6 cm apart, so the turntable moves food through them to heat it evenly.</p><p>A classic experiment: remove the turntable, heat a plate of cheese, and measure the gap between melted spots to find the speed of light.</p>`,
 f:[[`If melted spots on the cheese are 6.1 cm apart, what speed of light does that give?`,`λ = 12.2 cm, so c = fλ = 2.45 × 10⁹ × 0.122 ≈ 3.0 × 10⁸ m/s.`],
    [`Why doesn't the microwave radiation escape through the window?`,`The metal mesh has holes of a few millimetres, much smaller than the 12 cm wavelength, so it acts as a solid metal wall for microwaves but lets light through.`]]},
x4:{t:4,l:3,q:`Two identical 3 g balloons are rubbed and hung from the same point on threads 0.5 m long. They repel and settle 20 cm apart. Estimate the charge on each. (g = 10 m/s², 1/(4πε₀) = 9 × 10⁹ N m² C⁻²)`,
 h:[`Each thread makes an angle θ with the vertical where sinθ = 0.1/0.5. Draw the three forces on one balloon: weight, tension, electric force.`,
    `Horizontal force F = mg tanθ, then Coulomb's law F = kQ²/r².`],
 a:`<p>sinθ = 0.2, so tanθ ≈ 0.204. F = mg tanθ = 0.003 × 10 × 0.204 ≈ 6.1 × 10⁻³ N.</p><p>Q² = F r²/k = 6.1 × 10⁻³ × 0.04 / 9 × 10⁹ ≈ 2.7 × 10⁻¹⁴, so <b>Q ≈ 1.6 × 10⁻⁷ C</b>, about 10¹² extra electrons.</p><p>Sanity check: tiny compared with a coulomb, as static charges always are, but the forces are noticeable because the balloons are so light.</p>`,
 f:[[`How can a charged balloon stick to a neutral wall?`,`It polarises the wall: opposite charges in the wall's molecules shift slightly closer, and the attraction to the nearer charges beats the repulsion from the further ones.`],
    [`Why does the charge leak away faster on a humid day?`,`A thin film of water on surfaces conducts, letting the charge drain away.`]]},
x5:{t:4,l:2,q:`A power station sends 500 MW along cables with a total resistance of 5 Ω. Compare the power lost if it is sent at 400 kV and at 25 kV.`,
 h:[`Current I = P/V.`,
    `Power lost in the cables = I²R.`],
 a:`<p>At 400 kV: I = 5 × 10⁸ / 4 × 10⁵ = 1250 A. Loss = 1250² × 5 ≈ <b>7.8 MW</b>, about 1.6%.</p><p>At 25 kV: I = 20 000 A. Loss = (2 × 10⁴)² × 5 = <b>2000 MW</b>, four times the power being sent, so it is impossible.</p><p>Loss ∝ 1/V², so raising the voltage 16 times cuts the loss 256 times. That is why transformers and high-voltage lines are used.</p>`,
 f:[[`Why is electricity transmitted as ac rather than dc?`,`Transformers make stepping ac up and down simple and efficient. (Very long links now sometimes use high-voltage dc with power electronics.)`],
    [`What is the pd across the cables at 400 kV?`,`IR = 1250 × 5 = 6250 V, a small fraction of 400 kV.`]]},
n7:{t:4,l:2,q:`A compass sits 5 cm directly below a long straight wire running north–south. When 10 A flows, how far does the needle swing? (the field of a wire is B = μ₀I/(2πr), μ₀ = 4π × 10⁻⁷ T m A⁻¹; the Earth's horizontal field is about 2 × 10⁻⁵ T)`,
 h:[`Calculate the wire's field at the compass; it points east or west, at right angles to the Earth's field.`,
    `The needle lines up with the resultant: tanθ = B_wire / B_Earth.`],
 a:`<p>B_wire = 4π × 10⁻⁷ × 10 / (2π × 0.05) = <b>4 × 10⁻⁵ T</b>, twice the Earth's horizontal field.</p><p>tanθ = 4/2 = 2, so the needle swings by about <b>63°</b> from north. This is Ørsted's 1820 experiment, the first evidence linking electricity and magnetism.</p>`,
 f:[[`What happens if the current is reversed?`,`The needle swings 63° the other way.`],
    [`What would a compass do at the north magnetic pole?`,`The field there points almost straight down, so the horizontal part is tiny and the needle wanders; a dip needle would point vertically down.`]]},
p4:{t:4,l:2,q:`A TV remote uses an infrared LED at 940 nm. Find the energy of each photon in joules and in electronvolts. If it emits 10 mW, how many photons per second is that? (h = 6.6 × 10⁻³⁴ J s, c = 3 × 10⁸ m/s, e = 1.6 × 10⁻¹⁹ C)`,
 h:[`E = hc/λ.`,
    `Photons per second = power / energy per photon.`],
 a:`<p>E = 6.6 × 10⁻³⁴ × 3 × 10⁸ / 9.4 × 10⁻⁷ ≈ <b>2.1 × 10⁻¹⁹ J ≈ 1.3 eV</b>. So the LED needs a forward voltage of at least about 1.3 V, which is why two AA cells (3 V) are enough.</p><p>Photons per second = 0.01 / 2.1 × 10⁻¹⁹ ≈ <b>5 × 10¹⁶</b>. The remote still works when aimed at a wall because the wall scatters enough of these photons to reach the TV's sensor.</p>`,
 f:[[`How can you see whether a remote is working?`,`Look at it through a phone camera: the camera sensor detects infrared and shows the LED flashing.`],
    [`Would a blue LED (450 nm) need a higher or lower voltage?`,`Higher: about 2.8 eV per photon, so at least 2.8 V.`]]},
q2:{t:4,l:2,q:`A Van de Graaff dome is a sphere of radius 15 cm at 200 kV. Find the charge on it and the electric field at its surface. Air breaks down at about 3 × 10⁶ V/m: is it close to sparking? (1/(4πε₀) = 9 × 10⁹ N m² C⁻²)`,
 h:[`For a charged sphere, V = kQ/r.`,
    `The field at the surface is E = kQ/r² = V/r.`],
 a:`<p>Q = Vr/k = 2 × 10⁵ × 0.15 / 9 × 10⁹ ≈ <b>3.3 × 10⁻⁶ C</b>.</p><p>E = V/r = 2 × 10⁵ / 0.15 ≈ <b>1.3 × 10⁶ V/m</b>, about 45% of the breakdown field. Any sharp point (which concentrates the field) or a nearby earthed object will set off sparks.</p><p>Your hair stands on end when you touch it because each hair gets charge of the same sign and they repel.</p>`,
 f:[[`What is the largest voltage this dome could hold?`,`E_max r = 3 × 10⁶ × 0.15 = 450 kV; bigger domes reach higher voltages.`],
    [`Why does a 200 kV spark from the dome not kill you?`,`The total charge and energy are tiny (E = ½QV ≈ 0.3 J), so the current lasts microseconds.`]]},
r2:{t:4,l:2,q:`A camera flash charges a 100 μF capacitor to 300 V, then dumps it through the bulb in 1 ms. Find the energy stored, the average power of the flash, and the time constant if it charges through a 10 kΩ resistor.`,
 h:[`E = ½CV².`,
    `Average power = energy / time. Time constant = RC.`],
 a:`<p>E = ½ × 10⁻⁴ × 300² = <b>4.5 J</b>. Average power = 4.5 / 0.001 = <b>4.5 kW</b>, far more than the small battery could supply directly.</p><p>Time constant RC = 10⁴ × 10⁻⁴ = <b>1 s</b>, so it takes about 5 s to be nearly fully charged, which is why old flashes made you wait.</p><p>The capacitor's job is to store energy slowly and release it quickly.</p>`,
 f:[[`Where exactly is the energy stored?`,`In the electric field between the plates.`],
    [`What fraction of the energy remains after one time constant of discharging?`,`Charge falls to 1/e, and energy ∝ Q², so 1/e² ≈ 14% remains.`]]},
v1:{t:4,l:3,q:`An induction hob produces a field of peak 20 mT at 25 kHz through the base of a pan of area 0.02 m². Estimate the peak emf induced round the base. Why does it heat a steel pan but not your hand?`,
 h:[`For a sinusoidal field B = B₀ sin ωt through area A, the peak emf is B₀Aω.`,
    `ω = 2πf. Then think about the resistance of a metal pan compared with skin.`],
 a:`<p>Peak emf ≈ 0.02 × 0.02 × 2π × 25 000 ≈ <b>63 V</b>. The pan base has a very low resistance, so large eddy currents flow and heat it (P = V²/R is big).</p><p>Your hand is a poor conductor, so only tiny currents flow: negligible heating. The hob works best with iron or steel pans, which also add magnetic hysteresis heating, and have a higher resistance at this frequency than copper or aluminium.</p>`,
 f:[[`Why does the hob use 25 kHz rather than 50 Hz mains frequency?`,`The emf is proportional to frequency, so a high frequency gives much more heating; it is also above the range of hearing.`],
    [`Why doesn't the glass top get hot (except from the pan)?`,`Glass is an insulator, so no eddy currents flow in it.`]]},
y2:{t:4,l:3,q:`On a fine day there is an electric field of about 100 V/m near the ground. Treating the Earth as a conductor with surface charge density σ, where E = σ/ε₀, estimate the total charge on the Earth. Why don't you get a shock from the 170 V between your head and feet? (ε₀ = 8.85 × 10⁻¹² F/m, Earth's surface area 5.1 × 10¹⁴ m²)`,
 h:[`σ = ε₀E, then total charge = σ × area.`,
    `You are a far better conductor than air. What does a conductor do to the field around it?`],
 a:`<p>σ = 8.85 × 10⁻¹² × 100 ≈ 8.9 × 10⁻¹⁰ C/m². Total ≈ 8.9 × 10⁻¹⁰ × 5.1 × 10¹⁴ ≈ <b>4.5 × 10⁵ C</b> (negative).</p><p>You are an equipotential: charge flows almost instantly until your body is at the ground's potential, and the field lines end on your head rather than passing through you. So there is no pd across your body.</p>`,
 f:[[`Why doesn't the Earth's charge simply leak away through the air?`,`It does, steadily (about 1 kA worldwide), but thunderstorms around the globe keep recharging it.`],
    [`How long would the charge last without thunderstorms?`,`4.5 × 10⁵ C / 1000 A ≈ 450 s, about 8 minutes.`]]},
/* ---- gravity and astrophysics ---- */
a5:{t:6,l:2,q:`If the Sun collapsed into a black hole of the same mass, what radius would it have? What would happen to the Earth's orbit? (Schwarzschild radius R = 2GM/c², G = 6.7 × 10⁻¹¹ N m² kg⁻², M = 2.0 × 10³⁰ kg)`,
 h:[`Substitute into R = 2GM/c².`,
    `The force on the Earth is GMm/r². Which of these quantities change?`],
 a:`<p>R = 2 × 6.7 × 10⁻¹¹ × 2.0 × 10³⁰ / (3 × 10⁸)² ≈ <b>3 km</b>.</p><p>The Earth's orbit would <b>not change</b>: the force depends only on M and r, both the same. Outside a spherical mass, gravity is the same as if all the mass were at the centre. The Earth would, however, go dark and freeze.</p>`,
 f:[[`What would the Earth's Schwarzschild radius be?`,`About 9 mm.`],
    [`Why can't anything escape from inside the Schwarzschild radius?`,`Setting the escape speed √(2GM/r) equal to c gives exactly R = 2GM/c², so inside it the escape speed would exceed the speed of light (this Newtonian argument happens to give the correct answer).`]]},
a6:{t:6,l:3,q:`The tallest mountains a planet can support are limited by the rock at the base being crushed, at a pressure ρgh. If Earth's limit is about 10 km, estimate the limit on Mars, where g = 3.7 N/kg. Why are large bodies round?`,
 h:[`The crushing pressure is set by the rock's strength, roughly the same on both planets.`,
    `ρgh = constant, so h ∝ 1/g.`],
 a:`<p>h_Mars ≈ 10 × 9.8/3.7 ≈ <b>26 km</b>. Olympus Mons on Mars is about 22 km high, so the estimate is good.</p><p>On a large enough body, gravity overwhelms the strength of rock and the surface sags into a sphere, the shape with the lowest gravitational potential energy. For rocky bodies this happens above a few hundred kilometres across, which is why small asteroids are lumpy.</p>`,
 f:[[`How tall could mountains be on the Moon (g = 1.6 N/kg)?`,`About 10 × 9.8/1.6 ≈ 60 km in principle, although no process has built ones that high.`],
    [`Why are fast-spinning planets slightly flattened?`,`The rotation reduces the effective gravity at the equator, so the equator bulges out.`]]},
p6:{t:6,l:2,q:`The hydrogen spectrum has a red line from electrons dropping from level 3 to level 2. The energy levels are E_n = −13.6/n² eV. Find the photon energy and wavelength. How does this show the Sun contains hydrogen? (h = 6.6 × 10⁻³⁴ J s, e = 1.6 × 10⁻¹⁹ C)`,
 h:[`ΔE = 13.6 (1/4 − 1/9) eV.`,
    `Convert to joules, then λ = hc/E.`],
 a:`<p>ΔE = 13.6 × 5/36 ≈ <b>1.89 eV</b> = 3.0 × 10⁻¹⁹ J. λ = hc/E = 6.6 × 10⁻³⁴ × 3 × 10⁸ / 3.0 × 10⁻¹⁹ ≈ <b>655 nm</b>: red (the measured value is 656 nm).</p><p>The Sun's spectrum has dark absorption lines at exactly this and the other hydrogen wavelengths: hydrogen in its outer layers absorbs those photons. Every element has its own fingerprint of lines, which is how we know what stars are made of.</p>`,
 f:[[`Why is the line dark in the Sun's spectrum rather than bright?`,`Cooler gas in front of the hotter surface absorbs these wavelengths and re-emits them in all directions, so less reaches us along the line of sight.`],
    [`What is the ionisation energy of hydrogen from the ground state?`,`13.6 eV.`]]},
v4:{t:6,l:3,q:`The Sun has an apparent magnitude of −26.7 and Sirius, the brightest star, −1.5. A difference of 5 magnitudes is a factor of 100 in brightness. How many times brighter does the Sun appear? Why can't we see Sirius in the daytime?`,
 h:[`The brightness ratio is 100^(Δm/5) = 10^(0.4Δm).`,
    `Compare the light from Sirius with the light scattered by the blue sky around it.`],
 a:`<p>Δm = 25.2, so the ratio is 10^(0.4 × 25.2) = 10^(10.1) ≈ <b>1.3 × 10¹⁰</b>.</p><p>The daytime sky scatters a small fraction of that sunlight towards us from every direction, and the patch of sky around Sirius is far brighter than Sirius itself, so its light is drowned out. The stars are still there; from the Moon, with no air to scatter light, you can see them in sunlight.</p>`,
 f:[[`Why can Venus sometimes be seen in daylight?`,`At magnitude about −4.5 it is around 16 times brighter than Sirius, enough to stand out from a clear blue sky if you know where to look.`],
    [`How much brighter does a magnitude 1 star appear than a magnitude 6 star?`,`5 magnitudes: 100 times.`]]},
/* ---- everyday physics ---- */
d2:{t:7,l:1,q:`A 2.2 kW kettle has just boiled 1 litre of water. If it failed to switch off, how long would it take to boil dry? Compare with the time to heat the water from 20 °C to 100 °C. (latent heat of vaporisation 2.26 MJ/kg, c = 4200 J kg⁻¹ K⁻¹)`,
 h:[`Energy to boil off 1 kg = mL.`,
    `Energy to heat it = mcΔT. Divide each by the power.`],
 a:`<p>Boiling dry: 2.26 × 10⁶ / 2200 ≈ 1030 s ≈ <b>17 minutes</b>.</p><p>Heating from 20 °C: 4200 × 80 = 336 kJ, taking about 150 s ≈ <b>2.5 minutes</b>. Turning the water into steam needs nearly 7 times as much energy as heating it to boiling point.</p><p>Kettles get noisy just before boiling because bubbles of steam form at the hot element and collapse in the cooler water above; once all the water is hot, they rise to the top and the noise dies down.</p>`,
 f:[[`Why is the latent heat of vaporisation so much bigger than the latent heat of melting (334 kJ/kg)?`,`Boiling separates molecules completely, breaking all the bonds between them and pushing back the atmosphere; melting only loosens them.`],
    [`Why does a kettle switch off by itself?`,`Steam is directed onto a bimetallic strip (or sensor) that bends when hot and opens the switch.`]]},
v3:{t:7,l:2,q:`The fraction of light reflected at a boundary at normal incidence is R = ((n₁ − n₂)/(n₁ + n₂))². Cotton fibres have n ≈ 1.5. Compare the reflection at a fibre surrounded by air (n = 1.0) and by water (n = 1.33). Why does a wet T-shirt look darker?`,
 h:[`Substitute both pairs of refractive indices.`,
    `A dry fabric looks pale because many fibre surfaces each reflect a bit of light back out. What happens if each surface reflects much less?`],
 a:`<p>Air–fibre: R = (0.5/2.5)² = <b>4%</b>. Water–fibre: R = (0.17/2.83)² ≈ <b>0.36%</b>, about 11 times less.</p><p>A dry fabric scatters light back out through repeated reflections at many fibre surfaces, so it looks pale. When wet, light goes deeper into the fabric and has more chances of being absorbed by the dye, so it looks darker and more saturated (and sometimes see-through).</p>`,
 f:[[`Why does wet sand look darker than dry sand?`,`The same reason: water between the grains reduces reflection at each surface, so more light is absorbed.`],
    [`Why do glasses have anti-reflective coatings?`,`A thin layer of intermediate refractive index (a quarter of a wavelength thick) makes the reflections from its two surfaces cancel, reducing glare.`]]},
};
PHY.forEach(q=>{q.f=q.f||PHY_FOLLOW[q.id]||[];});
PHY.forEach(q=>{const c=PHY_CALC[q.id];if(c)Object.assign(q,c,{calc:true});});
/* older questions whose worked answers are already numerical also count as calculations */
PHY.forEach(q=>{if(!q.calc&&(q.a.match(/\d+(\.\d+)?\s*×\s*10|=\s*[\d.]+|≈\s*[\d.]+/g)||[]).length>=2)q.calc=true;});
try{if(localStorage.getItem('phy-calc')!=='1'){const R=JSON.parse(localStorage.getItem('phy-ratings')||'{}');Object.keys(PHY_CALC).forEach(id=>delete R[id]);localStorage.setItem('phy-ratings',JSON.stringify(R));localStorage.setItem('phy-calc','1');}}catch(e){}

const PHY_SOURCES=[
 ['Oxford Physics mock interview pack (official)','https://www.physics.ox.ac.uk/system/files/file_attachments/mock%20interview%20pack%20211122.pdf'],
 ['University of Oxford: interviews and sample questions','https://www.ox.ac.uk/interviews'],
 ['Oxford PAT past papers (useful for interview practice)','https://www.physics.ox.ac.uk/study/undergraduates/how-apply/physics-aptitude-test/pat-past-papers']
];

/* ---------- state ---------- */
const RATE={got:['Got it','ok'],hint:['Needed hints','sk'],stuck:['Stuck','no']};
let phyFilter=-1, phyTick=null;
const phyRatings=()=>loadJSON('phy-ratings',{});
/* filter: -1 all, -2 calculations only, otherwise a topic index */
function phyPool(){return PHY.filter(q=>phyFilter===-1||(phyFilter===-2?q.calc:q.t===phyFilter));}
/* Spaced repetition: after rating, a question comes back in 1 day (Stuck), 3 days (Needed hints) or 7 days (Got it),
   and 21 days once you get it again on its next visit. Older ratings without a due date use the same gaps. */
const PHY_GAP={stuck:1,hint:3,got:7};
const phyDue=r=>r.d||(r.t+PHY_GAP[r.r]*864e5);
function phyDueList(pool){const R=phyRatings(),now=Date.now();return pool.filter(q=>R[q.id]&&phyDue(R[q.id])<=now);}
function phyRate(id,r){
  const R=phyRatings(),prev=R[id],gap=r==='got'&&prev&&prev.r==='got'?21:PHY_GAP[r];
  R[id]={r,t:Date.now(),d:Date.now()+gap*864e5};saveJSON('phy-ratings',R);
}
function phyNext(exclude){
  const R=phyRatings(),pool=phyPool().filter(q=>q.id!==exclude);
  if(!pool.length)return phyPool()[0];
  /* 1. due for review (stuck first) 2. never tried 3. whatever is due soonest */
  const order={stuck:0,hint:1,got:2};
  const due=phyDueList(pool).sort((a,b)=>order[R[a.id].r]-order[R[b.id].r]||phyDue(R[a.id])-phyDue(R[b.id]));
  if(due.length){const r0=R[due[0].id].r;return pick(due.filter(q=>R[q.id].r===r0));}
  const fresh=pool.filter(q=>!R[q.id]);if(fresh.length)return pick(fresh);
  return pool.slice().sort((a,b)=>phyDue(R[a.id])-phyDue(R[b.id]))[0];
}
const lvl=l=>'●'.repeat(l)+'○'.repeat(3-l);

function phyHome(){
  leave();
  const R=phyRatings(),pool=phyPool();
  const cnt={got:0,hint:0,stuck:0};pool.forEach(q=>{if(R[q.id])cnt[R[q.id].r]++;});
  const unseen=pool.length-cnt.got-cnt.hint-cnt.stuck,ndue=phyDueList(pool).length;
  app.innerHTML=
  '<div class="stack">'+
  '<div class="stack" style="gap:8px"><p class="eyebrow">Practice · not scored</p><h1>Physics interview</h1>'+
  '<p class="muted">Open-ended questions in the style of Oxford physics interviews. Think aloud, work on paper, use hints the way an interviewer would nudge you, then compare with the worked answer.</p></div>'+
  '<div class="chips">'+['All'].concat(PHY_TOPICS).map((n,i)=>'<button class="chip'+(phyFilter===i-1?' on':'')+'" data-t="'+(i-1)+'">'+n+'</button>').join('')+'<button class="chip'+(phyFilter===-2?' on':'')+'" data-t="-2">🧮 Calculations ('+PHY.filter(q=>q.calc).length+')</button></div>'+
  '<div class="facts four"><div class="fact"><b>'+unseen+'</b><span>new</span></div><div class="fact"><b class="no">'+cnt.stuck+'</b><span>stuck</span></div><div class="fact"><b class="sk">'+cnt.hint+'</b><span>hints</span></div><div class="fact"><b class="ok">'+cnt.got+'</b><span>got it</span></div></div>'+
  '<button class="btn" id="pnext">'+(ndue?'Review '+ndue+' due question'+(ndue===1?'':'s'):'Next question')+'</button>'+
  '<p class="note">Questions come back for review 1 day after "Stuck", 3 days after "Needed hints" and 7 days after "Got it" (then 21 days).</p>'+
  '<div class="card"><h2 style="margin-bottom:6px">All questions</h2>'+
   pool.map(q=>{const r=R[q.id],isDue=r&&phyDue(r)<=Date.now();return '<button class="qrow" data-id="'+q.id+'"><span class="mark '+(r?RATE[r.r][1]:'sk')+'">'+(r?(r.r==='got'?'✓':r.r==='hint'?'~':'✗'):'·')+'</span><span class="qt">'+q.q+(isDue?' <span class="badge">due</span>':'')+'</span><span class="lv">'+lvl(q.l)+'</span></button>';}).join('')+'</div>'+
  '<div class="card stack"><h2>Official resources</h2><ul class="src">'+PHY_SOURCES.map(s=>'<li><a href="'+s[1]+'" target="_blank" rel="noopener">'+s[0]+'</a></li>').join('')+'</ul>'+
   '<p class="note">Questions here are written for practice in the style tutors use; they are not official Oxford questions. Interviews reward clear reasoning and responding to hints far more than knowing the answer already.</p></div>'+
  '<button class="btn ghost" id="phome">Home</button>'+
  '</div>';
  app.querySelectorAll('.chip').forEach(b=>b.onclick=()=>{phyFilter=+b.dataset.t;phyHome();});
  app.querySelectorAll('.qrow').forEach(b=>b.onclick=()=>phyQuestion(PHY.find(q=>q.id===b.dataset.id)));
  document.getElementById('pnext').onclick=()=>phyQuestion(phyNext());
  document.getElementById('phome').onclick=home;
  window.scrollTo(0,0);
}

function phyQuestion(q){
  clearInterval(phyTick);setBack(phyHome);setScratch(true);
  let shown=0,end=0;
  app.innerHTML=
  '<div class="stack">'+
  '<div class="top"><span class="eyebrow">'+PHY_TOPICS[q.t]+' · '+lvl(q.l)+'</span><span class="timer" id="ptimer"></span></div>'+
  '<div class="card stack"><p class="prompt">'+q.q+'</p>'+qTools({prompt:q.q,right:'',wrong:[],explain:'',phyId:q.id},'Physics interview · '+PHY_TOPICS[q.t]+' ('+q.id+')',{noConf:true})+
   '<div id="hints" class="stack" style="gap:10px"></div>'+
   '<div id="ans"></div></div>'+
  '<div class="row2"><button class="btn ghost" id="ptime">Start 5 min timer</button><button class="btn ghost" id="phint">Hint 1 of '+q.h.length+'</button></div>'+
  '<button class="btn" id="pans">Show worked answer</button>'+
  '<div id="rate"></div>'+
  '<button class="btn ghost" id="pback">Back to questions</button>'+
  '</div>';
  const $=id=>document.getElementById(id);
  $('ptime').onclick=()=>{
    if(end){clearInterval(phyTick);end=0;$('ptimer').textContent='';$('ptime').textContent='Start 5 min timer';return;}
    end=Date.now()+300000;$('ptime').textContent='Stop timer';
    const up=()=>{const left=(end-Date.now())/1000,el=$('ptimer');if(!el){clearInterval(phyTick);return;}
      el.textContent=fmt(left);el.classList.toggle('low',left<=60);if(left<=0){clearInterval(phyTick);el.textContent='Time';}};
    up();phyTick=setInterval(up,250);
  };
  $('phint').onclick=()=>{
    if(shown>=q.h.length)return;
    $('hints').insertAdjacentHTML('beforeend','<div class="hint"><b>Hint '+(shown+1)+'</b><p>'+q.h[shown]+'</p></div>');
    shown++;
    $('phint').textContent=shown<q.h.length?'Hint '+(shown+1)+' of '+q.h.length:'No more hints';
    $('phint').disabled=shown>=q.h.length;
  };
  $('pans').onclick=()=>{
    $('ans').innerHTML='<div class="answer"><b>Worked answer</b>'+q.a+'</div>'+
      (q.f.length?'<div class="stack" style="gap:8px;margin-top:14px"><b>A tutor might then ask</b>'+
        q.f.map(f=>'<details class="fu"><summary>'+f[0]+'</summary><p>'+f[1]+'</p></details>').join('')+'</div>':'');
    $('pans').style.display='none';
    $('rate').innerHTML='<div class="card stack"><p class="prompt" style="font-size:1rem">How did you do?</p><div class="row3">'+
      Object.entries(RATE).map(([k,v])=>'<button class="btn ghost rate '+v[1]+'" data-r="'+k+'">'+v[0]+'</button>').join('')+'</div></div>';
    $('rate').querySelectorAll('.rate').forEach(b=>b.onclick=()=>{
      phyRate(q.id,b.dataset.r);
      phyQuestion(phyNext(q.id));
    });
    $('ans').scrollIntoView({behavior:'smooth',block:'start'});
  };
  $('pback').onclick=phyHome;
  window.scrollTo(0,0);
}
